/* Bài nghe hiểu bổ sung 4.47: nhiều tình huống, tăng dần độ dài, có ghi chú điểm chính. Nạp sau content-listen2.js. */
LC_SETS.push(...[{"id": "lc-201", "lvl": "A1", "kind": "conversation", "title": "Anna Orders a Chicken Sandwich", "script": [["Waiter", "Hello. Welcome. Can I help you?"], ["Anna", "Yes, please. I'd like a chicken sandwich."], ["Waiter", "Okay. Do you want a drink with it?"], ["Anna", "Yes. A cold tea, please. How much is it?"], ["Waiter", "The sandwich and the tea are six dollars."], ["Anna", "Here you are. Can I sit by the window?"], ["Waiter", "Yes, of course. Please sit down. I'll bring your lunch."], ["Anna", "Thank you very much. See you later."]], "qs": [{"q": "What is Anna doing?", "opts": ["Ordering lunch", "Cooking lunch", "Asking the way", "Buying a ticket"], "a": 0, "kind": "gist", "why": "Anna nói \"I'd like a chicken sandwich\", tức là cô ấy đang gọi bữa trưa.", "wrong": {"Cooking lunch": "Cô ấy không nấu ăn, chỉ gọi món.", "Asking the way": "Không có câu hỏi đường nào trong đoạn hội thoại.", "Buying a ticket": "Không nhắc đến vé."}}, {"q": "What drink does Anna want?", "opts": ["Hot coffee", "Cold tea", "Orange juice", "Water"], "a": 1, "kind": "detail", "why": "Anna nói \"A cold tea, please.\"", "wrong": {"Hot coffee": "Cô ấy không gọi cà phê.", "Orange juice": "Không nhắc đến nước cam.", "Water": "Cô ấy không gọi nước lọc."}}, {"q": "How much is the lunch?", "opts": ["Four dollars", "Five dollars", "Six dollars", "Sixteen dollars"], "a": 2, "kind": "number", "why": "Người phục vụ nói \"are six dollars\".", "wrong": {"Four dollars": "Giá không phải bốn đô.", "Five dollars": "Giá không phải năm đô.", "Sixteen dollars": "Sixteen (16) nghe giống six, nhưng người phục vụ nói six (6)."}}, {"q": "What will the waiter do next?", "opts": ["Close the window", "Sit down with Anna", "Go to the bank", "Bring Anna's lunch"], "a": 3, "kind": "next-step", "why": "Người phục vụ nói \"I'll bring your lunch.\"", "wrong": {"Close the window": "Anna là người ngồi cạnh cửa sổ, không ai đóng cửa.", "Sit down with Anna": "Người phục vụ mời Anna ngồi, không ngồi cùng.", "Go to the bank": "Không nhắc đến ngân hàng."}}], "notes": {"vocab": [["chicken sandwich", "bánh sandwich gà"], ["cold tea", "trà lạnh"], ["how much", "bao nhiêu tiền"], ["by the window", "cạnh cửa sổ"], ["here you are", "của bạn đây"]], "grammar": [["I'd like (lịch sự)", "I'd like a chicken sandwich", "Dùng I'd like để gọi món một cách lịch sự, nghĩa là tôi muốn."], ["Can I ... ? (xin phép)", "Can I sit by the window?", "Can I + động từ dùng để xin phép làm gì đó."]], "tips": ["Khi nghe hội thoại ở quán, hãy nghe món ăn và giá tiền trước.", "Chú ý số: six (6) và sixteen (16) nghe gần giống nhau."]}}, {"id": "lc-202", "lvl": "A1", "kind": "conversation", "title": "Tom Asks the Way to the Post Office", "script": [["Tom", "Excuse me. Where is the post office?"], ["Woman", "Go straight on this street."], ["Tom", "Straight. Okay. I understand."], ["Woman", "Then turn left at the bank. You can see it on the corner."], ["Tom", "Turn left at the bank. Is it far?"], ["Woman", "No, it's not far. It's five minutes from here."], ["Woman", "The post office is next to a big park."], ["Tom", "Great. Thanks a lot. Have a nice day. Goodbye!"]], "qs": [{"q": "What does Tom want?", "opts": ["To buy a bank card", "To find the post office", "To go to the park", "To meet a friend"], "a": 1, "kind": "gist", "why": "Tom hỏi \"Where is the post office?\".", "wrong": {"To buy a bank card": "Tom không nói về thẻ ngân hàng.", "To go to the park": "Công viên chỉ là nơi bưu điện nằm cạnh.", "To meet a friend": "Không nhắc đến gặp bạn."}}, {"q": "Where does Tom turn left?", "opts": ["At the school", "At the park", "At the shop", "At the bank"], "a": 3, "kind": "detail", "why": "Người phụ nữ nói \"turn left at the bank\".", "wrong": {"At the school": "Không nhắc đến trường học.", "At the park": "Công viên ở cạnh bưu điện, không phải chỗ rẽ trái.", "At the shop": "Không nhắc đến cửa hàng."}}, {"q": "How far is the post office?", "opts": ["Two minutes", "Three minutes", "Five minutes", "Fifteen minutes"], "a": 2, "kind": "number", "why": "Người phụ nữ nói \"It's five minutes from here.\"", "wrong": {"Two minutes": "Không phải hai phút.", "Three minutes": "Không phải ba phút.", "Fifteen minutes": "Fifteen (15) nghe giống five (5), nhưng bà nói five."}}, {"q": "What should Tom do first?", "opts": ["Turn left at the bank", "Go straight on this street", "Go into the park", "Ask at the bank"], "a": 1, "kind": "next-step", "why": "Bà nói \"Go straight on this street\" trước, sau đó mới rẽ trái.", "wrong": {"Turn left at the bank": "Rẽ trái là bước thứ hai.", "Go into the park": "Công viên chỉ là điểm nhận biết bưu điện.", "Ask at the bank": "Không cần hỏi ở ngân hàng."}}], "notes": {"vocab": [["excuse me", "xin lỗi (để hỏi người lạ)"], ["post office", "bưu điện"], ["go straight", "đi thẳng"], ["turn left", "rẽ trái"], ["next to", "bên cạnh"]], "grammar": [["Câu mệnh lệnh", "Go straight on this street", "Câu mệnh lệnh bắt đầu bằng động từ, dùng để chỉ đường."], ["Where is ... ?", "Where is the post office?", "Hỏi vị trí: Where is + danh từ?"]], "tips": ["Khi nghe chỉ đường, hãy ghi thứ tự: đi thẳng, rồi rẽ trái.", "Nghe các từ then (sau đó) và next to (bên cạnh) để biết thứ tự và vị trí."]}}, {"id": "lc-203", "lvl": "A1", "kind": "announcement", "title": "Green Market Closing Time Announcement", "script": [["Announcer", "Good evening, shoppers."], ["Announcer", "This is an announcement from Green Market."], ["Announcer", "The shop closes at nine o'clock tonight."], ["Announcer", "Please bring your food to the front now."], ["Announcer", "You can pay at the three open desks."], ["Announcer", "The car park is open until ten o'clock."], ["Announcer", "Tomorrow we open at eight in the morning."], ["Announcer", "Thank you for shopping with us, and have a nice evening."]], "qs": [{"q": "What is the announcement about?", "opts": ["A special price", "A lost child", "The shop closing time", "A new shop"], "a": 2, "kind": "gist", "why": "Thông báo nói \"The shop closes at nine o'clock tonight.\"", "wrong": {"A special price": "Không nhắc đến giá đặc biệt.", "A lost child": "Không có trẻ bị lạc.", "A new shop": "Không nói về cửa hàng mới."}}, {"q": "When does the shop close tonight?", "opts": ["At eight o'clock", "At nine o'clock", "At ten o'clock", "At eleven o'clock"], "a": 1, "kind": "number", "why": "Thông báo nói \"closes at nine o'clock tonight\".", "wrong": {"At eight o'clock": "Tám giờ là giờ mở cửa ngày mai.", "At ten o'clock": "Mười giờ là giờ bãi đỗ xe đóng.", "At eleven o'clock": "Không nhắc đến mười một giờ."}}, {"q": "When does the shop open tomorrow?", "opts": ["At eight in the morning", "At nine in the morning", "At ten in the morning", "At seven in the morning"], "a": 0, "kind": "number", "why": "Thông báo nói \"Tomorrow we open at eight in the morning.\"", "wrong": {"At nine in the morning": "Chín giờ là giờ đóng cửa tối nay.", "At ten in the morning": "Mười giờ là giờ bãi đỗ xe đóng.", "At seven in the morning": "Không nhắc đến bảy giờ."}}, {"q": "What should shoppers do now?", "opts": ["Go home by car", "Come back tomorrow", "Wait at the car park", "Bring their food to the front"], "a": 3, "kind": "next-step", "why": "Thông báo nói \"Please bring your food to the front now.\"", "wrong": {"Go home by car": "Chưa cần về ngay, họ phải thanh toán trước.", "Come back tomorrow": "Ngày mai là giờ mở cửa, không phải việc cần làm bây giờ.", "Wait at the car park": "Bãi đỗ xe chỉ mở đến mười giờ, không bảo chờ ở đó."}}], "notes": {"vocab": [["announcement", "thông báo"], ["shoppers", "khách mua sắm"], ["closes", "đóng cửa"], ["pay", "trả tiền"], ["car park", "bãi đỗ xe"]], "grammar": [["Câu mệnh lệnh lịch sự", "Please bring your food to the front now", "Please + động từ là cách yêu cầu lịch sự trong thông báo."], ["Hiện tại đơn cho lịch cố định", "The shop closes at nine o'clock tonight", "Dùng hiện tại đơn để nói giờ mở, đóng cửa."]], "tips": ["Thông báo thường có giờ giấc: nghe kỹ từng con số và từ close, open.", "Chú ý có nhiều giờ khác nhau (nine, ten, eight), hãy gắn từng giờ với từng việc."]}}, {"id": "lc-204", "lvl": "A1", "kind": "voicemail", "title": "Ben Invites Mia to a Picnic", "script": [["Ben", "Hi Mia, it's Ben. How are you?"], ["Ben", "Are you free on Sunday? The weather will be nice."], ["Ben", "I want to go to the park for a picnic."], ["Ben", "We meet at ten o'clock at the big gate."], ["Ben", "I bring sandwiches and juice."], ["Ben", "Can you bring some fruit? Apples are good."], ["Ben", "Please call me back tonight, after dinner."], ["Ben", "See you on Sunday. I'm happy! Bye!"]], "qs": [{"q": "Why does Ben call Mia?", "opts": ["To ask for help with work", "To say sorry", "To invite her to a picnic", "To ask for fruit only"], "a": 2, "kind": "gist", "why": "Ben nói \"I want to go to the park for a picnic\" và hỏi Mia có rảnh không.", "wrong": {"To ask for help with work": "Ben không nhờ làm việc.", "To say sorry": "Ben không xin lỗi.", "To ask for fruit only": "Ben nhờ mang trái cây nhưng mục đích chính là mời đi picnic."}}, {"q": "What does Ben bring?", "opts": ["Sandwiches and juice", "Fruit and cake", "Water and bread", "Tea and rice"], "a": 0, "kind": "detail", "why": "Ben nói \"I bring sandwiches and juice.\"", "wrong": {"Fruit and cake": "Trái cây là thứ Ben nhờ Mia mang.", "Water and bread": "Không nhắc đến nước và bánh mì.", "Tea and rice": "Không nhắc đến trà và cơm."}}, {"q": "What time do they meet?", "opts": ["At nine o'clock", "At ten o'clock", "At eleven o'clock", "At twelve o'clock"], "a": 1, "kind": "number", "why": "Ben nói \"We meet at ten o'clock at the big gate.\"", "wrong": {"At nine o'clock": "Không phải chín giờ.", "At eleven o'clock": "Không phải mười một giờ.", "At twelve o'clock": "Không phải mười hai giờ."}}, {"q": "What should Mia do tonight?", "opts": ["Go to the park", "Make sandwiches", "Buy juice", "Call Ben back"], "a": 3, "kind": "next-step", "why": "Ben nói \"Please call me back tonight.\"", "wrong": {"Go to the park": "Picnic là vào Chủ nhật, không phải tối nay.", "Make sandwiches": "Ben mang bánh sandwich.", "Buy juice": "Ben mang nước ép."}}], "notes": {"vocab": [["picnic", "buổi dã ngoại ăn ngoài trời"], ["are you free", "bạn có rảnh không"], ["big gate", "cổng lớn"], ["bring", "mang đến"], ["call me back", "gọi lại cho tôi"]], "grammar": [["Can you ... ? (nhờ vả)", "Can you bring some fruit?", "Can you + động từ dùng để nhờ ai làm gì."], ["want to + động từ", "I want to go to the park", "want to + động từ nguyên mẫu nghĩa là muốn làm gì."]], "tips": ["Tin nhắn thoại thường nêu: ai gọi, việc gì, khi nào, bạn cần làm gì.", "Chú ý giờ và ngày: Sunday, ten o'clock."]}}, {"id": "lc-205", "lvl": "A1", "kind": "conversation", "title": "Linh Checks In at the Clinic", "script": [["Receptionist", "Good morning. Welcome to the clinic. Can I help you?"], ["Linh", "Good morning. I have an appointment with Doctor Brown."], ["Receptionist", "What's your name, please?"], ["Linh", "My name is Linh Tran."], ["Receptionist", "Yes, I see it. Your appointment is at half past ten."], ["Linh", "Oh, good. I'm early. Is that okay?"], ["Receptionist", "Please fill in this form first. Then sit in the waiting room."], ["Linh", "Okay. Thank you very much."]], "qs": [{"q": "Why is Linh at the clinic?", "opts": ["She has an appointment", "She works there", "She is lost", "She wants to buy medicine"], "a": 0, "kind": "gist", "why": "Linh nói \"I have an appointment with Doctor Brown.\"", "wrong": {"She works there": "Cô ấy là bệnh nhân, không làm việc ở đó.", "She is lost": "Cô ấy không bị lạc.", "She wants to buy medicine": "Không nhắc đến mua thuốc."}}, {"q": "Who is Linh's doctor?", "opts": ["Doctor Tran", "Doctor Linh", "Doctor Smith", "Doctor Brown"], "a": 3, "kind": "detail", "why": "Linh nói \"with Doctor Brown\".", "wrong": {"Doctor Tran": "Tran là họ của Linh, không phải bác sĩ.", "Doctor Linh": "Linh là tên bệnh nhân.", "Doctor Smith": "Không nhắc đến bác sĩ Smith."}}, {"q": "What time is the appointment?", "opts": ["Half past ten", "Half past nine", "Ten o'clock", "Eleven o'clock"], "a": 0, "kind": "number", "why": "Lễ tân nói \"half past ten\", tức mười giờ rưỡi.", "wrong": {"Half past nine": "Half past nine là chín giờ rưỡi, sai.", "Ten o'clock": "Ten o'clock là mười giờ đúng, nhưng lịch hẹn là mười giờ rưỡi.", "Eleven o'clock": "Không phải mười một giờ."}}, {"q": "What must Linh do first?", "opts": ["Sit in the waiting room", "See the doctor now", "Fill in a form", "Pay for the visit"], "a": 2, "kind": "next-step", "why": "Lễ tân nói \"Please fill in this form first.\"", "wrong": {"Sit in the waiting room": "Ngồi phòng chờ là bước sau.", "See the doctor now": "Linh đến sớm nên chưa gặp bác sĩ ngay.", "Pay for the visit": "Không nhắc đến việc trả tiền."}}], "notes": {"vocab": [["appointment", "cuộc hẹn khám"], ["waiting room", "phòng chờ"], ["fill in", "điền vào"], ["form", "mẫu đơn"], ["half past ten", "mười giờ rưỡi"]], "grammar": [["have + danh từ", "I have an appointment with Doctor Brown", "have dùng để nói về cuộc hẹn hoặc sở hữu."], ["Please + mệnh lệnh", "Please fill in this form first", "Please làm lời yêu cầu lịch sự hơn."]], "tips": ["Ở phòng khám, hãy nghe tên, giờ hẹn và việc cần làm trước.", "Half past ten nghĩa là mười giờ rưỡi, đừng nhầm với ten o'clock."]}}, {"id": "lc-206", "lvl": "A1", "kind": "talk", "title": "Mai Talks About Her Family", "script": [["Mai", "Hello. My name is Mai."], ["Mai", "I want to tell you about my family."], ["Mai", "There are five people in my family."], ["Mai", "My father is a teacher, and my mother is a nurse."], ["Mai", "I have one brother. He is twelve years old."], ["Mai", "I have a grandmother too. She lives with us."], ["Mai", "We eat dinner together every evening."], ["Mai", "I love my family very much."]], "qs": [{"q": "What is Mai's talk about?", "opts": ["Her school", "Her job", "Her house", "Her family"], "a": 3, "kind": "gist", "why": "Mai nói \"I want to tell you about my family.\"", "wrong": {"Her school": "Mai không nói về trường học.", "Her job": "Mai không nói về công việc của mình.", "Her house": "Mai không nói về ngôi nhà."}}, {"q": "What is Mai's mother's job?", "opts": ["A nurse", "A teacher", "A doctor", "A cook"], "a": 0, "kind": "detail", "why": "Mai nói \"my mother is a nurse\".", "wrong": {"A teacher": "Giáo viên là nghề của bố.", "A doctor": "Không nhắc đến bác sĩ.", "A cook": "Không nhắc đến đầu bếp."}}, {"q": "How many people are in Mai's family?", "opts": ["Four", "Five", "Six", "Twelve"], "a": 1, "kind": "number", "why": "Mai nói \"There are five people in my family.\"", "wrong": {"Four": "Không phải bốn người.", "Six": "Không phải sáu người.", "Twelve": "Twelve là tuổi của em trai."}}, {"q": "How old is Mai's brother?", "opts": ["Ten", "Eleven", "Twelve", "Fifteen"], "a": 2, "kind": "number", "why": "Mai nói \"He is twelve years old.\"", "wrong": {"Ten": "Không phải mười tuổi.", "Eleven": "Không phải mười một tuổi.", "Fifteen": "Fifteen (15) không được nhắc đến."}}], "notes": {"vocab": [["family", "gia đình"], ["nurse", "y tá"], ["brother", "anh hoặc em trai"], ["grandmother", "bà"], ["together", "cùng nhau"]], "grammar": [["There are + số + danh từ", "There are five people in my family", "There are dùng để nói có bao nhiêu người hoặc vật."], ["Hiện tại đơn ngôi thứ ba", "She lives with us", "Chủ ngữ she/he thì động từ thêm -s."]], "tips": ["Trong bài nói giới thiệu, hãy nghe chủ đề ở câu đầu rồi ghi các chi tiết.", "Chú ý số: five (số người) và twelve (tuổi), đừng nhầm hai con số."]}}, {"id": "lc-301", "lvl": "A2", "kind": "conversation", "title": "Booking a Taxi to the Airport", "script": [["Operator", "City Taxi, good morning. How can I help you?"], ["Anna", "Hi. I need a taxi to the airport, please."], ["Operator", "Sure. When do you need it?"], ["Anna", "Tomorrow morning at six thirty."], ["Operator", "Okay. Where are you now?"], ["Anna", "I'm at twenty-five Green Street, near the park."], ["Operator", "Got it. How many people are going?"], ["Anna", "Two people and three big bags. We are going on holiday, so we have a lot of things."], ["Operator", "No problem. We'll send a large car. It costs about thirty dollars."], ["Anna", "That's fine. Can I pay by card?"], ["Operator", "Yes, you can. You can also pay with cash. Please give me your phone number too."], ["Anna", "It is zero nine one, two three four, five six seven."], ["Operator", "Thank you. The driver will call you five minutes before he arrives."], ["Anna", "Great. Thank you very much."]], "qs": [{"q": "Why is Anna calling?", "opts": ["To book a taxi", "To change a flight", "To ask about a bus", "To find a lost bag"], "a": 0, "kind": "gist", "why": "Anna nói: \"I need a taxi to the airport, please.\"", "wrong": {"To change a flight": "Cô ấy không nhắc đến đổi chuyến bay.", "To ask about a bus": "Cô ấy gọi hãng taxi, không hỏi về xe buýt.", "To find a lost bag": "Cô ấy không nói mất hành lý; cô ấy chỉ có ba túi lớn."}}, {"q": "When does Anna need the taxi?", "opts": ["Tomorrow at six fifteen", "Tomorrow at six thirty", "Today at six thirty", "Tomorrow at seven thirty"], "a": 1, "kind": "number", "why": "Anna nói: \"Tomorrow morning at six thirty.\"", "wrong": {"Tomorrow at six fifteen": "Sáu giờ mười lăm không được nhắc đến.", "Today at six thirty": "Cô ấy cần xe vào ngày mai, không phải hôm nay.", "Tomorrow at seven thirty": "Bảy giờ rưỡi nghe gần giống nhưng sai."}}, {"q": "Where will the taxi pick her up?", "opts": ["At the airport", "At the park gate", "At twenty-five Green Street", "At the taxi office"], "a": 2, "kind": "detail", "why": "Anna nói: \"I'm at twenty-five Green Street, near the park.\"", "wrong": {"At the airport": "Sân bay là nơi cô ấy muốn đến, không phải nơi đón.", "At the park gate": "Công viên chỉ là nơi ở gần, không phải địa chỉ đón.", "At the taxi office": "Cô ấy không đến văn phòng taxi."}}, {"q": "How much will the ride cost?", "opts": ["About thirteen dollars", "About fifty dollars", "About thirty dollars", "About twenty dollars"], "a": 2, "kind": "number", "why": "Người trực tổng đài nói: \"It costs about thirty dollars.\"", "wrong": {"About thirteen dollars": "Thirteen và thirty nghe giống nhau, nhưng giá là thirty.", "About fifty dollars": "Giá không phải năm mươi đô.", "About twenty dollars": "Giá không phải hai mươi đô."}}, {"q": "What will the driver do before he arrives?", "opts": ["Send a text message", "Call Anna", "Ring the door bell", "Wait at the airport"], "a": 1, "kind": "next-step", "why": "Người trực tổng đài nói: \"The driver will call you five minutes before he arrives.\"", "wrong": {"Send a text message": "Tài xế sẽ gọi điện, không nhắn tin.", "Ring the door bell": "Không nhắc đến việc bấm chuông cửa.", "Wait at the airport": "Tài xế đến đón Anna, không chờ ở sân bay."}}], "notes": {"vocab": [["airport", "sân bay"], ["large car", "xe lớn", "Dùng cho nhiều người và hành lý."], ["pay by card", "trả bằng thẻ"], ["arrives", "đến nơi", "arrive = đến"], ["near the park", "gần công viên"]], "grammar": [["will (future)", "The driver will call you five minutes before he arrives.", "Dùng will + động từ nguyên mẫu để nói về việc sẽ xảy ra."], ["Can I ...? (xin phép)", "Can I pay by card?", "Can I + động từ dùng để hỏi xin phép hoặc hỏi có được làm gì không."]], "tips": ["Khi nghe đặt xe, hãy chú ý giờ, địa chỉ và giá tiền; ghi nhanh các con số.", "Cẩn thận các số nghe giống nhau như thirteen và thirty: thirteen nhấn âm cuối, thirty nhấn âm đầu."]}}, {"id": "lc-302", "lvl": "A2", "kind": "conversation", "title": "Returning a Shirt That Is Too Small", "script": [["Clerk", "Hello. Can I help you?"], ["Mia", "Yes, please. I bought this shirt last Saturday, but it's too small. I want to return it."], ["Clerk", "Okay. Do you have the receipt?"], ["Mia", "Yes, here it is. I still have the bag too, and I did not wear the shirt."], ["Clerk", "Thank you. You paid twenty-four dollars. Do you want your money back?"], ["Mia", "Well, I'd like a bigger size, if you have one."], ["Clerk", "Let me check. We have a medium in blue, but not in white."], ["Mia", "Blue is fine. I'll take the medium."], ["Clerk", "Great. It is a very nice colour, and I think it will fit you well."], ["Clerk", "The medium is twenty-six dollars, so you need to pay two dollars more."], ["Mia", "No problem. Here's my card."], ["Clerk", "Thanks. Here's your new shirt and your receipt."]], "qs": [{"q": "What does Mia want to do?", "opts": ["Buy a hat", "Return a shirt", "Ask for a job", "Pay a bill"], "a": 1, "kind": "gist", "why": "Mia nói: \"I want to return it\", ý nói chiếc áo sơ mi.", "wrong": {"Buy a hat": "Cô ấy không nhắc đến mũ.", "Ask for a job": "Cô ấy không xin việc.", "Pay a bill": "Cô ấy không thanh toán hóa đơn; cô ấy đổi áo."}}, {"q": "Why does Mia return the shirt?", "opts": ["It is the wrong colour", "It is too expensive", "It is too small", "It is dirty"], "a": 2, "kind": "detail", "why": "Mia nói: \"it's too small.\"", "wrong": {"It is the wrong colour": "Màu sắc không phải lý do; cô ấy còn chọn màu xanh.", "It is too expensive": "Cô ấy không nói áo quá đắt.", "It is dirty": "Cô ấy không nói áo bị bẩn."}}, {"q": "How much did Mia pay for the first shirt?", "opts": ["Twenty-four dollars", "Twenty-six dollars", "Fourteen dollars", "Two dollars"], "a": 0, "kind": "number", "why": "Nhân viên nói: \"You paid twenty-four dollars.\"", "wrong": {"Twenty-six dollars": "Hai mươi sáu đô là giá của chiếc cỡ vừa mới.", "Fourteen dollars": "Mười bốn đô nghe giống nhưng không đúng.", "Two dollars": "Hai đô là số tiền cô ấy phải trả thêm."}}, {"q": "Which shirt does Mia take?", "opts": ["A white medium", "A blue medium", "A blue small", "A white large"], "a": 1, "kind": "detail", "why": "Nhân viên nói có cỡ vừa màu xanh nhưng không có màu trắng; Mia nói: \"I'll take the medium.\"", "wrong": {"A white medium": "Cửa hàng không có màu trắng.", "A blue small": "Cô ấy cần cỡ lớn hơn, không phải cỡ nhỏ.", "A white large": "Không có cỡ lớn màu trắng được nhắc đến."}}, {"q": "What will Mia do next?", "opts": ["Go home with her old shirt", "Get her money back", "Pay two dollars more", "Look for another shop"], "a": 2, "kind": "next-step", "why": "Nhân viên nói cô cần trả thêm hai đô và Mia đưa thẻ: \"Here's my card.\"", "wrong": {"Go home with her old shirt": "Cô ấy đổi áo, nên không mang áo cũ về.", "Get her money back": "Cô ấy chọn đổi sang áo khác, không lấy lại tiền.", "Look for another shop": "Cô ấy không đi tìm cửa hàng khác."}}], "notes": {"vocab": [["receipt", "hóa đơn, biên lai"], ["return it", "trả lại nó"], ["money back", "hoàn tiền"], ["a bigger size", "cỡ lớn hơn"], ["medium", "cỡ vừa (M)"]], "grammar": [["Comparative (so sánh hơn)", "I'd like a bigger size, if you have one.", "Tính từ ngắn thêm -er để so sánh hơn: big thành bigger."], ["Past simple (quá khứ đơn)", "I bought this shirt last Saturday", "Dùng quá khứ đơn với mốc thời gian đã qua như last Saturday; buy thành bought."]], "tips": ["Trong hội thoại ở cửa hàng, hãy nghe lý do trả hàng trước, rồi đến lựa chọn cuối cùng của khách.", "Chú ý số tiền xuất hiện nhiều lần; câu hỏi thường hỏi số tiền cụ thể."]}}, {"id": "lc-303", "lvl": "A2", "kind": "announcement", "title": "Cancelled Train and Replacement Bus Notice", "script": [["Announcer", "Attention, please. This is an announcement for passengers going to Oxford."], ["Announcer", "The ten fifteen train to Oxford is cancelled today. We are sorry for this problem."], ["Announcer", "There is a problem with the rails near Reading."], ["Announcer", "Please don't wait on platform four. A replacement bus will leave at ten forty-five."], ["Announcer", "The bus leaves from the front of the station, next to the main entrance."], ["Announcer", "The bus is free. Please show your train ticket to the driver."], ["Announcer", "The journey will take about one hour and twenty minutes, so it will be slower than the train."], ["Announcer", "If you need help, please ask a member of staff in a yellow jacket."], ["Announcer", "The next train to Oxford is at twelve o'clock. Thank you for your patience."]], "qs": [{"q": "What is the announcement about?", "opts": ["A late bus", "A cancelled train", "A lost ticket", "A new platform"], "a": 1, "kind": "gist", "why": "Thông báo nói: \"The ten fifteen train to Oxford is cancelled today.\"", "wrong": {"A late bus": "Xe buýt là phương tiện thay thế, không bị trễ.", "A lost ticket": "Không nhắc đến vé bị mất.", "A new platform": "Hành khách được dặn không chờ ở sân ga bốn, nhưng không có sân ga mới."}}, {"q": "Which train is cancelled?", "opts": ["The ten fifty train", "The ten forty-five train", "The ten fifteen train", "The twelve o'clock train"], "a": 2, "kind": "number", "why": "Thông báo nói: \"The ten fifteen train to Oxford is cancelled today.\"", "wrong": {"The ten fifty train": "Mười giờ năm mươi không được nhắc đến.", "The ten forty-five train": "Mười giờ bốn mươi lăm là giờ xe buýt chạy.", "The twelve o'clock train": "Chuyến mười hai giờ vẫn chạy bình thường."}}, {"q": "Where can passengers get the bus?", "opts": ["On platform four", "At the Oxford station", "Next to the ticket office", "In front of the station"], "a": 3, "kind": "detail", "why": "Thông báo nói: \"The bus leaves from the front of the station, next to the main entrance.\"", "wrong": {"On platform four": "Hành khách được dặn đừng chờ ở sân ga bốn.", "At the Oxford station": "Xe buýt đi từ ga hiện tại, không phải ga Oxford.", "Next to the ticket office": "Xe đỗ cạnh cửa chính, không phải cạnh quầy vé."}}, {"q": "What should passengers show to the bus driver?", "opts": ["Their train ticket", "Their passport", "A bus pass", "A yellow jacket"], "a": 0, "kind": "next-step", "why": "Thông báo nói: \"Please show your train ticket to the driver.\"", "wrong": {"Their passport": "Không cần hộ chiếu.", "A bus pass": "Xe buýt miễn phí, nên không cần thẻ xe buýt.", "A yellow jacket": "Áo vàng là của nhân viên, không phải thứ hành khách cần."}}, {"q": "How long is the bus journey?", "opts": ["About forty minutes", "About one hour", "About two hours", "About one hour and twenty minutes"], "a": 3, "kind": "number", "why": "Thông báo nói: \"The journey will take about one hour and twenty minutes.\"", "wrong": {"About forty minutes": "Bốn mươi phút quá ngắn.", "About one hour": "Một tiếng chưa đủ; còn thêm hai mươi phút.", "About two hours": "Hai tiếng quá dài."}}], "notes": {"vocab": [["cancelled", "bị hủy"], ["replacement bus", "xe buýt thay thế"], ["platform", "sân ga"], ["main entrance", "cửa chính"], ["member of staff", "nhân viên"], ["patience", "sự kiên nhẫn", "Thank you for your patience = cảm ơn quý khách đã kiên nhẫn chờ."]], "grammar": [["Passive (bị động)", "The ten fifteen train to Oxford is cancelled today.", "Cấu trúc is/are + quá khứ phân từ để nói điều gì đó bị làm."], ["will (future)", "A replacement bus will leave at ten forty-five.", "Dùng will để nói về kế hoạch hoặc việc sẽ xảy ra."]], "tips": ["Trong thông báo ở ga, nghe trước xem chuyện gì xảy ra (hủy, trễ), rồi nghe phải làm gì.", "Hãy ghi lại các giờ giấc và số sân ga; chúng thường bị hỏi."]}}, {"id": "lc-304", "lvl": "A2", "kind": "voicemail", "title": "Dentist Appointment Reminder Message", "script": [["Receptionist", "Hello, this is Sara from Bright Smile Dental Clinic. This message is for Mr Tran."], ["Receptionist", "I'm calling to remind you about your appointment with Doctor Green."], ["Receptionist", "Your appointment is on Thursday, the fourteenth of March, at nine thirty in the morning."], ["Receptionist", "It's a check-up and a clean, so it will take about thirty minutes."], ["Receptionist", "Please come ten minutes early and bring your insurance card."], ["Receptionist", "Please brush your teeth before you come, and tell the doctor if you have any pain."], ["Receptionist", "Please don't eat or drink anything hot before your visit."], ["Receptionist", "If you can't come, please call us on five five five, zero one two three, before Wednesday afternoon."], ["Receptionist", "We hope you are well, and we'll see you on Thursday. Goodbye."]], "qs": [{"q": "Why is the receptionist calling?", "opts": ["To cancel a visit", "To give test results", "To remind about an appointment", "To ask for payment"], "a": 2, "kind": "gist", "why": "Lễ tân nói: \"I'm calling to remind you about your appointment with Doctor Green.\"", "wrong": {"To cancel a visit": "Cô ấy không hủy lịch hẹn.", "To give test results": "Cô ấy không nhắc đến kết quả xét nghiệm.", "To ask for payment": "Cô ấy không đòi thanh toán."}}, {"q": "When is the appointment?", "opts": ["Thursday at nine thirty", "Thursday at ten thirty", "Wednesday at nine thirty", "Friday at nine"], "a": 0, "kind": "number", "why": "Lễ tân nói: \"on Thursday, the fourteenth of March, at nine thirty in the morning.\"", "wrong": {"Thursday at ten thirty": "Mười giờ rưỡi không đúng.", "Wednesday at nine thirty": "Thứ Tư là hạn cuối để gọi hủy lịch.", "Friday at nine": "Thứ Sáu không được nhắc đến."}}, {"q": "How long will the visit take?", "opts": ["About fifteen minutes", "About twenty minutes", "About forty minutes", "About thirty minutes"], "a": 3, "kind": "detail", "why": "Lễ tân nói: \"it will take about thirty minutes.\"", "wrong": {"About fifteen minutes": "Mười lăm phút quá ngắn.", "About twenty minutes": "Hai mươi phút không đúng.", "About forty minutes": "Bốn mươi phút không đúng."}}, {"q": "What should Mr Tran bring?", "opts": ["His insurance card", "His old X-rays", "A friend", "Some money"], "a": 0, "kind": "detail", "why": "Lễ tân nói: \"bring your insurance card.\"", "wrong": {"His old X-rays": "Không nhắc đến phim X-quang cũ.", "A friend": "Không cần mang người đi cùng.", "Some money": "Thẻ bảo hiểm được yêu cầu, không phải tiền."}}, {"q": "What should he do if he can't come?", "opts": ["Call before Wednesday afternoon", "Send an email", "Come on Friday", "Do nothing"], "a": 0, "kind": "next-step", "why": "Lễ tân nói: \"please call us ... before Wednesday afternoon.\"", "wrong": {"Send an email": "Cô ấy yêu cầu gọi điện, không gửi email.", "Come on Friday": "Không nhắc đến việc đến vào thứ Sáu.", "Do nothing": "Anh ấy cần gọi phòng khám, không phải ngồi yên."}}], "notes": {"vocab": [["appointment", "cuộc hẹn khám"], ["remind you", "nhắc bạn"], ["check-up", "khám tổng quát"], ["insurance card", "thẻ bảo hiểm"], ["early", "sớm"]], "grammar": [["Imperative (câu mệnh lệnh lịch sự)", "Please come ten minutes early and bring your insurance card.", "Dùng please + động từ nguyên mẫu để yêu cầu lịch sự."], ["If-clause (điều kiện)", "If you can't come, please call us", "If + hiện tại, rồi nêu việc cần làm."]], "tips": ["Trong tin nhắn thoại, nghe tên người gọi, lý do gọi, rồi ngày giờ.", "Hãy ghi lại ngày, giờ và việc cần mang; đây là thông tin quan trọng nhất."]}}, {"id": "lc-305", "lvl": "A2", "kind": "conversation", "title": "A Nurse Explains When to Take Medicine", "script": [["Nurse", "Mr Hall, here is your medicine. Let me explain it."], ["Patient", "Thank you. Is it hard to take?"], ["Nurse", "No, it's easy. You take the white tablet in the morning, after breakfast."], ["Patient", "Okay. And the other one?"], ["Nurse", "Do you understand so far? Please ask me if you are not sure."], ["Nurse", "The small orange tablet is for the evening. Take it before dinner."], ["Patient", "I usually have a big breakfast at home, so that is easy for me."], ["Patient", "Should I take them with water?"], ["Nurse", "Yes, please drink a full glass of water. Don't take them with coffee."], ["Patient", "What if I forget a tablet?"], ["Nurse", "Take it when you remember, but don't take two tablets at the same time."], ["Patient", "I understand. For how many days?"], ["Nurse", "For seven days. If you feel dizzy, please call us."]], "qs": [{"q": "What is the nurse doing?", "opts": ["Taking a blood test", "Explaining how to take medicine", "Booking an appointment", "Giving food advice"], "a": 1, "kind": "gist", "why": "Y tá nói: \"Here is your medicine. Let me explain it.\"", "wrong": {"Taking a blood test": "Cô ấy không lấy máu.", "Booking an appointment": "Cô ấy không đặt lịch hẹn.", "Giving food advice": "Cô ấy nói về thuốc, không phải chế độ ăn."}}, {"q": "When should Mr Hall take the white tablet?", "opts": ["Before dinner", "At night", "In the morning, after breakfast", "At lunch"], "a": 2, "kind": "detail", "why": "Y tá nói: \"You take the white tablet in the morning, after breakfast.\"", "wrong": {"Before dinner": "Trước bữa tối là lúc uống viên cam.", "At night": "Không nhắc đến uống vào ban đêm.", "At lunch": "Không nhắc đến bữa trưa."}}, {"q": "What should he drink with the tablets?", "opts": ["Coffee", "Milk", "Tea", "A full glass of water"], "a": 3, "kind": "detail", "why": "Y tá nói: \"please drink a full glass of water. Don't take them with coffee.\"", "wrong": {"Coffee": "Cà phê bị cấm khi uống thuốc.", "Milk": "Không nhắc đến sữa.", "Tea": "Không nhắc đến trà."}}, {"q": "What should he do if he forgets a tablet?", "opts": ["Take two tablets later", "Take it when he remembers", "Skip the next day", "Call the nurse at night"], "a": 1, "kind": "next-step", "why": "Y tá nói: \"Take it when you remember, but don't take two tablets at the same time.\"", "wrong": {"Take two tablets later": "Cô ấy dặn không uống hai viên cùng lúc.", "Skip the next day": "Không nhắc đến việc bỏ cả ngày.", "Call the nurse at night": "Chỉ gọi khi bị chóng mặt, không phải vì quên thuốc."}}, {"q": "For how many days will he take the medicine?", "opts": ["Three days", "Five days", "Seven days", "Ten days"], "a": 2, "kind": "number", "why": "Y tá nói: \"For seven days.\"", "wrong": {"Three days": "Ba ngày không đúng.", "Five days": "Năm ngày không đúng.", "Ten days": "Mười ngày không đúng."}}], "notes": {"vocab": [["tablet", "viên thuốc"], ["after breakfast", "sau bữa sáng"], ["before dinner", "trước bữa tối"], ["a full glass of water", "một cốc nước đầy"], ["dizzy", "chóng mặt"], ["forget", "quên"]], "grammar": [["Imperative negative (cấm đoán)", "Don't take them with coffee.", "Don't + động từ nguyên mẫu để dặn đừng làm gì."], ["Should I ...? (hỏi lời khuyên)", "Should I take them with water?", "Should I + động từ dùng để hỏi mình có nên làm gì."]], "tips": ["Khi nghe hướng dẫn uống thuốc, chú ý thời điểm (sáng, tối, trước hay sau bữa ăn).", "Nghe từ phủ định như don't, vì chúng đổi hoàn toàn ý nghĩa của lời dặn."]}}, {"id": "lc-306", "lvl": "A2", "kind": "talk", "title": "A Student Describes Her Weekend", "script": [["Linh", "Hi, everyone. Today I want to tell you about my weekend. It was really nice."], ["Linh", "On Saturday morning, I got up late, at nine o'clock. I had a big breakfast with my mother."], ["Linh", "In the afternoon, I met my friend Hoa. We went to the library and studied for our English test."], ["Linh", "After that, we were hungry, so we ate noodles at a small restaurant. It cost four dollars."], ["Linh", "On Sunday, the weather was good, so I went to the lake with my family. We had a picnic."], ["Linh", "My brother played football with some boys, and I read a book under a tree."], ["Linh", "In the evening, we came home and watched a film together."], ["Linh", "I was tired, but I was happy. Next weekend, I want to visit my grandmother."]], "qs": [{"q": "What is Linh talking about?", "opts": ["Her school test", "Her weekend", "Her family holiday", "Her new job"], "a": 1, "kind": "gist", "why": "Linh nói: \"Today I want to tell you about my weekend.\"", "wrong": {"Her school test": "Bài kiểm tra chỉ là một phần nhỏ của cuối tuần.", "Her family holiday": "Cô ấy kể về cuối tuần, không phải kỳ nghỉ gia đình.", "Her new job": "Cô ấy không nhắc đến công việc mới."}}, {"q": "What time did Linh get up on Saturday?", "opts": ["At eight o'clock", "At nine o'clock", "At ten o'clock", "At seven o'clock"], "a": 1, "kind": "number", "why": "Linh nói: \"I got up late, at nine o'clock.\"", "wrong": {"At eight o'clock": "Tám giờ không đúng.", "At ten o'clock": "Mười giờ không đúng.", "At seven o'clock": "Bảy giờ không đúng."}}, {"q": "What did Linh and Hoa do in the library?", "opts": ["They ate noodles", "They watched a film", "They studied for a test", "They read comic books"], "a": 2, "kind": "detail", "why": "Linh nói: \"We went to the library and studied for our English test.\"", "wrong": {"They ate noodles": "Họ ăn mì sau đó, ở nhà hàng nhỏ.", "They watched a film": "Xem phim là việc cô ấy làm vào tối Chủ nhật.", "They read comic books": "Không nhắc đến truyện tranh."}}, {"q": "Where did Linh go on Sunday?", "opts": ["To the lake", "To the library", "To a restaurant", "To her grandmother's house"], "a": 0, "kind": "detail", "why": "Linh nói: \"I went to the lake with my family. We had a picnic.\"", "wrong": {"To the library": "Thư viện là nơi cô ấy đến vào thứ Bảy.", "To a restaurant": "Nhà hàng cũng là thứ Bảy.", "To her grandmother's house": "Nhà bà là kế hoạch cho cuối tuần sau."}}, {"q": "What does Linh want to do next weekend?", "opts": ["Play football", "Go to the lake again", "Study at the library", "Visit her grandmother"], "a": 3, "kind": "next-step", "why": "Linh nói: \"Next weekend, I want to visit my grandmother.\"", "wrong": {"Play football": "Em trai cô ấy chơi bóng đá, không phải cô.", "Go to the lake again": "Cô ấy không nói muốn đến hồ lần nữa.", "Study at the library": "Cô ấy không nhắc đến việc học ở thư viện tuần sau."}}], "notes": {"vocab": [["got up late", "dậy muộn"], ["breakfast", "bữa sáng"], ["library", "thư viện"], ["picnic", "buổi dã ngoại"], ["noodles", "mì"], ["tired", "mệt"]], "grammar": [["Past simple (quá khứ đơn)", "We went to the library and studied for our English test.", "Động từ quá khứ: go thành went; động từ có quy tắc thêm -ed như studied."], ["want to + verb", "I want to visit my grandmother.", "Dùng want to + động từ nguyên mẫu để nói điều mình muốn làm."]], "tips": ["Khi nghe một bài nói kể chuyện, chú ý các từ chỉ thời gian như on Saturday, after that, in the evening.", "Đoán thứ tự sự việc theo ngày; câu hỏi thường hỏi nơi chốn và việc làm theo từng ngày."]}}, {"id": "lc-307", "lvl": "A2", "kind": "interview", "title": "Strawberries at the Saturday Market", "script": [["Host", "Good morning, everyone. I'm at the Saturday market in Riverside, and I'm here with Linda, who sells fruit. Linda, can you tell us about your stall?"], ["Linda", "Of course! I sell fruit and vegetables, and I love my job."], ["Host", "How long have you worked at this market?"], ["Linda", "I started six years ago. My mother had a small stall here before me."], ["Host", "What do you have today?"], ["Linda", "Today I have apples, oranges and strawberries. The strawberries are very fresh. I picked them yesterday afternoon."], ["Host", "How much are they?"], ["Linda", "One box costs four dollars. If you buy two boxes, it's seven dollars."], ["Host", "That's a good price! What time does the market close?"], ["Linda", "We close at two o'clock. But next week we'll open earlier, at seven, because it will be hot."]], "qs": [{"q": "What is the interview mostly about?", "opts": ["Linda's fruit stall at a market", "A new shop in the city", "A cooking class for children", "The weather this weekend"], "a": 0, "kind": "gist", "why": "Người dẫn chương trình nói \"I'm here with Linda, who sells fruit\" và hỏi về quầy hàng của cô ấy.", "wrong": {"A new shop in the city": "Họ nói về quầy hàng ở chợ, không phải cửa hàng mới trong thành phố.", "A cooking class for children": "Không có lớp nấu ăn nào được nhắc đến.", "The weather this weekend": "Thời tiết chỉ được nhắc ngắn gọn, không phải chủ đề chính."}}, {"q": "How long has Linda worked at the market?", "opts": ["Two years", "Four years", "Six years", "Ten years"], "a": 2, "kind": "detail", "why": "Linda nói \"I started six years ago\", nghĩa là cô ấy làm ở đây sáu năm.", "wrong": {"Two years": "Linda nói \"I started six years ago\", không phải hai năm.", "Four years": "Bốn đô la là giá một hộp dâu, không phải số năm làm việc.", "Ten years": "Không có con số mười năm nào trong bài."}}, {"q": "How much are two boxes of strawberries?", "opts": ["Four dollars", "Seven dollars", "Eight dollars", "Two dollars"], "a": 1, "kind": "number", "why": "Linda nói \"If you buy two boxes, it's seven dollars.\"", "wrong": {"Four dollars": "Bốn đô la là giá cho MỘT hộp.", "Eight dollars": "Hai hộp không tính 4 + 4 = 8, mà được giảm giá còn bảy.", "Two dollars": "Không có giá hai đô la nào được nhắc đến."}}, {"q": "What time does the market close?", "opts": ["At seven o'clock", "At four o'clock", "At noon", "At two o'clock"], "a": 3, "kind": "number", "why": "Linda nói \"We close at two o'clock.\"", "wrong": {"At seven o'clock": "Bảy giờ là giờ chợ sẽ mở cửa vào tuần sau.", "At four o'clock": "Không có bốn giờ trong bài; bốn là giá một hộp dâu.", "At noon": "Chợ đóng cửa lúc hai giờ, không phải giữa trưa."}}, {"q": "What will happen next week?", "opts": ["The market will be closed", "The market will open at seven", "The strawberries will cost seven dollars", "Linda will sell vegetables only"], "a": 1, "kind": "next-step", "why": "Linda nói \"next week we'll open earlier, at seven, because it will be hot.\"", "wrong": {"The market will be closed": "Chợ vẫn mở, chỉ mở sớm hơn.", "The strawberries will cost seven dollars": "Bảy đô la là giá hai hộp hôm nay, không phải điều sẽ xảy ra tuần sau.", "Linda will sell vegetables only": "Không có thông tin nào nói Linda chỉ bán rau."}}], "notes": {"vocab": [["stall", "quầy hàng ở chợ"], ["strawberries", "dâu tây"], ["fresh", "tươi", "Trái nghĩa: old, stale"], ["picked", "đã hái (quá khứ của pick)"], ["close", "đóng cửa", "Ở đây là động từ, đọc /kloʊz/"]], "grammar": [["Past simple: started + ago", "I started six years ago.", "Dùng thì quá khứ đơn với \"ago\" để nói một việc đã bắt đầu cách đây bao lâu."], ["First conditional", "If you buy two boxes, it's seven dollars.", "Cấu trúc If + hiện tại đơn, kết quả: nói về một điều kiện có thể xảy ra."], ["Future with will", "next week we'll open earlier", "Dùng will để nói kế hoạch hoặc dự đoán trong tương lai."]], "tips": ["Khi nghe phỏng vấn, hãy nghe câu hỏi của người dẫn chương trình trước: câu hỏi cho biết câu trả lời sắp nói về điều gì (how long, how much, what time).", "Chú ý các con số và đơn vị: six years, four dollars, seven dollars, two o'clock. Một bài ngắn thường có nhiều số gần giống nhau."]}}, {"id": "lc-308", "lvl": "A2", "kind": "conversation", "title": "A Present for Anna's Sister", "script": [["Anna", "Hi Tom. I need some help. It's my sister's birthday on Sunday, and I don't have a present yet."], ["Tom", "How old is she going to be?"], ["Anna", "She'll be twenty. She loves reading, and she likes cooking too."], ["Tom", "What about a cookbook? There's a bookshop near the station."], ["Anna", "Good idea, but she bought a cookbook last month. Maybe a nice scarf?"], ["Tom", "Hmm. It's still warm, so she won't wear it now. I think a book of short stories is better. It costs about fifteen euros."], ["Anna", "Fifteen euros is fine. My budget is twenty."], ["Tom", "Great. Let's go this afternoon after lunch. I'll help you choose."], ["Anna", "Thanks! And I'll buy a card too."], ["Tom", "Good. I know a small shop with really nice ones, and it is very close."]], "qs": [{"q": "What are Anna and Tom trying to do?", "opts": ["Choose a birthday present", "Plan a holiday", "Cook a meal together", "Find a new bookshop"], "a": 0, "kind": "gist", "why": "Anna nói \"It's my sister's birthday on Sunday, and I don't have a present yet.\"", "wrong": {"Plan a holiday": "Họ nói về quà sinh nhật, không phải kỳ nghỉ.", "Cook a meal together": "Nấu ăn chỉ là sở thích của em gái Anna.", "Find a new bookshop": "Cửa hàng sách đã có sẵn gần ga, họ không đi tìm cửa hàng mới."}}, {"q": "How old will Anna's sister be?", "opts": ["Fifteen", "Twenty", "Twenty-five", "Thirty"], "a": 1, "kind": "number", "why": "Anna nói \"She'll be twenty.\"", "wrong": {"Fifteen": "Mười lăm là giá cuốn sách, tính bằng euro.", "Twenty-five": "Không có số hai mươi lăm trong bài.", "Thirty": "Không có số ba mươi trong bài."}}, {"q": "Why does Anna not buy a cookbook?", "opts": ["It is too expensive", "Her sister does not like cooking", "Her sister bought one last month", "The bookshop is closed"], "a": 2, "kind": "detail", "why": "Anna nói \"she bought a cookbook last month.\"", "wrong": {"It is too expensive": "Giá không phải lý do; sách truyện ngắn mới là mười lăm euro.", "Her sister does not like cooking": "Em gái Anna thích nấu ăn (\"she likes cooking too\").", "The bookshop is closed": "Không ai nói cửa hàng sách đóng cửa."}}, {"q": "How much does the book of short stories cost?", "opts": ["About fifteen euros", "About twenty euros", "About ten euros", "About thirty euros"], "a": 0, "kind": "number", "why": "Tom nói \"It costs about fifteen euros.\"", "wrong": {"About twenty euros": "Hai mươi euro là ngân sách tối đa của Anna.", "About ten euros": "Không có mười euro trong bài.", "About thirty euros": "Không có ba mươi euro trong bài."}}, {"q": "When will they go to the bookshop?", "opts": ["This afternoon, after lunch", "On Sunday morning", "Tomorrow evening", "Next month"], "a": 0, "kind": "next-step", "why": "Tom nói \"Let's go this afternoon after lunch.\"", "wrong": {"On Sunday morning": "Chủ nhật là ngày sinh nhật, không phải lúc họ đi mua.", "Tomorrow evening": "Họ không hẹn buổi tối ngày mai.", "Next month": "Không có kế hoạch cho tháng sau."}}], "notes": {"vocab": [["present", "món quà", "Trong bài có nghĩa là quà tặng, không phải \"hiện tại\""], ["cookbook", "sách nấu ăn"], ["scarf", "khăn quàng cổ"], ["budget", "ngân sách, số tiền dự tính chi"], ["short stories", "truyện ngắn"]], "grammar": [["Future with going to", "How old is she going to be?", "Dùng be going to để hỏi hoặc nói về điều sẽ xảy ra theo kế hoạch hoặc dự đoán."], ["Past simple", "she bought a cookbook last month", "Thì quá khứ đơn với last month: bought là quá khứ bất quy tắc của buy."], ["Let's + verb", "Let's go this afternoon after lunch.", "Dùng Let's + động từ nguyên mẫu để đề nghị cùng làm gì."]], "tips": ["Khi hai người bàn chọn quà, hãy chú ý lời đề nghị rồi lời từ chối: What about...? / Good idea, but... Câu trả lời đúng thường là phương án cuối cùng được đồng ý.", "Nghe kỹ từng con số và hỏi xem nó là gì: tuổi (twenty), giá (fifteen euros), ngân sách (twenty). Dễ nhầm lẫn giữa các số."]}}, {"id": "lc-401", "lvl": "B1", "kind": "conversation", "title": "Assistant Manager Interview at the Bookshop", "script": [["Ms Clark", "Good morning, Daniel. Please take a seat. Thanks for coming in today."], ["Daniel", "Good morning. Thank you for seeing me."], ["Ms Clark", "So, you're applying for the assistant manager job at our bookshop. Can you tell me a bit about your experience?"], ["Daniel", "Sure. I've worked in a café for three years. Actually, it's nearly four now, because I started in November. At first I just served customers, but last year I took over the ordering, so I deal with suppliers as well."], ["Ms Clark", "That sounds useful. What do you enjoy most about it?"], ["Daniel", "Honestly, I like helping people find what they need. And I'm good at staying calm when it gets busy. On Saturdays we often have a queue out of the door."], ["Ms Clark", "Good. Is there anything you find difficult?"], ["Daniel", "Well, I'm not very organised with paperwork, but I've been working on it. I make a list every morning, and it really helps me keep track of things."], ["Ms Clark", "Fine. This job involves working on weekends, and sometimes we stay open until nine in the evening. Is that a problem?"], ["Daniel", "Not at all. I'd rather work on weekends, because I study during the week. I only have classes on Monday and Tuesday."], ["Ms Clark", "Perfect. The salary is thirteen pounds an hour. Do you have any questions for me?"], ["Daniel", "Yes, when would the job start?"], ["Ms Clark", "We'd like someone to start on the first of March, but we'll phone everyone by Friday. I'll call you if you get through to the second round."], ["Daniel", "Great, thanks. I look forward to hearing from you."]], "qs": [{"q": "What is the conversation mainly about?", "opts": ["An interview for a job at a bookshop", "A customer buying a book", "A new student's first day at college", "A manager giving a staff training session"], "a": 0, "kind": "gist", "why": "Ms Clark nói \"you're applying for the assistant manager job at our bookshop.\"", "wrong": {"A customer buying a book": "Daniel không mua sách; anh ấy xin việc.", "A new student's first day at college": "Daniel là người xin việc, không phải ngày đầu đi học.", "A manager giving a staff training session": "Đây là buổi phỏng vấn tuyển dụng, không phải buổi đào tạo."}}, {"q": "How long has Daniel worked at the café?", "opts": ["Exactly three years", "Nearly four years", "About six months", "More than five years"], "a": 1, "kind": "number", "why": "Daniel nói \"three years. Actually, it's nearly four now\", nên đáp án đúng là gần bốn năm.", "wrong": {"Exactly three years": "Daniel nói ba năm rồi sửa lại: \"it's nearly four now\".", "About six months": "Anh ấy bắt đầu từ tháng Mười Một nhưng đã làm gần bốn năm, không phải sáu tháng.", "More than five years": "Không có thông tin này; con số là gần bốn năm."}}, {"q": "What does Daniel say is difficult for him?", "opts": ["Doing paperwork in an organised way", "Working on weekends", "Staying calm when it is busy", "Talking to customers"], "a": 0, "kind": "detail", "why": "Daniel nói \"I'm not very organised with paperwork, but I've been working on it.\"", "wrong": {"Working on weekends": "Daniel nói \"Not at all\", anh ấy thích làm cuối tuần.", "Staying calm when it is busy": "Đây là điểm mạnh của anh ấy.", "Talking to customers": "Anh ấy thích giúp khách, không nói là khó."}}, {"q": "What can we guess about Daniel?", "opts": ["He has never worked before", "He wants a job during the week", "He is probably a student", "He already works at the bookshop"], "a": 2, "kind": "inference", "why": "Daniel nói \"I study during the week. I only have classes on Monday and Tuesday\", nên có thể đoán anh ấy là sinh viên.", "wrong": {"He has never worked before": "Anh ấy đã làm việc ở quán cà phê gần bốn năm.", "He wants a job during the week": "Anh ấy muốn làm cuối tuần vì học trong tuần.", "He already works at the bookshop": "Anh ấy làm ở quán cà phê và đang xin vào hiệu sách."}}, {"q": "What will Ms Clark do by Friday?", "opts": ["Phone everyone who applied", "Send Daniel a contract", "Meet Daniel again at the café", "Start the new employee on the first of March"], "a": 0, "kind": "next-step", "why": "Ms Clark nói \"we'll phone everyone by Friday.\"", "wrong": {"Send Daniel a contract": "Chưa có hợp đồng; chỉ gọi điện cho ứng viên.", "Meet Daniel again at the café": "Không có kế hoạch gặp ở quán cà phê.", "Start the new employee on the first of March": "Ngày một tháng Ba là ngày bắt đầu làm việc dự kiến, không phải việc làm vào thứ Sáu."}}], "notes": {"vocab": [["applying for", "nộp đơn xin (việc)"], ["experience", "kinh nghiệm"], ["took over", "tiếp quản, đảm nhận", "Cụm động từ: take over"], ["deal with", "xử lý, làm việc với"], ["keep track of", "theo dõi, nắm được", "Cụm cố định: keep track of things"], ["get through to", "vượt qua để vào (vòng sau)"], ["look forward to", "mong chờ", "Sau to là danh động từ: hearing"]], "grammar": [["Present perfect", "I've worked in a café for three years.", "Present perfect + for + khoảng thời gian: việc bắt đầu trong quá khứ và vẫn tiếp tục đến nay."], ["Would rather", "I'd rather work on weekends", "I'd rather + động từ nguyên mẫu nghĩa là \"tôi thích ... hơn\"."], ["Present perfect continuous", "I've been working on it.", "have been + V-ing: việc đã bắt đầu và đang tiếp diễn, nhấn mạnh quá trình cố gắng."]], "tips": ["Trong buổi phỏng vấn, nghe câu hỏi của người phỏng vấn trước rồi tìm ý chính của câu trả lời. Chú ý khi người nói tự sửa số (three years, actually nearly four): số sau mới là đáp án.", "Từ báo hiệu như Actually, Well, Honestly thường đứng trước ý quan trọng hoặc lời sửa lại."]}}, {"id": "lc-402", "lvl": "B1", "kind": "announcement", "title": "Gate Change for the Edinburgh Flight", "script": [["Announcer", "Good afternoon, ladies and gentlemen. This is an important announcement for passengers on flight two four seven to Edinburgh."], ["Announcer", "The flight was due to leave from gate twelve, but there has been a change. Boarding will now take place at gate twenty-two. Please note, that's gate twenty-two, not gate twelve."], ["Announcer", "Gate twenty-two is in the same terminal, but it's a bit further away. It takes about ten minutes to walk there from the main shopping area, so please make your way there as soon as possible."], ["Announcer", "Boarding was due to begin at three fifteen, but because the aircraft arrived late, it will now start at three forty. The flight itself will leave at four ten, about twenty-five minutes later than planned."], ["Announcer", "Passengers with young children and those who need extra help can board first. Please speak to a member of staff at the gate."], ["Announcer", "When boarding starts, we'll call passengers by row number. Rows twenty to thirty will go first, then everyone else."], ["Announcer", "Please have your passport and boarding card ready, and remember that you can only take one piece of hand luggage onto the plane."], ["Announcer", "If you have a bag that is too big, please leave it at the desk, and we'll put it in the hold at no extra cost."], ["Announcer", "We'd also like to remind passengers not to leave bags alone. Any bags left unattended may be removed by security."], ["Announcer", "Thank you for your patience, and we apologise for any inconvenience. We wish you a pleasant flight."]], "qs": [{"q": "What is the main purpose of the announcement?", "opts": ["To tell passengers about a new gate and boarding time", "To say the flight has been cancelled", "To explain how to check in", "To warn about bad weather"], "a": 0, "kind": "gist", "why": "Thông báo nói \"there has been a change. Boarding will now take place at gate twenty-two\" và giờ lên máy bay mới.", "wrong": {"To say the flight has been cancelled": "Chuyến bay không bị hủy, chỉ đổi cổng và giờ lên máy bay.", "To explain how to check in": "Không có hướng dẫn làm thủ tục check-in.", "To warn about bad weather": "Lý do trễ là máy bay đến muộn, không phải thời tiết."}}, {"q": "What time will boarding start now?", "opts": ["Three forty", "Three fifteen", "Four ten", "Two forty"], "a": 0, "kind": "number", "why": "Thông báo nói \"it will now start at three forty.\"", "wrong": {"Three fifteen": "Ba giờ mười lăm là giờ lên máy bay dự kiến ban đầu.", "Four ten": "Bốn giờ mười là giờ máy bay cất cánh.", "Two forty": "Không có giờ này trong thông báo."}}, {"q": "What can passengers do with a bag that is too big?", "opts": ["Carry it onto the plane", "Leave it at the desk to go in the hold", "Pay an extra fee", "Leave it alone near the gate"], "a": 1, "kind": "detail", "why": "Thông báo nói \"leave it at the desk, and we'll put it in the hold at no extra cost.\"", "wrong": {"Carry it onto the plane": "Chỉ được mang một kiện hành lý xách tay.", "Pay an extra fee": "Thông báo nói \"at no extra cost\" nghĩa là không mất thêm phí.", "Leave it alone near the gate": "Hành lý bỏ không có người trông có thể bị an ninh lấy đi."}}, {"q": "Why does the announcer ask people to go to the gate as soon as possible?", "opts": ["Because the plane will leave early", "Because the gate will close at three fifteen", "Because the new gate is quite far away", "Because the shopping area is closing"], "a": 2, "kind": "inference", "why": "Thông báo nói cổng mới \"is a bit further away. It takes about ten minutes to walk there\", nên cần đi sớm.", "wrong": {"Because the plane will leave early": "Máy bay cất cánh muộn hơn dự kiến 25 phút.", "Because the gate will close at three fifteen": "Ba giờ mười lăm là giờ lên máy bay ban đầu, không phải giờ đóng cổng.", "Because the shopping area is closing": "Không có thông tin về khu mua sắm đóng cửa."}}, {"q": "What should passengers do first?", "opts": ["Go to gate twelve", "Wait at the check-in desks", "Speak to security about their bags", "Go to gate twenty-two"], "a": 3, "kind": "next-step", "why": "Thông báo nói \"Boarding will now take place at gate twenty-two\" và \"please make your way there as soon as possible.\"", "wrong": {"Go to gate twelve": "Cổng mười hai là cổng cũ, đã đổi.", "Wait at the check-in desks": "Thông báo không yêu cầu quay lại quầy làm thủ tục.", "Speak to security about their bags": "Chỉ nhắc không để hành lý không người trông, không yêu cầu gặp an ninh."}}], "notes": {"vocab": [["boarding", "việc lên máy bay"], ["gate", "cổng (ở sân bay)"], ["due to", "dự kiến sẽ, theo lịch", "be due to + động từ nguyên mẫu"], ["hand luggage", "hành lý xách tay"], ["hold", "khoang hành lý của máy bay"], ["unattended", "không có người trông coi"], ["inconvenience", "sự bất tiện"]], "grammar": [["Past form for original plan", "The flight was due to leave from gate twelve", "was due to + động từ nguyên mẫu nói về kế hoạch ban đầu, thường báo hiệu sắp có thay đổi."], ["Passive voice", "Any bags left unattended may be removed by security.", "may be + quá khứ phân từ: bị động, nói điều có thể xảy ra với hành lý."], ["Because + clause", "because the aircraft arrived late", "Because + mệnh đề đầy đủ để giải thích lý do."]], "tips": ["Trong thông báo sân bay, hãy nghe số hiệu chuyến bay, cổng và giờ trước tiên. Khi có thay đổi, thường có hai con số: cũ và mới (twelve, twenty-two).", "Chú ý các từ như now, not, instead: chúng cho biết thông tin nào là mới và đúng."]}}, {"id": "lc-403", "lvl": "B1", "kind": "voicemail", "title": "Landlord Voicemail About the Bathroom Heater", "script": [["Mr Evans", "Hello Maria, this is Peter Evans, your landlord, calling about the flat on Park Street. It's about half past nine on Tuesday morning."], ["Mr Evans", "I got your message about the heater in the bathroom. I'm sorry to hear it's stopped working again."], ["Mr Evans", "I've talked to a repair company called Bright Heating, and they can send someone round on Thursday."], ["Mr Evans", "The engineer will come between ten and twelve. Let me check my notes. Yes, ten and twelve, not eleven and one, as I thought at first."], ["Mr Evans", "Unfortunately, I won't be there myself, because I'll be away on business until Friday. So I'd be grateful if you could let him in."], ["Mr Evans", "If you can't be at home on Thursday morning, please call the company directly and ask for another day. Their number is in the email I sent you."], ["Mr Evans", "You also mentioned a leak under the kitchen sink. I'd like to have a look at that too, but it'll have to wait until next week. In the meantime, please put a bucket under it and try not to use the dishwasher."], ["Mr Evans", "I'll pay for the heater repair, so you don't need to give the engineer any money."], ["Mr Evans", "Please call me back on my mobile if there's a problem, or send me a text message. I'll check my phone in the evenings."], ["Mr Evans", "Thanks very much, Maria. Speak soon. Bye for now."]], "qs": [{"q": "Why is Mr Evans calling Maria?", "opts": ["To arrange a repair to the heater", "To ask her to pay the rent", "To tell her she must move out", "To invite her to a meeting"], "a": 0, "kind": "gist", "why": "Ông nói \"I got your message about the heater in the bathroom\" và sắp xếp thợ đến sửa.", "wrong": {"To ask her to pay the rent": "Không có nhắc đến tiền thuê nhà.", "To tell her she must move out": "Không có nội dung này.", "To invite her to a meeting": "Ông gọi để sắp xếp sửa chữa, không phải mời họp."}}, {"q": "When will the engineer come?", "opts": ["On Thursday between eleven and one", "On Tuesday at half past nine", "On Thursday between ten and twelve", "On Friday morning"], "a": 2, "kind": "number", "why": "Ông nói \"between ten and twelve, not eleven and one\" vào thứ Năm.", "wrong": {"On Thursday between eleven and one": "Ông đã sửa lại: không phải từ mười một đến một giờ.", "On Tuesday at half past nine": "Thứ Ba lúc chín giờ rưỡi là lúc ông gọi điện.", "On Friday morning": "Thứ Sáu là ngày ông đi công tác về, không phải ngày thợ đến."}}, {"q": "What should Maria do about the leak under the sink?", "opts": ["Call the heating company", "Put a bucket under it and avoid the dishwasher", "Fix it herself", "Pay the engineer on Thursday"], "a": 1, "kind": "detail", "why": "Ông nói \"please put a bucket under it and try not to use the dishwasher.\"", "wrong": {"Call the heating company": "Công ty Bright Heating chỉ sửa lò sưởi; chỗ rò rỉ để tuần sau.", "Fix it herself": "Ông nói sẽ tự xem vào tuần sau.", "Pay the engineer on Thursday": "Ông nói ông sẽ trả tiền sửa lò sưởi và Maria không cần trả."}}, {"q": "What should Maria do if she can't be at home on Thursday morning?", "opts": ["Ask her neighbour to pay", "Call Mr Evans to cancel the repair", "Wait until Mr Evans returns on Friday", "Call the repair company and ask for another day"], "a": 3, "kind": "next-step", "why": "Ông nói \"please call the company directly and ask for another day.\"", "wrong": {"Ask her neighbour to pay": "Không có nhắc đến hàng xóm.", "Call Mr Evans to cancel the repair": "Ông bảo gọi công ty, không phải hủy sửa.", "Wait until Mr Evans returns on Friday": "Ông không bảo cô chờ ông về; cô cần gọi công ty."}}, {"q": "What does the message suggest about the heater?", "opts": ["It has had problems before", "It is brand new", "It was fixed last week by Mr Evans", "It cannot be repaired"], "a": 0, "kind": "inference", "why": "Ông nói \"it's stopped working again\", chữ \"again\" cho thấy lò sưởi đã hỏng trước đây.", "wrong": {"It is brand new": "Ông nói nó \"stopped working again\", nên không phải đồ mới.", "It was fixed last week by Mr Evans": "Không có thông tin này.", "It cannot be repaired": "Ông đã sắp xếp thợ đến sửa nên có thể sửa được."}}], "notes": {"vocab": [["landlord", "chủ nhà (cho thuê)"], ["heater", "lò sưởi, máy sưởi"], ["send someone round", "cử người đến (nhà)", "Cụm động từ: send round"], ["engineer", "thợ kỹ thuật"], ["leak", "chỗ rò rỉ"], ["in the meantime", "trong khi chờ đợi"], ["I'd be grateful", "tôi sẽ rất biết ơn", "Cách nhờ lịch sự"]], "grammar": [["Present perfect", "I've talked to a repair company called Bright Heating", "have + quá khứ phân từ: việc vừa làm xong và còn liên quan đến hiện tại."], ["Future with will", "I'll be away on business until Friday.", "will be + trạng thái: nói về điều sẽ diễn ra tại một thời điểm trong tương lai."], ["Polite request with could", "I'd be grateful if you could let him in.", "I'd be grateful if you could + động từ: cách nhờ vả lịch sự."]], "tips": ["Với tin nhắn thoại, hãy nghe ngay: ai gọi, vì sao gọi, và việc người nghe cần làm. Ghi lại ngày, giờ, và các số điện thoại hay tên.", "Cẩn thận khi người nói tự sửa lại thông tin (ten and twelve, not eleven and one): đáp án là lần nói sau."]}}, {"id": "lc-404", "lvl": "B1", "kind": "talk", "title": "Five Habits for Exam Success", "script": [["Dr Lee", "Hello everyone, and thanks for coming to today's study skills session. I'm going to share five simple ideas to help you get ready for your exams."], ["Dr Lee", "First, start early. Many students leave everything until the last week, and then they feel stressed. It's much better to begin about six weeks before the exam and study a little every day."], ["Dr Lee", "Second, make a plan. Write down every subject and decide how many hours you'll give to each one. Give more time to the topics you find difficult, not the ones you already like."], ["Dr Lee", "Third, don't just read your notes again and again. That feels easy, but you often forget it quickly. Instead, test yourself. Close your book, write down what you remember, and then check your answers."], ["Dr Lee", "Fourth, take regular breaks. Studying for fifty minutes and then resting for ten minutes works well for most people. Go for a short walk or drink some water, but try not to check your phone."], ["Dr Lee", "Fifth, look after your body. Sleep is really important. A lot of people stay up all night before an exam, but that's a bad idea, because tired students make more mistakes. Most adults need between seven and nine hours."], ["Dr Lee", "I'd also suggest working with a friend sometimes. Explaining a topic to someone else is a great way to find out what you really understand."], ["Dr Lee", "On the day of the exam, have a proper breakfast, arrive early, and read every question carefully before you begin."], ["Dr Lee", "If you get stuck, don't panic. Move on to the next question and come back to it later."], ["Dr Lee", "So, to sum up: start early, make a plan, test yourself, take breaks and sleep well. Please pick up a free planner at the door on your way out. Thank you."]], "qs": [{"q": "What is the talk mostly about?", "opts": ["Ways to get ready for exams", "How to choose a university", "How to write a good essay", "Why exams are unfair"], "a": 0, "kind": "gist", "why": "Dr Lee nói \"I'm going to share five simple ideas to help you get ready for your exams.\"", "wrong": {"How to choose a university": "Bài nói về cách ôn thi, không phải chọn trường.", "How to write a good essay": "Không nhắc đến cách viết luận.", "Why exams are unfair": "Diễn giả không nói thi cử bất công."}}, {"q": "How long before the exam should students begin studying?", "opts": ["About six weeks", "About one week", "About fifty days", "About ten weeks"], "a": 0, "kind": "number", "why": "Dr Lee nói \"It's much better to begin about six weeks before the exam.\"", "wrong": {"About one week": "Một tuần là thời điểm nhiều sinh viên bắt đầu muộn, điều Dr Lee khuyên không nên.", "About fifty days": "Năm mươi là số phút học, không phải số ngày.", "About ten weeks": "Không có con số mười tuần."}}, {"q": "What does Dr Lee say about breaks?", "opts": ["Students should study for ten minutes and rest for fifty", "Students should not take breaks at all", "Students should try not to check their phones", "Students should watch videos on their phones"], "a": 2, "kind": "detail", "why": "Dr Lee nói \"Go for a short walk or drink some water, but try not to check your phone.\"", "wrong": {"Students should study for ten minutes and rest for fifty": "Ngược lại: học năm mươi phút, nghỉ mười phút.", "Students should not take breaks at all": "Ông khuyên nghỉ thường xuyên.", "Students should watch videos on their phones": "Ông khuyên cố gắng không xem điện thoại."}}, {"q": "What would Dr Lee probably say to a student who stays up all night before an exam?", "opts": ["That it is a good way to learn more", "That it is a bad idea", "That the student only needs four hours of sleep", "That the student should skip breakfast"], "a": 1, "kind": "inference", "why": "Dr Lee nói \"A lot of people stay up all night before an exam, but that's a bad idea, because tired students make more mistakes.\"", "wrong": {"That it is a good way to learn more": "Ông nói đó là ý tồi vì mệt mỏi dễ mắc lỗi.", "That the student only needs four hours of sleep": "Ông nói người lớn cần từ bảy đến chín giờ.", "That the student should skip breakfast": "Ông khuyên ăn sáng đầy đủ vào ngày thi."}}, {"q": "What can students do at the end of the session?", "opts": ["Take a free planner at the door", "Sign up for another class", "Take a practice exam", "Buy a book from Dr Lee"], "a": 0, "kind": "next-step", "why": "Dr Lee nói \"Please pick up a free planner at the door on your way out.\"", "wrong": {"Sign up for another class": "Không có nhắc đến đăng ký lớp khác.", "Take a practice exam": "Không có bài thi thử.", "Buy a book from Dr Lee": "Không có sách nào được bán."}}], "notes": {"vocab": [["get ready for", "chuẩn bị cho"], ["stressed", "căng thẳng"], ["test yourself", "tự kiểm tra bản thân"], ["take regular breaks", "nghỉ giải lao đều đặn"], ["stay up", "thức khuya"], ["get stuck", "bị kẹt, không làm tiếp được"], ["sum up", "tóm tắt lại", "to sum up: tóm lại"]], "grammar": [["Imperatives for advice", "Close your book, write down what you remember", "Câu mệnh lệnh dùng để đưa lời khuyên; nghe như hướng dẫn từng bước."], ["Comparative with much", "It's much better to begin about six weeks before the exam", "much + so sánh hơn: nhấn mạnh sự khác biệt lớn."], ["Negative imperative", "don't just read your notes again and again", "Don't + động từ: khuyên không nên làm gì."]], "tips": ["Trong bài nói có nhiều ý, hãy nghe các từ đánh số như First, Second, Third, Fourth, Fifth: mỗi từ mở ra một ý mới. Ghi nhanh một từ khóa cho mỗi ý.", "Cuối bài, nghe cụm To sum up: ông thường nhắc lại các ý chính và lời nhắc việc cần làm tiếp theo."]}}, {"id": "lc-405", "lvl": "B1", "kind": "conversation", "title": "Understanding Your Blood Test Results", "script": [["Doctor", "Good morning, Mr Hall. Please sit down. I've got your blood test results here, and I'd like to go through them with you."], ["Mr Hall", "Thanks, doctor. I've been a bit worried since Tuesday. Is everything all right?"], ["Doctor", "Mostly, yes. Your cholesterol is a little high. The number is five point eight, and we'd like it to be under five. It's not dangerous yet, but we should deal with it."], ["Mr Hall", "Oh dear. What about my blood sugar? My father has diabetes, so I always worry about that."], ["Doctor", "Good news there. Your blood sugar is completely normal, and your kidneys are working well too. The only other thing is that your iron level is slightly low, which can make you feel tired."], ["Mr Hall", "That explains a lot. I've been feeling worn out for about two months, even after a full night's sleep."], ["Doctor", "I don't think it's anything serious, but let's check it again. I'd like you to come back in six weeks for a second blood test."], ["Mr Hall", "And what should I do until then? Do I need to take any tablets?"], ["Doctor", "Not yet. First, try changing your diet. Eat less fried food, and cut down on cheese and butter. Have more beans, green vegetables and a bit of red meat for the iron."], ["Mr Hall", "That sounds easy enough. What about exercise? I sit at my desk all day."], ["Doctor", "Walking for thirty minutes a day would really help. If your cholesterol is still high after the next test, we'll talk about medication then."], ["Mr Hall", "All right. Should I stop eating before the second test?"], ["Doctor", "Yes, don't eat or drink anything except water for eight hours before. Book the appointment at reception on your way out, and please call us if you feel dizzy."], ["Mr Hall", "Will do. Thank you so much, doctor."]], "qs": [{"q": "Why is Mr Hall at the clinic?", "opts": ["To hear the results of his blood tests", "To get medicine for his tiredness", "To book an operation", "To ask about his father's illness"], "a": 0, "kind": "gist", "why": "Bác sĩ mở đầu: \"I've got your blood test results here, and I'd like to go through them with you.\"", "wrong": {"To get medicine for his tiredness": "Bác sĩ nói chưa cần dùng thuốc (Not yet), nên đây không phải mục đích chính.", "To book an operation": "Không có phẫu thuật nào được nhắc đến.", "To ask about his father's illness": "Bố ông ấy chỉ được nhắc đến như lý do ông lo lắng, không phải mục đích buổi khám."}}, {"q": "Which result is completely normal?", "opts": ["His blood sugar", "His cholesterol", "His iron level", "None of them"], "a": 0, "kind": "detail", "why": "Bác sĩ nói: \"Your blood sugar is completely normal, and your kidneys are working well too.\"", "wrong": {"His cholesterol": "Cholesterol hơi cao: \"a little high\".", "His iron level": "Sắt hơi thấp: \"slightly low\".", "None of them": "Đường huyết và thận đều bình thường."}}, {"q": "When should Mr Hall have the second blood test?", "opts": ["In two weeks", "In two months", "In six weeks", "In eight weeks"], "a": 2, "kind": "number", "why": "Bác sĩ nói: \"come back in six weeks for a second blood test.\"", "wrong": {"In two weeks": "Hai tháng là thời gian ông mệt mỏi, không phải thời gian tái khám.", "In two months": "Hai tháng là thời gian ông cảm thấy mệt, không phải lịch xét nghiệm lại.", "In eight weeks": "Tám giờ là thời gian nhịn ăn, không phải tám tuần."}}, {"q": "What must he do before the second test?", "opts": ["Take tablets for a month", "Stop all exercise", "Eat more red meat only", "Eat and drink nothing except water for eight hours"], "a": 3, "kind": "next-step", "why": "Bác sĩ dặn: \"don't eat or drink anything except water for eight hours before.\"", "wrong": {"Take tablets for a month": "Bác sĩ nói \"Not yet\" về việc dùng thuốc.", "Stop all exercise": "Bác sĩ khuyên đi bộ ba mươi phút mỗi ngày, không phải ngừng vận động.", "Eat more red meat only": "Thịt đỏ chỉ là một phần trong chế độ ăn, không phải yêu cầu trước xét nghiệm."}}, {"q": "What does the doctor think is the likely reason for his tiredness?", "opts": ["Diabetes", "Low iron in his blood", "Kidney problems", "Too much cholesterol"], "a": 1, "kind": "inference", "why": "Bác sĩ nói sắt thấp \"can make you feel tired\" và bệnh nhân đáp \"That explains a lot.\"", "wrong": {"Diabetes": "Đường huyết bình thường nên không phải tiểu đường.", "Kidney problems": "Bác sĩ nói thận hoạt động tốt.", "Too much cholesterol": "Cholesterol cao không được nói là nguyên nhân gây mệt."}}], "notes": {"vocab": [["blood test results", "kết quả xét nghiệm máu"], ["cholesterol", "cholesterol, mỡ máu"], ["blood sugar", "đường huyết"], ["worn out", "kiệt sức, rất mệt", "cách nói thân mật"], ["cut down on", "giảm bớt", "cụm động từ"], ["dizzy", "chóng mặt"]], "grammar": [["Zero/first conditional with if", "If your cholesterol is still high after the next test, we'll talk about medication then.", "Câu điều kiện loại 1: if + hiện tại đơn, will + động từ, nói về khả năng có thể xảy ra trong tương lai."], ["Present perfect continuous", "I've been feeling worn out for about two months", "Thì hiện tại hoàn thành tiếp diễn diễn tả việc kéo dài từ quá khứ đến nay."]], "tips": ["Khi bác sĩ giải thích kết quả, hãy nghe từng chỉ số và tính từ đi kèm như high, low, normal để biết kết quả nào ổn.", "Chú ý con số và đơn vị thời gian như six weeks và eight hours, vì chúng hay bị nhầm với nhau."]}}, {"id": "lc-406", "lvl": "B1", "kind": "interview", "title": "A Volunteer Nurse in the Mountains", "script": [["Host", "Today we're talking to Maria Santos, a nurse who spends part of every year working as a volunteer. Maria, welcome to the show."], ["Maria", "Thanks for having me. It's lovely to be here."], ["Host", "So where do you volunteer, and how long have you been doing it?"], ["Maria", "I work with a small charity that runs mobile clinics in mountain villages. I started four years ago, and now I go twice a year for three weeks each time."], ["Host", "That sounds tough. What does a normal day look like?"], ["Maria", "We get up at six, drive for about two hours, and set up the clinic in a school or a community hall. By eight o'clock there's often a queue of sixty or seventy people."], ["Host", "What kind of problems do you see?"], ["Maria", "Mostly simple things, actually. Infections, high blood pressure, children with coughs, and lots of people who've never had a check-up. I also give vaccinations and show mothers how to look after a baby."], ["Host", "Was there anything that surprised you at first?"], ["Maria", "The language, definitely. I didn't expect to need an interpreter every day. At the beginning I felt a bit helpless, but I've picked up some local words, so now I can greet patients and explain simple instructions."], ["Host", "And what's the hardest part?"], ["Maria", "Having to send people to hospital. Sometimes the nearest one is five hours away, and some families can't afford the journey. That's when I feel frustrated."], ["Host", "So why do you keep going back?"], ["Maria", "Because it reminds me why I became a nurse. At home I'm always rushing, but there I can spend time with each patient. I come back tired, but happy. My advice to students is to start small, join a local clinic first, and just be kind and willing to learn."]], "qs": [{"q": "What is the interview mainly about?", "opts": ["A new hospital in the mountains", "A nurse's experience of volunteering in remote villages", "A course for interpreters", "How to become a doctor"], "a": 1, "kind": "gist", "why": "Người dẫn nói: \"a nurse who spends part of every year working as a volunteer.\"", "wrong": {"A new hospital in the mountains": "Bệnh viện gần nhất cách xa năm giờ, không có bệnh viện mới nào được nhắc.", "A course for interpreters": "Phiên dịch chỉ được nhắc như một khó khăn ban đầu.", "How to become a doctor": "Maria là y tá và không nói về việc trở thành bác sĩ."}}, {"q": "How often does Maria go, and for how long each time?", "opts": ["Twice a year for three weeks", "Four times a year for two weeks", "Once a year for six weeks", "Twice a year for four weeks"], "a": 0, "kind": "number", "why": "Maria nói: \"I go twice a year for three weeks each time.\"", "wrong": {"Four times a year for two weeks": "Bốn là số năm bà đã tham gia, không phải số lần mỗi năm.", "Once a year for six weeks": "Bà nói \"twice a year\", không phải một lần.", "Twice a year for four weeks": "Bốn năm là thời gian bà làm việc, mỗi chuyến chỉ ba tuần."}}, {"q": "What does Maria find hardest?", "opts": ["Getting up at six o'clock", "Giving vaccinations", "Sending patients to a hospital that is very far away", "Teaching mothers"], "a": 2, "kind": "detail", "why": "Maria nói: \"Having to send people to hospital. Sometimes the nearest one is five hours away.\"", "wrong": {"Getting up at six o'clock": "Việc dậy lúc sáu giờ không được nói là khó nhất.", "Giving vaccinations": "Bà tiêm chủng bình thường, không nói đó là khó khăn.", "Teaching mothers": "Hướng dẫn các bà mẹ không bị nói là khó."}}, {"q": "Why does Maria prefer the volunteer work to her job at home?", "opts": ["The pay is much better", "There are fewer patients", "The work is easier", "She can spend more time with each patient"], "a": 3, "kind": "inference", "why": "Maria nói ở nhà \"I'm always rushing, but there I can spend time with each patient.\"", "wrong": {"The pay is much better": "Không có nhắc đến lương.", "There are fewer patients": "Có hàng chục người xếp hàng từ tám giờ sáng.", "The work is easier": "Bà nói mình về nhà mệt, nên công việc không hề nhẹ."}}, {"q": "What does Maria advise a student to do first?", "opts": ["Join a local clinic", "Learn the local language", "Travel abroad at once", "Wait until they are qualified"], "a": 0, "kind": "next-step", "why": "Maria khuyên: \"start small, join a local clinic first.\"", "wrong": {"Learn the local language": "Bà chỉ kể mình học dần một số từ địa phương, không đưa ra lời khuyên này.", "Travel abroad at once": "Bà khuyên \"start small\".", "Wait until they are qualified": "Bà không nói phải chờ tốt nghiệp."}}], "notes": {"vocab": [["volunteer", "tình nguyện viên"], ["mobile clinics", "phòng khám lưu động"], ["check-up", "khám sức khỏe tổng quát"], ["vaccinations", "tiêm chủng"], ["interpreter", "phiên dịch viên"], ["picked up", "học được, tiếp thu dần", "cụm động từ"], ["frustrated", "bực bội, nản lòng"]], "grammar": [["Present perfect for experience", "I've picked up some local words", "Hiện tại hoàn thành dùng khi kết quả của việc đã học vẫn còn đến bây giờ."], ["Gerund as subject", "Having to send people to hospital.", "Cụm Having to + động từ dùng như danh từ để nói về một việc bắt buộc phải làm."]], "tips": ["Trong phỏng vấn, hãy nghe câu hỏi của người dẫn trước vì nó cho biết chủ đề của câu trả lời.", "Chú ý các con số về tần suất và thời gian như twice a year hay three weeks."]}}, {"id": "lc-407", "lvl": "B1", "kind": "conversation", "title": "Two Groups, One Room", "script": [["Helen", "Hello, community centre office, Helen speaking. Oh, hi Anna. What can I do for you?"], ["Anna", "Hi Helen. I'm here for the book club. We booked Room Two for tonight at seven, but there's a yoga class in there already."], ["Helen", "Oh no. Let me check the diary. You're right, it says seven o'clock for both of you. Tom, could you come over for a second?"], ["Tom", "Hi. Is there a problem? I've taught that class in Room Two every Thursday for two years."], ["Helen", "There's been a double booking. Anna's book club reserved the room for tonight too."], ["Anna", "I booked it three weeks ago by email, and I've got the confirmation here on my phone."], ["Tom", "I believe you, but I've got twelve students arriving in fifteen minutes, and they need the space and the mats."], ["Helen", "Okay, let's work this out. Room Three is free tonight, but it only holds ten people. How many are in your book club, Anna?"], ["Anna", "Eight, usually, but one of us is bringing a friend, so nine. That should fit."], ["Tom", "That's fine with me. And Anna, sorry about the mix-up."], ["Anna", "No problem, but is Room Three heated? It was freezing last time."], ["Helen", "Good point. I'll turn the heating on right now, and I'll bring in some tea and biscuits as an apology. It's on the house."], ["Anna", "That's very kind. Could you also send me a new confirmation so this doesn't happen again?"], ["Helen", "Of course. I'll email it before six, and from now on I'll check the diary twice."]], "qs": [{"q": "What is the problem at the start of the conversation?", "opts": ["The yoga teacher is late", "Two groups have booked the same room", "The room is too cold", "Anna forgot to book a room"], "a": 1, "kind": "gist", "why": "Helen nói: \"There's been a double booking.\"", "wrong": {"The yoga teacher is late": "Tom đã có mặt, vấn đề không phải việc trễ giờ.", "The room is too cold": "Phòng lạnh chỉ là lo ngại về sau, đối với Phòng Ba.", "Anna forgot to book a room": "Anna đã đặt phòng và có email xác nhận."}}, {"q": "How many people will be in Anna's group tonight?", "opts": ["Nine", "Eight", "Ten", "Twelve"], "a": 0, "kind": "number", "why": "Anna nói: \"Eight, usually, but one of us is bringing a friend, so nine.\"", "wrong": {"Eight": "Tám là số thường lệ, nhưng tối nay có thêm một người bạn.", "Ten": "Mười là sức chứa của Phòng Ba.", "Twelve": "Mười hai là số học viên yoga của Tom."}}, {"q": "Who will change rooms?", "opts": ["Tom's yoga class", "Both groups", "Anna's book club", "Neither group"], "a": 2, "kind": "inference", "why": "Phòng Ba chứa được mười người và Tom đồng ý, nên nhóm đọc sách của Anna chuyển: \"Room Three is free tonight... That should fit.\"", "wrong": {"Tom's yoga class": "Tom giữ Phòng Hai vì lớp yoga cần mat và chỗ rộng.", "Both groups": "Chỉ một nhóm chuyển phòng.", "Neither group": "Hai nhóm không thể dùng chung Phòng Hai."}}, {"q": "Why does Anna ask about the heating?", "opts": ["She wants a warmer room for yoga", "The heating in Room Two is broken", "She likes hot tea", "Room Three was very cold last time"], "a": 3, "kind": "detail", "why": "Anna hỏi: \"is Room Three heated? It was freezing last time.\"", "wrong": {"She wants a warmer room for yoga": "Anna không tham gia yoga.", "The heating in Room Two is broken": "Không có thông tin này.", "She likes hot tea": "Trà là món Helen tự đề nghị mang đến."}}, {"q": "What will Helen do by six o'clock?", "opts": ["Email Anna a new confirmation", "Call Tom's students", "Cancel the yoga class", "Move the tables"], "a": 0, "kind": "next-step", "why": "Helen nói: \"I'll email it before six.\"", "wrong": {"Call Tom's students": "Helen không hứa gọi học viên của Tom.", "Cancel the yoga class": "Lớp yoga vẫn diễn ra như thường.", "Move the tables": "Helen không nhắc đến việc dọn bàn."}}], "notes": {"vocab": [["double booking", "đặt trùng lịch"], ["diary", "sổ lịch hẹn"], ["confirmation", "thư xác nhận"], ["mix-up", "sự nhầm lẫn"], ["work this out", "tìm ra cách giải quyết", "cụm động từ"], ["on the house", "miễn phí, do cơ sở mời"]], "grammar": [["Present perfect for a recent problem", "There's been a double booking.", "There has been dùng để nói về sự việc vừa xảy ra và còn ảnh hưởng hiện tại."], ["Will for instant decisions", "I'll turn the heating on right now", "Will dùng để quyết định hoặc hứa làm ngay tại lúc nói."]], "tips": ["Khi có hai bên tranh chấp, hãy nghe ai là người nhường và giải pháp cuối cùng là gì.", "Cẩn thận với các con số gần nhau như eight, nine, ten và twelve, thường dùng làm đáp án gây nhiễu."]}}, {"id": "lc-408", "lvl": "B1", "kind": "talk", "title": "Why Walking Is Good Medicine", "script": [["Dr Lee", "Hello everyone, and thanks for coming to today's health talk. I'd like to speak about the simplest exercise there is, and that's walking."], ["Dr Lee", "Many people think you need a gym membership to get fit, but that's not true. Walking is free, you can do it almost anywhere, and it's gentle on your joints."], ["Dr Lee", "Let's start with the heart. Studies show that people who walk briskly for thirty minutes, five days a week, have a lower risk of heart disease and high blood pressure."], ["Dr Lee", "Walking also helps to control weight. You won't lose kilos overnight, but if you walk every day and keep an eye on what you eat, you'll notice a difference after a few months."], ["Dr Lee", "It's good for your mind too. A short walk outside can lift your mood, and many people find it helps them think more clearly."], ["Dr Lee", "Now, you may be wondering how far to go. Many people aim for ten thousand steps a day, but that's just a popular target. If you currently do three thousand, going up to five thousand is already a great improvement."], ["Dr Lee", "My advice is to build up slowly. Start with ten minutes a day, add five minutes each week, and wear comfortable shoes."], ["Dr Lee", "Here are some tips to make it a habit. Get off the bus one stop early, take the stairs instead of the lift, and call a friend while you walk instead of sitting down to chat."], ["Dr Lee", "A quick warning, though. If you feel chest pain, severe dizziness or you're short of breath, stop and see a doctor straight away."], ["Dr Lee", "To sum up, walking protects your heart, helps your weight, and improves your mood. It costs nothing, and almost everybody can do it."], ["Dr Lee", "So this week, why not try a ten minute walk after dinner? Thank you for listening, and I'll take your questions now."]], "qs": [{"q": "What is the main message of the talk?", "opts": ["Regular walking is an easy way to improve your health", "Everyone needs a gym membership", "Running is better than walking", "Ten thousand steps are compulsory"], "a": 0, "kind": "gist", "why": "Bác sĩ nói đi bộ là bài tập đơn giản nhất, \"free\" và \"gentle on your joints\".", "wrong": {"Everyone needs a gym membership": "Bác sĩ nói ngược lại: không cần thẻ phòng tập.", "Running is better than walking": "Bài nói không so sánh với chạy bộ.", "Ten thousand steps are compulsory": "Đó chỉ là \"a popular target\", không bắt buộc."}}, {"q": "Which benefit is NOT mentioned?", "opts": ["A lower risk of heart disease", "Stronger arm muscles", "A better mood", "Help with controlling weight"], "a": 1, "kind": "detail", "why": "Bác sĩ nhắc đến tim, cân nặng và tâm trạng, không nhắc đến cơ tay.", "wrong": {"A lower risk of heart disease": "Có được nhắc: tim mạch.", "A better mood": "Có được nhắc: \"lift your mood\".", "Help with controlling weight": "Có được nhắc: kiểm soát cân nặng."}}, {"q": "How should a beginner increase his walking time?", "opts": ["Add ten minutes every day", "Double it every week", "Add five minutes each week", "Add thirty minutes each month"], "a": 2, "kind": "number", "why": "Bác sĩ nói: \"Start with ten minutes a day, add five minutes each week.\"", "wrong": {"Add ten minutes every day": "Mười phút là thời gian bắt đầu, không phải mức tăng.", "Double it every week": "Không có nói tăng gấp đôi.", "Add thirty minutes each month": "Ba mươi phút là mục tiêu cho người đi nhanh, không phải mức tăng."}}, {"q": "What should someone do if they get chest pain while walking?", "opts": ["Walk more slowly and continue", "Drink water and carry on", "Call a friend to walk with", "Stop and see a doctor immediately"], "a": 3, "kind": "next-step", "why": "Bác sĩ cảnh báo: \"If you feel chest pain... stop and see a doctor straight away.\"", "wrong": {"Walk more slowly and continue": "Bác sĩ bảo phải dừng lại.", "Drink water and carry on": "Không có lời khuyên này.", "Call a friend to walk with": "Gọi bạn là mẹo tạo thói quen, không phải xử trí đau ngực."}}, {"q": "What does the speaker mean by saying ten thousand steps is just a popular target?", "opts": ["Fewer steps can still be beneficial", "It is an official medical rule", "Nobody can reach it", "Steps are not worth counting"], "a": 0, "kind": "inference", "why": "Ông nói tăng từ ba nghìn lên năm nghìn bước \"is already a great improvement\".", "wrong": {"It is an official medical rule": "Ông nói đó chỉ là mục tiêu phổ biến, không phải quy định.", "Nobody can reach it": "Ông không nói không ai đạt được.", "Steps are not worth counting": "Ông vẫn khuyến khích tăng số bước."}}], "notes": {"vocab": [["gentle on your joints", "nhẹ nhàng cho khớp"], ["briskly", "nhanh, hăng hái"], ["risk of heart disease", "nguy cơ bệnh tim"], ["lift your mood", "cải thiện tâm trạng"], ["build up slowly", "tăng dần dần", "cụm động từ"], ["short of breath", "khó thở"]], "grammar": [["Instead of + verb-ing", "take the stairs instead of the lift", "Instead of + V-ing nghĩa là thay vì làm việc gì."], ["Imperative advice", "Start with ten minutes a day", "Câu mệnh lệnh dùng để đưa ra lời khuyên trực tiếp."]], "tips": ["Trong bài nói về sức khỏe, hãy nghe các lợi ích được liệt kê theo thứ tự và các từ như first, also, to sum up.", "Các con số về thời gian và số bước thường đi kèm lời khuyên, hãy ghi lại số đầu tiên và mức tăng."]}}, {"id": "lc-501", "lvl": "B2", "kind": "conversation", "title": "Constructive Feedback After a Client Presentation", "script": [["Laura", "James, have you got a minute? I wanted to talk about the presentation you gave to the client yesterday."], ["James", "Sure. To be honest, I was hoping you'd say something, because I felt it didn't go as well as it could have."], ["Laura", "Well, I don't think it was bad at all. The structure was really clear, and the case study you chose was exactly what the client needed. They were nodding the whole way through."], ["James", "That's reassuring. I spent most of last weekend on those slides, so I'm glad it showed."], ["Laura", "It did. If I can be completely honest, though, a couple of things could be improved. The first is the pace. You got through the first ten slides in about eight minutes, and I think some of the finance people were struggling to keep up."], ["James", "Hmm, I suppose I do tend to speed up when I'm nervous. Is that what you noticed?"], ["Laura", "Partly, yes. I'd suggest pausing after each key figure, so the numbers have time to sink in. That would also give people a chance to ask questions, which, in my experience, clients appreciate."], ["James", "Fair enough. What was the second thing?"], ["Laura", "The slides themselves. The sales chart on slide twelve was packed with so much detail that it couldn't be read from the back of the room. It might be worth cutting it down to the three figures that really matter."], ["James", "I thought it might be too busy, but I ran out of time to simplify it. I was told the deadline was Friday, and then the meeting was moved to Wednesday."], ["Laura", "That's not your fault at all, and I'll raise it with Mark, because schedules shouldn't be changed without warning. But for next time, even a quick review with a colleague would catch things like that."], ["James", "Would you be willing to look at my next draft? I've got another presentation in three weeks."], ["Laura", "Of course. Send it over a week before the date, and I'll go through it with you over coffee. Honestly, you have a real talent for explaining complicated ideas, and a little polish will make it even stronger."], ["James", "Thanks, Laura. I really appreciate you being so direct but kind about it."], ["Laura", "That's the best way to learn. Now, let's get you ready for next time."]], "qs": [{"q": "What is Laura's main purpose in talking to James?", "opts": ["To give him feedback on his presentation", "To complain about the client", "To ask him to change the deadline", "To praise him and nothing else"], "a": 0, "kind": "gist", "why": "Laura mở đầu: \"I wanted to talk about the presentation you gave to the client yesterday.\"", "wrong": {"To complain about the client": "Khách hàng phản ứng tốt, họ gật đầu suốt buổi.", "To ask him to change the deadline": "Chính lịch họp bị đổi, Laura sẽ nói với Mark.", "To praise him and nothing else": "Laura còn đưa ra hai điểm cần cải thiện."}}, {"q": "What was the first problem Laura mentions?", "opts": ["The case study was wrong", "He spoke too fast", "He arrived late", "He ignored the questions"], "a": 1, "kind": "detail", "why": "Laura nói: \"The first is the pace\" và James đồng ý mình hay nói nhanh khi lo lắng.", "wrong": {"The case study was wrong": "Laura khen case study là đúng thứ khách cần.", "He arrived late": "Không có chuyện đến muộn.", "He ignored the questions": "Laura chỉ gợi ý dừng lại để mọi người đặt câu hỏi."}}, {"q": "Which slide had the chart that was hard to read?", "opts": ["Slide two", "Slide ten", "Slide twelve", "Slide eight"], "a": 2, "kind": "number", "why": "Laura nói: \"The sales chart on slide twelve was packed with so much detail.\"", "wrong": {"Slide two": "Con số hai không được nhắc.", "Slide ten": "Mười slide là phần đầu bài thuyết trình đi quá nhanh.", "Slide eight": "Tám phút là thời gian của mười slide đầu."}}, {"q": "Why did James not simplify the chart?", "opts": ["He thought it was already clear", "Mark told him not to", "He forgot about it", "The meeting was moved earlier than expected"], "a": 3, "kind": "detail", "why": "James nói: \"I was told the deadline was Friday, and then the meeting was moved to Wednesday.\"", "wrong": {"He thought it was already clear": "Anh nói mình đã nghĩ nó quá rối.", "Mark told him not to": "Mark không liên quan đến việc này, Laura sẽ phản ánh với Mark.", "He forgot about it": "Anh nói mình hết thời gian chứ không quên."}}, {"q": "How does Laura feel about James's abilities overall?", "opts": ["She thinks he is talented and just needs polish", "She thinks he should not present again", "She believes he is careless", "She is disappointed in his work"], "a": 0, "kind": "inference", "why": "Laura nói: \"you have a real talent for explaining complicated ideas, and a little polish will make it even stronger.\"", "wrong": {"She thinks he should not present again": "Laura sẵn lòng giúp anh chuẩn bị bài sau.", "She believes he is careless": "Cô nói lỗi lịch trình không phải lỗi của anh.", "She is disappointed in his work": "Cô khen cấu trúc và nói anh có tài giải thích ý tưởng phức tạp."}}, {"q": "What will James do before his next presentation?", "opts": ["Ask Mark to change the schedule", "Send Laura his draft a week before the date", "Practise with the client", "Send the slides the day before"], "a": 1, "kind": "next-step", "why": "Laura nói: \"Send it over a week before the date, and I'll go through it with you over coffee.\"", "wrong": {"Ask Mark to change the schedule": "Laura mới là người nói với Mark.", "Practise with the client": "Không có chi tiết này.", "Send the slides the day before": "Laura bảo gửi trước một tuần."}}], "notes": {"vocab": [["reassuring", "làm yên tâm"], ["struggling to keep up", "vất vả theo kịp"], ["sink in", "thấm vào, được hiểu rõ"], ["packed with", "chứa đầy"], ["ran out of time", "hết thời gian"], ["raise it with", "nêu vấn đề với ai"], ["polish", "sự trau chuốt"]], "grammar": [["Softening criticism with would", "I'd suggest pausing after each key figure", "I'd suggest + V-ing là cách nói lịch sự để đưa ra góp ý nhẹ nhàng."], ["Passive voice", "I was told the deadline was Friday", "Câu bị động dùng khi không quan trọng ai nói; điều quan trọng là thông tin."], ["Modal for obligation in the passive", "schedules shouldn't be changed without warning", "Shouldn't + be + V3 là câu bị động với động từ khuyết thiếu, nói điều không nên xảy ra."]], "tips": ["Khi nghe góp ý, hãy chú ý các cụm làm mềm như If I can be completely honest, though, vì sau đó thường là điểm chê.", "Hãy nghe kỹ điều gì thay đổi, ví dụ hạn chót Friday rồi chuyển thành Wednesday."]}}, {"id": "lc-502", "lvl": "B2", "kind": "talk", "title": "An Introduction to the Nervous System", "script": [["Professor Clarke", "Good morning, everybody, and welcome to the first lecture in our neuroscience block. Today I want to give you the big picture of the nervous system."], ["Professor Clarke", "Let me begin with a simple question. How does your hand know to pull away from a hot cup before you've even realised it hurts? The answer lies in the nervous system, which is essentially the body's communication network."], ["Professor Clarke", "Broadly speaking, we divide it into two parts. The central nervous system consists of the brain and the spinal cord. The peripheral nervous system, on the other hand, includes all the nerves that run from the spinal cord to the rest of the body."], ["Professor Clarke", "The basic working unit of both is the neuron, or nerve cell. Neurons pass electrical signals along their length, and they communicate across tiny gaps using chemical messengers called neurotransmitters."], ["Professor Clarke", "Now, the peripheral system is divided again. The somatic part controls voluntary movements, such as picking up a pen. The autonomic part, by contrast, regulates things that happen without conscious effort, like your heartbeat, digestion and breathing."], ["Professor Clarke", "The autonomic system itself has two branches, and it's worth remembering them now. The sympathetic branch prepares the body for action, the so-called fight or flight response. The parasympathetic branch does the opposite, and is responsible for rest and digestion."], ["Professor Clarke", "Going back to the hot cup, what you experienced was a reflex. The signal doesn't travel all the way to the brain first. It's processed in the spinal cord, which sends an instruction back to the muscle almost immediately. The brain is informed afterwards, and that's when you feel the pain."], ["Professor Clarke", "This is clinically important. When a doctor taps your knee with a hammer, they're testing that reflex pathway. If the response is absent or exaggerated, it may suggest damage somewhere along the nerve or the spinal cord."], ["Professor Clarke", "I should stress, however, that the nervous system doesn't work in isolation. It's closely linked to the hormonal system, and together they keep the body in balance."], ["Professor Clarke", "A word on how to study this topic. Many students try to memorise long lists of nerves, and I'd strongly advise against it. Instead, draw the pathways yourself, from the sensation to the response. If you can explain the route of a single reflex, you've understood the principle."], ["Professor Clarke", "For next week, please read the first chapter of the textbook, which covers the structure of the neuron, and bring one question that you'd like to see answered. The practical session will be held on Thursday at two o'clock in the anatomy lab."], ["Professor Clarke", "Right, that's enough from me for now. Let's take a five minute break, and then we'll look at some brain images."]], "qs": [{"q": "What is the main aim of this lecture?", "opts": ["To give an overview of the nervous system", "To teach the names of all the nerves", "To explain how hormones work", "To describe a single disease"], "a": 0, "kind": "gist", "why": "Giáo sư nói: \"I want to give you the big picture of the nervous system.\"", "wrong": {"To teach the names of all the nerves": "Giáo sư khuyên không nên học thuộc danh sách dây thần kinh.", "To explain how hormones work": "Hệ nội tiết chỉ được nhắc ngắn gọn là có liên quan.", "To describe a single disease": "Bài giảng không bàn về một bệnh cụ thể."}}, {"q": "Which structures make up the central nervous system?", "opts": ["The brain and the spinal cord", "The spinal cord and the nerves in the arms", "The brain and the heart", "All the nerves in the body"], "a": 0, "kind": "detail", "why": "Giáo sư nói: \"The central nervous system consists of the brain and the spinal cord.\"", "wrong": {"The spinal cord and the nerves in the arms": "Dây thần kinh ở tay thuộc hệ ngoại biên.", "The brain and the heart": "Tim không thuộc hệ thần kinh trung ương.", "All the nerves in the body": "Đó là hệ ngoại biên cộng với một phần khác."}}, {"q": "What does the autonomic part control?", "opts": ["Movements we choose to make", "Functions that happen without conscious effort", "Only the sensation of pain", "The chemical messengers"], "a": 1, "kind": "detail", "why": "Giáo sư nói: \"The autonomic part... regulates things that happen without conscious effort, like your heartbeat, digestion and breathing.\"", "wrong": {"Movements we choose to make": "Đó là phần somatic, kiểm soát vận động chủ ý.", "Only the sensation of pain": "Cảm giác đau được nhắc ở phần phản xạ, không phải chức năng của hệ tự chủ.", "The chemical messengers": "Chất dẫn truyền thần kinh là phương tiện giao tiếp giữa các neuron."}}, {"q": "Why does a reflex happen so quickly?", "opts": ["The brain sends the signal faster", "The muscles act without nerves", "The signal is handled in the spinal cord first", "The pain is felt before the movement"], "a": 2, "kind": "inference", "why": "Giáo sư nói: \"It's processed in the spinal cord... The brain is informed afterwards.\"", "wrong": {"The brain sends the signal faster": "Não chỉ được thông báo sau đó.", "The muscles act without nerves": "Vẫn cần dây thần kinh truyền tín hiệu.", "The pain is felt before the movement": "Cảm giác đau đến sau cử động."}}, {"q": "When is the practical session?", "opts": ["Thursday at two o'clock", "Thursday at five o'clock", "Tuesday at two o'clock", "Next week in the lecture hall"], "a": 0, "kind": "number", "why": "Giáo sư nói: \"The practical session will be held on Thursday at two o'clock in the anatomy lab.\"", "wrong": {"Thursday at five o'clock": "Năm phút là thời gian nghỉ giải lao.", "Tuesday at two o'clock": "Ngày thực hành là thứ Năm.", "Next week in the lecture hall": "Thực hành diễn ra ở phòng thí nghiệm giải phẫu."}}, {"q": "What should the students do before next week?", "opts": ["Memorise a list of nerves", "Write an essay on hormones", "Test each other's reflexes", "Read a chapter and bring one question"], "a": 3, "kind": "next-step", "why": "Giáo sư nói: \"please read the first chapter of the textbook... and bring one question.\"", "wrong": {"Memorise a list of nerves": "Giáo sư khuyên không làm vậy.", "Write an essay on hormones": "Không có bài luận nào được giao.", "Test each other's reflexes": "Không có yêu cầu này."}}], "notes": {"vocab": [["nervous system", "hệ thần kinh"], ["spinal cord", "tủy sống"], ["neuron", "nơ-ron, tế bào thần kinh"], ["voluntary", "có chủ ý"], ["reflex", "phản xạ"], ["on the other hand", "mặt khác", "từ nối"], ["in isolation", "một cách tách biệt"]], "grammar": [["Contrast signposts", "The autonomic part, by contrast, regulates", "By contrast và on the other hand là từ nối chỉ sự đối lập giữa hai ý."], ["Passive voice", "The practical session will be held on Thursday", "Câu bị động tương lai: will be + V3, dùng cho sự kiện đã lên kế hoạch."]], "tips": ["Trong bài giảng, hãy nghe các từ đánh dấu như broadly speaking, on the other hand và to sum up để theo dõi cấu trúc.", "Thông tin thực tế như bài đọc và lịch thực hành thường nằm ở cuối bài, nên đừng mất tập trung."]}}, {"id": "lc-503", "lvl": "B2", "kind": "interview", "title": "A Sleep Researcher on Weekend Lie-ins", "script": [["Host", "Welcome to the show. Today I'm talking with Dr Maya Rivera, a sleep researcher who has spent ten years studying teenagers and students. Dr Rivera, thanks for joining us."], ["Dr Rivera", "Thanks for having me. It's a pleasure."], ["Host", "Let's start with a big claim. A lot of people say they function perfectly well on five hours of sleep. Is that true?"], ["Dr Rivera", "Well, that's what many of them believe, but our data suggests otherwise. In our lab, people who slept five hours a night for a week thought they were coping fine. However, their scores on attention tasks had dropped by almost a third. The problem is that tiredness itself makes it harder to notice how tired you are."], ["Host", "So how much sleep do adults actually need?"], ["Dr Rivera", "It varies a little, but most adults need between seven and nine hours. I'd originally have said eight, but newer studies show that a range is more realistic. Students are often surprised to hear that teenagers need even more, around nine hours."], ["Host", "And what about the weekend? Lots of students sleep until noon on Saturday to catch up."], ["Dr Rivera", "That's a really common habit, and it does help a bit, but it isn't a cure. If you sleep until noon, your body clock shifts later, and then on Sunday night you can't fall asleep. We call it social jet lag. It's like flying across two time zones every weekend."], ["Host", "That's a vivid comparison. What would you recommend instead?"], ["Dr Rivera", "Keep your wake-up time within an hour of your usual time, even at the weekend. If you're exhausted, a short nap of twenty minutes in the early afternoon is much better than a long lie-in. Anything longer than that and you risk waking up groggy."], ["Host", "Many listeners look at their phones in bed. Is that really a problem?"], ["Dr Rivera", "It's partly the light, but honestly the bigger issue is the content. Scrolling through news or messages keeps your brain alert. I suggest putting the phone in another room at least thirty minutes before bed. Reading a paper book works far better."], ["Host", "And what about caffeine?"], ["Dr Rivera", "Coffee stays in your system for about six hours, so a cup at four in the afternoon is still working at ten at night. I tell students to stop drinking it after lunch."], ["Host", "Dr Rivera, if listeners remember only one thing, what should it be?"], ["Dr Rivera", "Consistency. Go to bed and get up at roughly the same time every day. It sounds boring, but it's the most effective change you can make, and it costs nothing."], ["Host", "Wonderful advice. Thank you so much."]], "qs": [{"q": "What is the main subject of the interview?", "opts": ["How scientists measure brain activity", "How much sleep people need and which habits help", "Why students should study at night", "How to treat serious sleep disorders"], "a": 1, "kind": "gist", "why": "Cả cuộc phỏng vấn nói về lượng giấc ngủ cần thiết và những thói quen giúp ngủ tốt hơn, như ngủ giờ đều đặn, ngủ trưa ngắn và bỏ cà phê.", "wrong": {"How scientists measure brain activity": "Bà chỉ nhắc đến thí nghiệm tại phòng thí nghiệm, không nói về đo hoạt động não.", "Why students should study at night": "Bà không khuyên học ban đêm; bà khuyên ngủ đúng giờ.", "How to treat serious sleep disorders": "Không có phần nào bàn về điều trị rối loạn giấc ngủ nghiêm trọng."}}, {"q": "What happened to people who slept only five hours a night for a week?", "opts": ["They felt much more tired than usual", "They did better on attention tasks", "Their attention scores fell although they felt fine", "They needed a nap every afternoon"], "a": 2, "kind": "detail", "why": "Bà nói họ \"thought they were coping fine\" nhưng điểm các bài tập chú ý \"had dropped by almost a third\".", "wrong": {"They felt much more tired than usual": "Vấn đề là họ không nhận ra mình mệt, nên họ vẫn cảm thấy ổn.", "They did better on attention tasks": "Điểm chú ý giảm chứ không tăng.", "They needed a nap every afternoon": "Không có thông tin về việc họ cần ngủ trưa mỗi ngày."}}, {"q": "How much sleep does Dr Rivera say teenagers need?", "opts": ["About nine hours", "About eight hours", "About seven hours", "About ten hours"], "a": 0, "kind": "number", "why": "Bà nói thanh thiếu niên cần nhiều hơn người lớn, \"around nine hours\". Con số tám là con số bà từng định nói cho người lớn.", "wrong": {"About seven hours": "Bảy giờ là mức thấp nhất của người lớn, không phải của thiếu niên.", "About eight hours": "Tám giờ là con số bà từng nói cho người lớn trước khi sửa lại.", "About ten hours": "Mười giờ không được nhắc đến."}}, {"q": "According to the researcher, why does sleeping until noon on Saturday cause problems?", "opts": ["It makes people eat too much", "It moves the body clock later, so Sunday sleep is hard", "It reduces the total hours of sleep in the week", "It makes naps impossible"], "a": 1, "kind": "detail", "why": "Bà giải thích \"your body clock shifts later\", nên tối Chủ nhật khó ngủ, gọi là social jet lag.", "wrong": {"It makes people eat too much": "Bà không nói gì về việc ăn quá nhiều.", "It reduces the total hours of sleep in the week": "Ngủ muộn không làm giảm tổng giờ ngủ; vấn đề là lệch đồng hồ sinh học.", "It makes naps impossible": "Bà không nói ngủ muộn khiến không thể ngủ trưa."}}, {"q": "Why does Dr Rivera tell students to stop drinking coffee after lunch?", "opts": ["Coffee is bad for the stomach in the afternoon", "Students cannot afford coffee late in the day", "Coffee only works for six hours in total", "A cup at four can still affect sleep at night"], "a": 3, "kind": "inference", "why": "Bà nói cà phê ở lại trong cơ thể khoảng sáu giờ, nên ly lúc bốn giờ chiều \"is still working at ten at night\", tức là có thể làm khó ngủ.", "wrong": {"Coffee is bad for the stomach in the afternoon": "Bà không nói về dạ dày mà nói về giấc ngủ.", "Coffee only works for six hours in total": "Sáu giờ là thời gian cà phê còn trong cơ thể, và nó vẫn tác dụng đến đêm.", "Students cannot afford coffee late in the day": "Giá cả không được nhắc đến."}}, {"q": "What does she say is the single most effective change people can make?", "opts": ["Take a long nap every day", "Sleep late at the weekend", "Keep fixed times for going to bed and waking up", "Read the news before bed"], "a": 2, "kind": "next-step", "why": "Bà trả lời \"Consistency\": đi ngủ và thức dậy vào cùng một giờ mỗi ngày, và việc này không tốn gì.", "wrong": {"Take a long nap every day": "Bà chỉ khuyên ngủ trưa ngắn hai mươi phút, không phải ngủ dài.", "Sleep late at the weekend": "Ngủ nướng cuối tuần gây social jet lag.", "Read the news before bed": "Đọc tin tức trước khi ngủ khiến não tỉnh táo; bà khuyên đọc sách giấy."}}], "notes": {"vocab": [["coping fine", "xoay xở ổn, vẫn đối phó được", "cope with = đối phó với"], ["body clock", "đồng hồ sinh học"], ["social jet lag", "lệch múi giờ xã hội", "do ngủ khác giờ giữa ngày thường và cuối tuần"], ["long lie-in", "giấc ngủ nướng dài", "lie-in là cách nói của người Anh"], ["groggy", "uể oải, choáng váng sau khi ngủ dậy"], ["consistency", "sự đều đặn, nhất quán"]], "grammar": [["Hedging with would have", "I'd originally have said eight", "Cấu trúc would have said cho thấy người nói từng nghĩ thế nhưng đã đổi ý; đây là cách nói nhẹ nhàng khi chỉnh lại thông tin."], ["Zero conditional", "If you sleep until noon, your body clock shifts later", "If + hiện tại, hiện tại: diễn tả kết quả luôn xảy ra, như một quy luật."], ["Anything ... and ...", "Anything longer than that and you risk waking up groggy", "Cấu trúc nói nhanh: câu danh từ + and + mệnh đề, mang nghĩa nếu vượt quá mức đó thì sẽ có rủi ro."]], "tips": ["Trong phỏng vấn, người dẫn chương trình thường nêu câu hỏi ngắn; hãy tập trung vào câu trả lời dài của khách mời và các từ báo hiệu như however, but, instead.", "Chú ý các con số (năm giờ, chín giờ, hai mươi phút) và xem chúng đang nói về ai, vì người nói có thể sửa lại số ngay sau đó."]}}, {"id": "lc-504", "lvl": "B2", "kind": "conversation", "title": "Understanding Consent Before an Endoscopy", "script": [["Dr Okafor", "Good morning, Mr Hale. I'm Dr Okafor. I'd like to go through the endoscopy with you today before you sign anything. Is that all right?"], ["Mr Hale", "Yes, of course. To be honest, I'm a bit nervous. I only know that they put a camera down my throat."], ["Dr Okafor", "That's essentially right. A thin, flexible tube with a small camera goes through your mouth into your stomach, so we can look at what's causing your pain. It usually takes about fifteen minutes."], ["Mr Hale", "Will I be awake?"], ["Dr Okafor", "You'll be given a sedative through a vein in your arm, so you'll feel very relaxed and sleepy. Most people don't remember the procedure afterwards. We'll also numb your throat with a spray."], ["Mr Hale", "What could go wrong?"], ["Dr Okafor", "That's a good question, and you have every right to ask. Serious complications are rare. Some people have a sore throat for a day or two. Very occasionally, the tube can make a small tear in the wall of the food pipe, and that would need treatment in hospital. We'd also watch your breathing carefully because of the sedative."], ["Mr Hale", "And if I decide not to have it?"], ["Dr Okafor", "That's entirely your decision, and it won't affect the rest of your care. The alternative is to treat your symptoms with medication and monitor you, but we wouldn't be able to see the lining of your stomach, so we might miss something."], ["Nurse Evans", "Sorry to interrupt, Doctor. Mr Hale, I should mention that your appointment has moved. It was Thursday, but it's now Friday at half past nine."], ["Mr Hale", "Friday works for me, actually. Do I need to prepare?"], ["Nurse Evans", "Yes. No food after midnight, but you can sip water until six in the morning. And because of the sedation, someone must take you home. You can't drive or go in a taxi alone."], ["Mr Hale", "My daughter can do that."], ["Dr Okafor", "Perfect. Mr Hale, do you feel you understand the risks and the alternatives?"], ["Mr Hale", "I think so. Could you explain the sedation part once more?"], ["Dr Okafor", "Of course. In simple terms, the medicine makes you drowsy, we monitor your oxygen levels throughout, and you wake up shortly afterwards."], ["Mr Hale", "That's clearer, thank you. I'm happy to go ahead."], ["Dr Okafor", "Wonderful. Then the nurse will bring the consent form on Friday morning, and you can sign it after any last questions."]], "qs": [{"q": "What is the main purpose of the conversation?", "opts": ["To tell the patient his test results", "To explain a procedure so the patient can decide whether to agree", "To change the patient's medication", "To book a taxi for the patient"], "a": 1, "kind": "gist", "why": "Bác sĩ nói muốn \"go through the endoscopy\" với bệnh nhân trước khi ký, giải thích cách làm, rủi ro và lựa chọn thay thế để ông tự quyết định.", "wrong": {"To tell the patient his test results": "Chưa có kết quả xét nghiệm nào được nhắc đến.", "To change the patient's medication": "Không có thay đổi thuốc; chỉ nhắc thuốc như một lựa chọn thay thế.", "To book a taxi for the patient": "Đi taxi chỉ là chi tiết phụ của y tá."}}, {"q": "What will Mr Hale feel during the procedure?", "opts": ["Relaxed and sleepy, and he probably won't remember it", "Fully awake and in pain", "Nothing, because he will have general surgery", "Only a sore throat that lasts a week"], "a": 0, "kind": "detail", "why": "Bác sĩ nói ông sẽ được tiêm thuốc an thần, \"very relaxed and sleepy\", và hầu hết mọi người không nhớ gì sau đó.", "wrong": {"Fully awake and in pain": "Ông được dùng thuốc an thần nên không tỉnh táo hoàn toàn.", "Nothing, because he will have general surgery": "Đây là nội soi với thuốc an thần, không phải phẫu thuật gây mê toàn thân.", "Only a sore throat that lasts a week": "Đau họng chỉ kéo dài một hai ngày, và không phải điều ông cảm nhận trong lúc làm."}}, {"q": "When is the appointment now?", "opts": ["Thursday at half past nine", "Friday at nine fifteen", "Friday at half past nine", "Thursday at nine fifteen"], "a": 2, "kind": "number", "why": "Y tá nói lịch hẹn \"was Thursday, but it's now Friday at half past nine\". Thứ Năm là lịch cũ.", "wrong": {"Thursday at half past nine": "Thứ Năm là lịch cũ đã bị dời.", "Friday at nine fifteen": "Giờ đúng là chín giờ rưỡi, không phải chín giờ mười lăm.", "Thursday at nine fifteen": "Cả ngày lẫn giờ đều không đúng; fifteen là thời lượng thủ thuật."}}, {"q": "Which risk does the doctor describe as very occasional?", "opts": ["A reaction to the numbing spray", "Losing his voice permanently", "A broken tooth", "A small tear in the food pipe"], "a": 3, "kind": "detail", "why": "Bác sĩ nói rất hiếm khi ống \"can make a small tear in the wall of the food pipe\" và cần điều trị trong bệnh viện.", "wrong": {"A reaction to the numbing spray": "Bác sĩ không nhắc đến phản ứng với thuốc xịt tê.", "A broken tooth": "Không có đề cập đến gãy răng.", "Losing his voice permanently": "Mất giọng vĩnh viễn không được nhắc đến; chỉ có đau họng một hai ngày."}}, {"q": "What must happen before Mr Hale goes home after the procedure?", "opts": ["He must take a taxi alone", "He must drive carefully", "Someone must go with him and take him home", "He must stay in hospital for two days"], "a": 2, "kind": "next-step", "why": "Y tá nói vì dùng thuốc an thần nên \"someone must take you home\", và con gái ông sẽ làm việc đó.", "wrong": {"He must take a taxi alone": "Y tá nói rõ ông không được đi taxi một mình.", "He must drive carefully": "Ông không được tự lái xe sau khi dùng thuốc an thần.", "He must stay in hospital for two days": "Không có yêu cầu ở lại viện hai ngày; đó chỉ là thời gian đau họng có thể kéo dài."}}, {"q": "Why does Dr Okafor explain the sedation again?", "opts": ["He forgot to mention it earlier", "He wants to be sure the patient truly understands before agreeing", "He is trying to persuade the patient to refuse", "The nurse asked him to repeat it"], "a": 1, "kind": "inference", "why": "Bệnh nhân xin giải thích lại phần an thần, và bác sĩ giải thích đơn giản hơn để chắc rằng ông hiểu rõ trước khi ký đồng ý.", "wrong": {"He forgot to mention it earlier": "Bác sĩ đã giải thích phần này từ trước; lần này là theo yêu cầu của bệnh nhân.", "He is trying to persuade the patient to refuse": "Bác sĩ nói rõ quyết định thuộc về bệnh nhân và không ép ông từ chối.", "The nurse asked him to repeat it": "Chính bệnh nhân yêu cầu, không phải y tá."}}], "notes": {"vocab": [["sedative", "thuốc an thần"], ["complications", "biến chứng"], ["food pipe", "thực quản", "cách nói đời thường của oesophagus"], ["numb your throat", "làm tê cổ họng"], ["alternative", "lựa chọn thay thế"], ["drowsy", "buồn ngủ, lơ mơ"], ["consent form", "phiếu đồng ý thực hiện thủ thuật"]], "grammar": [["Future passive", "You'll be given a sedative through a vein in your arm", "Thể bị động tương lai (will be + quá khứ phân từ) dùng khi người thực hiện không quan trọng bằng việc sẽ xảy ra với bệnh nhân."], ["Modal verb can for possibility", "the tube can make a small tear in the wall of the food pipe", "Can dùng để nói điều có thể xảy ra, ở đây là một rủi ro hiếm gặp."], ["Must for obligation", "someone must take you home", "Must diễn tả yêu cầu bắt buộc, thường dùng cho quy định an toàn."]], "tips": ["Trong cuộc nói chuyện y tế, hãy nghe các từ chỉ mức độ như rare, very occasionally, usually để biết rủi ro lớn hay nhỏ.", "Khi có người xen vào và thay đổi thông tin (ngày, giờ), hãy ghi lại cả giá trị cũ lẫn giá trị mới vì câu hỏi thường dùng giá trị cũ làm đáp án sai."]}}, {"id": "lc-505", "lvl": "B2", "kind": "announcement", "title": "New Visiting Hours at Riverside General", "script": [["Announcer", "Good afternoon, and welcome to Riverside General Hospital. This is an important announcement for all patients, families, and visitors about changes to our visiting-hours policy."], ["Announcer", "Over the past year, we've seen a sharp rise in winter infections on our wards, and many patients have told us they struggle to rest when rooms are crowded. For these reasons, the hospital board has decided to introduce new hours."], ["Announcer", "From Monday the third of November, general wards will be open to visitors from two o'clock in the afternoon until eight o'clock in the evening. Please note that an earlier notice gave the date as the second of November. That was a printing error, and the correct date is the third."], ["Announcer", "Until now, visitors could come at any time between nine in the morning and nine at night."], ["Announcer", "Each patient may have no more than two visitors at a time. Children under twelve may visit only when accompanied by an adult, and they must stay no longer than thirty minutes."], ["Announcer", "The intensive care unit follows a different schedule. Visits there are limited to two periods, from eleven until twelve noon, and from five until six in the evening, and only close family members will be admitted."], ["Announcer", "There are some exceptions. Parents of children admitted to the paediatric ward may stay with them around the clock. Partners of women in labour are also welcome at any hour, and so are relatives of patients who are very seriously ill."], ["Announcer", "If you have a cough, a fever, or a runny nose, we kindly ask you not to visit. A phone or video call is a good alternative, and our nurses can help patients set one up."], ["Announcer", "When you arrive, please stop at the front desk, where you'll be asked to sign in and collect a visitor badge. The badge should be worn visibly throughout your stay and returned when you leave."], ["Announcer", "Visitors are also asked to clean their hands with the gel at the entrance of each ward. This simple step protects patients who are recovering from surgery or taking medicines that weaken their immunity."], ["Announcer", "If you can't come during the new hours because of work, you may apply for a special pass. Forms are available at the front desk, and applications will be reviewed within two working days."], ["Announcer", "For questions about the new policy, call the patient services office on extension four five two one. Our staff will be happy to explain the details and discuss your individual situation."], ["Announcer", "Once again, the new hours begin on Monday the third of November. Thank you for helping us keep our patients safe, and we wish everyone a speedy recovery."]], "qs": [{"q": "What is the announcement mainly about?", "opts": ["A new emergency department", "A change to when and how people can visit patients", "A shortage of beds on the wards", "A new parking system"], "a": 1, "kind": "gist", "why": "Thông báo mở đầu nói về \"changes to our visiting-hours policy\" và sau đó giải thích giờ mới, ngoại lệ và quy định.", "wrong": {"A new emergency department": "Không có khoa cấp cứu mới nào được nhắc đến.", "A shortage of beds on the wards": "Bệnh viện không nói thiếu giường; lý do là nhiễm trùng và nhu cầu nghỉ ngơi.", "A new parking system": "Không đề cập đến bãi đỗ xe."}}, {"q": "When do the new visiting hours begin?", "opts": ["Monday the second of November", "Monday the third of November", "Thursday the third of November", "Monday the thirteenth of November"], "a": 1, "kind": "number", "why": "Người đọc sửa lại: thông báo cũ ghi ngày hai là \"a printing error\", ngày đúng là mùng ba tháng Mười Một.", "wrong": {"Monday the second of November": "Ngày hai là ngày in nhầm trong thông báo cũ.", "Thursday the third of November": "Ngày đúng là thứ Hai, không phải thứ Năm.", "Monday the thirteenth of November": "Con số là third, không phải thirteenth."}}, {"q": "How are visits to the intensive care unit organised?", "opts": ["Anyone may visit from two until eight", "Only close family, in two short periods a day", "Visitors may stay around the clock", "Children may visit for thirty minutes"], "a": 1, "kind": "detail", "why": "Thông báo nói khoa hồi sức chỉ cho thăm trong hai khung giờ và \"only close family members will be admitted\".", "wrong": {"Anyone may visit from two until eight": "Hai đến tám giờ là giờ của các khoa thường.", "Visitors may stay around the clock": "Chỉ cha mẹ bệnh nhi và một số trường hợp đặc biệt được ở cả ngày.", "Children may visit for thirty minutes": "Ba mươi phút là giới hạn cho trẻ em ở khoa thường."}}, {"q": "Who may visit at any hour?", "opts": ["Partners of women in labour", "Anyone with a visitor badge", "Visitors who clean their hands", "People who work during the day"], "a": 0, "kind": "detail", "why": "Người đọc nói \"Partners of women in labour are also welcome at any hour\", cùng với cha mẹ bệnh nhi và người thân bệnh nhân rất nặng.", "wrong": {"Anyone with a visitor badge": "Huy hiệu khách chỉ để đăng ký; không cho phép ra vào mọi lúc.", "Visitors who clean their hands": "Rửa tay là quy định cho mọi khách.", "People who work during the day": "Người đi làm phải xin giấy phép đặc biệt, không tự do ra vào."}}, {"q": "Why does the hospital ask people with a cough or fever not to visit?", "opts": ["Because phones are cheaper than visits", "Because the hospital wants to protect vulnerable patients from infection", "Because the hospital has too few nurses", "Because sick visitors cannot find parking"], "a": 1, "kind": "inference", "why": "Bệnh viện nói nhiễm trùng mùa đông tăng và gel rửa tay bảo vệ bệnh nhân \"taking medicines that weaken their immunity\", nên khách bị bệnh được khuyên không đến.", "wrong": {"Because phones are cheaper than visits": "Chi phí điện thoại không được đề cập.", "Because the hospital has too few nurses": "Bệnh viện không nói thiếu y tá.", "Because sick visitors cannot find parking": "Không liên quan đến chỗ đỗ xe."}}, {"q": "What should a visitor do if they cannot come during the new hours because of work?", "opts": ["Visit the intensive care unit instead", "Call the front desk every day", "Apply for a special pass", "Wait until the policy ends"], "a": 2, "kind": "next-step", "why": "Thông báo nói người không đến được có thể \"apply for a special pass\" bằng mẫu đơn ở quầy lễ tân, xét trong hai ngày làm việc.", "wrong": {"Visit the intensive care unit instead": "Hồi sức tích cực chỉ dành cho người thân gần gũi.", "Call the front desk every day": "Không có yêu cầu gọi hằng ngày; họ làm đơn xin giấy phép.", "Wait until the policy ends": "Không nói chính sách sẽ kết thúc."}}], "notes": {"vocab": [["intensive care unit", "khoa hồi sức tích cực"], ["accompanied by", "đi cùng với"], ["around the clock", "suốt ngày đêm"], ["in labour", "đang chuyển dạ"], ["immunity", "khả năng miễn dịch"], ["special pass", "giấy phép đặc biệt"], ["speedy recovery", "mau bình phục"]], "grammar": [["Modal may for permission and limits", "Each patient may have no more than two visitors at a time", "May dùng trong văn bản chính thức để nói điều được phép hoặc giới hạn cho phép."], ["Passive voice", "Visits there are limited to two periods", "Bị động dùng để nói về quy định mà không cần nêu ai đặt ra."], ["Future passive in instructions", "where you'll be asked to sign in and collect a visitor badge", "Will be asked là bị động tương lai, cách nói lịch sự để báo trước các bước phải làm."]], "tips": ["Với thông báo, hãy nghe trước câu mở đầu để biết chủ đề, rồi chú ý các từ báo hiệu thay đổi như please note, correct, exceptions.", "Thông báo thường sửa lỗi ngày giờ; khi nghe thấy chữ error hay correct, hãy bỏ giá trị cũ và ghi giá trị mới."]}}, {"id": "lc-506", "lvl": "B2", "kind": "talk", "title": "Why Cities Need Better Cycling Design", "script": [["Professor Hart", "Good morning, everyone. Today I'd like to talk about a question that city planners have wrestled with for decades: how do we persuade people to cycle, and why does it matter?"], ["Professor Hart", "Let me start with some history. In the nineteen seventies, many Dutch cities were heading in the same direction as everyone else, building wider roads for cars. Then a series of protests about road deaths changed public opinion, and the government began to invest in cycling."], ["Professor Hart", "Today, about a quarter of all trips in the Netherlands are made by bike. Now, you might assume that the Dutch simply love cycling more than other people do. I'd argue the opposite. Their success comes mainly from design, not from culture."], ["Professor Hart", "The key idea is separation. When bikes share the road with fast traffic, most people, particularly parents and older adults, feel unsafe, and they stay at home or take the car. Protected lanes, with a physical barrier, change that feeling."], ["Professor Hart", "Planners often talk about the eight to eighty rule: a city is working well if an eight-year-old and an eighty-year-old can both cycle safely."], ["Professor Hart", "The second factor is directness. Cyclists will not take a long detour. If the bike route is slower than driving, only the most determined riders will use it, so networks must connect homes, schools, and workplaces by the shortest path."], ["Professor Hart", "Third, there's parking. It sounds trivial, but secure parking at stations makes a huge difference. People won't leave a bike outside all day if they think it will be stolen."], ["Professor Hart", "Of course, critics raise objections. Shopkeepers often fear that removing car spaces will hurt business. Yet studies in several cities have found that cyclists and pedestrians visit shops more frequently, even if they spend less on each visit."], ["Professor Hart", "Another concern is cost. Admittedly, building protected lanes isn't cheap. However, compared with motorways, it's remarkably affordable, and it saves money on healthcare because people become more active."], ["Professor Hart", "What about hills and bad weather? Electric bikes have partly solved the first problem, and the second matters less than you'd think. Copenhagen residents cycle all winter, provided that the lanes are cleared of snow first."], ["Professor Hart", "So what should a city do first? In my view, rather than building scattered lanes everywhere, start with one connected route between two busy destinations, and make it excellent."], ["Professor Hart", "That approach has a practical advantage. Residents can see the benefits quickly, and political support grows. Once people have experienced one good route, they begin to ask for more."], ["Professor Hart", "To sum up, cycling is not mainly about culture or fitness. It's about whether the street makes people feel safe, and that's a choice that planners and politicians can make. Thank you."]], "qs": [{"q": "What is the speaker's main argument?", "opts": ["Cycling grows when streets are designed to feel safe", "The Dutch are naturally better at sport", "Cars should be banned from all cities", "Electric bikes are the only solution"], "a": 0, "kind": "gist", "why": "Cuối bài ông tóm tắt: đi xe đạp không chủ yếu do văn hóa mà do con đường có khiến người ta \"feel safe\" hay không.", "wrong": {"The Dutch are naturally better at sport": "Ông phản bác ý rằng người Hà Lan yêu xe đạp hơn người khác.", "Cars should be banned from all cities": "Ông không đề nghị cấm hoàn toàn xe hơi.", "Electric bikes are the only solution": "Xe đạp điện chỉ giải quyết một phần vấn đề đồi dốc."}}, {"q": "What changed Dutch policy in the nineteen seventies?", "opts": ["A rise in fuel prices", "Protests about road deaths", "A new sports campaign", "Complaints from shopkeepers"], "a": 1, "kind": "detail", "why": "Ông nói \"a series of protests about road deaths changed public opinion\", sau đó chính phủ đầu tư cho xe đạp.", "wrong": {"A rise in fuel prices": "Giá nhiên liệu không được nhắc đến.", "A new sports campaign": "Không có chiến dịch thể thao nào được đề cập.", "Complaints from shopkeepers": "Chủ cửa hàng chỉ được nhắc đến như người phản đối, ở phần sau."}}, {"q": "According to the eight to eighty rule, who should be able to cycle safely?", "opts": ["Children of eight and adults of eighteen", "People aged eight and people aged eighty", "Cyclists who ride eighty kilometres", "Anyone between eighteen and eighty"], "a": 1, "kind": "number", "why": "Ông nói một thành phố tốt khi \"an eight-year-old and an eighty-year-old can both cycle safely\".", "wrong": {"Children of eight and adults of eighteen": "Mười tám không phải con số trong quy tắc.", "Cyclists who ride eighty kilometres": "Tám mươi là tuổi, không phải số ki-lô-mét.", "Anyone between eighteen and eighty": "Quy tắc nói về hai đầu độ tuổi, tám và tám mươi, không phải mười tám."}}, {"q": "What does the speaker imply about shopkeepers' fears?", "opts": ["They are probably exaggerated", "They are completely correct", "They only apply in cold countries", "They have not been studied"], "a": 0, "kind": "inference", "why": "Ông nói các nghiên cứu thấy người đi xe đạp và đi bộ ghé cửa hàng \"more frequently\", ngụ ý nỗi lo về kinh doanh bị phóng đại.", "wrong": {"They are completely correct": "Ông đưa nghiên cứu phản bác nên không phải hoàn toàn đúng.", "They only apply in cold countries": "Ông không nói nỗi lo chỉ ở nước lạnh.", "They have not been studied": "Ông nói rõ đã có nhiều nghiên cứu ở nhiều thành phố."}}, {"q": "Why does secure parking matter?", "opts": ["People worry that their bikes will be stolen", "It makes the lanes wider", "It reduces car traffic by half", "It is cheaper than building lanes"], "a": 0, "kind": "detail", "why": "Ông nói mọi người sẽ không để xe cả ngày bên ngoài nếu nghĩ nó \"will be stolen\".", "wrong": {"It makes the lanes wider": "Bãi đỗ không liên quan đến độ rộng làn đường.", "It reduces car traffic by half": "Không có con số giảm một nửa giao thông xe hơi.", "It is cheaper than building lanes": "Ông không so sánh chi phí đỗ xe với làm làn đường."}}, {"q": "What does the speaker recommend a city should do first?", "opts": ["Build many separate lanes in every district", "Buy electric bikes for all residents", "Create one excellent connected route between busy places", "Wait until the winter is over"], "a": 2, "kind": "next-step", "why": "Ông khuyên \"start with one connected route between two busy destinations, and make it excellent\" thay vì làm nhiều làn rời rạc.", "wrong": {"Build many separate lanes in every district": "Ông phản đối việc xây nhiều làn rời rạc khắp nơi.", "Buy electric bikes for all residents": "Ông không đề nghị mua xe đạp điện cho dân.", "Wait until the winter is over": "Thời tiết không phải lý do để chờ; dân Copenhagen đạp cả mùa đông."}}], "notes": {"vocab": [["wrestled with", "vật lộn với, trăn trở với (một vấn đề)"], ["protected lanes", "làn đường có rào chắn riêng cho xe đạp"], ["detour", "đường vòng"], ["objections", "sự phản đối"], ["scattered lanes", "các làn đường rời rạc"], ["provided that", "với điều kiện là"]], "grammar": [["Hedging an opinion", "I'd argue the opposite", "I'd argue là cách nói giảm khi đưa ra quan điểm mạnh, thường gặp trong bài nói học thuật."], ["First conditional", "If the bike route is slower than driving, only the most determined riders will use it", "If + hiện tại, will + động từ: nói về kết quả có thể xảy ra trong tương lai."], ["Once + present perfect", "Once people have experienced one good route, they begin to ask for more", "Once + hiện tại hoàn thành chỉ việc đã xảy ra xong, kéo theo kết quả tiếp theo."]], "tips": ["Trong bài nói, hãy nghe các từ đánh số như first, second, third, another vì chúng báo các ý chính.", "Khi thấy Yet, However, Admittedly, ý của người nói sắp đối lập; câu hỏi suy luận thường dựa vào đó."]}}, {"id": "lc-507", "lvl": "B2", "kind": "conversation", "title": "Three Colleagues Debate Remote Work", "script": [["Priya", "So, Tom, did you read the email? The company's thinking of asking everyone back to the office four days a week."], ["Tom", "I did, and honestly I'm not surprised. Management keeps saying collaboration suffers when we're not in the same room."], ["Priya", "But is that actually true? I've been fully remote for two years, and my team ships features faster than ever. Nobody interrupts me every ten minutes."], ["Tom", "I see your point, but you're a senior developer. Think about the new graduates who joined last spring. They've barely met anyone, and they don't have anyone to ask quick questions."], ["Priya", "That's fair. Mentoring is probably the strongest argument for the office. Although, we could set up a buddy system with video calls."], ["Tom", "Video calls are exhausting, though. After four in a row, I can't think. Whereas if we're at the next desk, a thirty-second chat solves the problem."], ["Chen", "Sorry, I'm joining late. Are you talking about the return-to-office plan? I think we're ignoring the commute. I spend ninety minutes a day on the train. That's nearly eight hours a week I'll never get back."], ["Priya", "Exactly. And people with young children, or someone caring for a parent, need flexibility. If the company insists on four days, we'll lose good people."], ["Tom", "Possibly, but flexibility can also mean isolation. Some of my friends who work from home say they haven't had a proper conversation with a colleague for weeks."], ["Chen", "So maybe the answer is a middle ground. Two days in the office, when the whole team's there, and the rest from home."], ["Tom", "Hmm, two feels a bit low to me. What about three? Then the new graduates would get enough contact."], ["Priya", "Three is a reasonable compromise, provided we choose the days together instead of having them imposed. I'd rather everyone came in on the same days, so the trip is worth it."], ["Chen", "Agreed. Shall we write that up as a proposal and send it to our manager by Friday?"], ["Tom", "Yes, let's do that. I'll draft it tonight and share it with you both tomorrow morning."]], "qs": [{"q": "What are the speakers mainly doing?", "opts": ["Planning a team party", "Discussing a return-to-office plan and looking for a compromise", "Interviewing a new graduate", "Complaining about their manager's salary"], "a": 1, "kind": "gist", "why": "Họ bàn về kế hoạch quay lại văn phòng bốn ngày một tuần và cuối cùng tìm một giải pháp trung gian, \"a middle ground\".", "wrong": {"Planning a team party": "Không có tiệc nào được nhắc đến.", "Interviewing a new graduate": "Không có phỏng vấn sinh viên mới ra trường; họ chỉ được nhắc đến như ví dụ.", "Complaining about their manager's salary": "Không nói về lương của quản lý."}}, {"q": "How many office days a week do they finally agree to propose?", "opts": ["Two", "Three", "Four", "Five"], "a": 1, "kind": "number", "why": "Chen đề xuất hai ngày, Tom thấy hơi ít và đề nghị ba, Priya đồng ý \"Three is a reasonable compromise\". Bốn là đề xuất của công ty.", "wrong": {"Two": "Hai ngày là đề xuất đầu tiên của Chen, nhưng Tom không đồng ý.", "Four": "Tom và những người khác đã đồng ý ba ngày.", "Five": "Bốn ngày là kế hoạch của công ty, họ muốn giảm xuống."}}, {"q": "Why does Chen dislike the plan?", "opts": ["The office is too noisy", "He prefers working at night", "Travelling takes about ninety minutes a day", "He wants a bigger desk"], "a": 2, "kind": "detail", "why": "Chen nói anh dành \"ninety minutes a day on the train\", gần tám tiếng mỗi tuần.", "wrong": {"The office is too noisy": "Anh không nói văn phòng ồn.", "He prefers working at night": "Anh không nói thích làm việc ban đêm.", "He wants a bigger desk": "Không có chi tiết về bàn làm việc."}}, {"q": "What is Tom's main worry about working from home?", "opts": ["New graduates lack contact and quick help", "Developers work too slowly", "Video calls cost too much", "Managers cannot see the team"], "a": 0, "kind": "detail", "why": "Tom nói các bạn mới tốt nghiệp \"have barely met anyone\" và không có ai để hỏi nhanh.", "wrong": {"Developers work too slowly": "Chính Priya nói nhóm làm nhanh hơn khi ở nhà.", "Video calls cost too much": "Chi phí gọi video không được nhắc đến.", "Managers cannot see the team": "Quản lý không được nói đến ở ý này."}}, {"q": "Why does Priya want everyone to come in on the same days?", "opts": ["So the commute is worthwhile because colleagues are there", "So the office is less crowded", "So the manager can check attendance", "So nobody has to use video calls"], "a": 0, "kind": "inference", "why": "Priya nói muốn mọi người đến cùng ngày \"so the trip is worth it\", tức là chuyến đi có ý nghĩa vì gặp được đồng nghiệp.", "wrong": {"So the office is less crowded": "Cô không nói về việc giảm đông đúc.", "So the manager can check attendance": "Không có ý kiểm tra điểm danh.", "So nobody has to use video calls": "Họ vẫn có thể dùng gọi video trong các ngày ở nhà."}}, {"q": "What will Tom do next?", "opts": ["Send the proposal to the manager tonight", "Call the manager on Friday", "Ask the new graduates for their opinion", "Write a first version tonight and share it tomorrow morning"], "a": 3, "kind": "next-step", "why": "Tom nói \"I'll draft it tonight and share it with you both tomorrow morning\".", "wrong": {"Send the proposal to the manager tonight": "Anh chỉ soạn bản nháp tối nay, chưa gửi cho quản lý.", "Ask the new graduates for their opinion": "Không có kế hoạch hỏi sinh viên mới.", "Call the manager on Friday": "Hạn gửi cho quản lý là thứ Sáu, không phải lúc Tom gọi."}}], "notes": {"vocab": [["return-to-office plan", "kế hoạch yêu cầu quay lại làm việc tại văn phòng"], ["mentoring", "việc hướng dẫn, kèm cặp"], ["buddy system", "hệ thống bạn đồng hành"], ["commute", "quãng đường đi làm hằng ngày"], ["middle ground", "giải pháp trung gian"], ["compromise", "sự thỏa hiệp"], ["imposed", "bị áp đặt"]], "grammar": [["Would rather + past", "I'd rather everyone came in on the same days", "Would rather + chủ ngữ + quá khứ đơn nói mong muốn về hiện tại hoặc tương lai; dạng quá khứ ở đây không chỉ quá khứ."], ["Provided + clause", "provided we choose the days together instead of having them imposed", "Provided (that) nghĩa là với điều kiện; having them imposed là bị động dùng sau instead of."], ["First conditional", "If the company insists on four days, we'll lose good people", "If + hiện tại, will + động từ: dự đoán kết quả có thể xảy ra."]], "tips": ["Trong cuộc tranh luận, hãy nghe cụm nhường bước như I see your point, That's fair vì sau đó thường là ý đối lập hoặc thỏa hiệp.", "Số liệu thay đổi trong lúc nói chuyện (hai, ba, bốn ngày); hãy theo dõi ai đề xuất con số nào và con số cuối cùng được chọn."]}}, {"id": "lc-508", "lvl": "B2", "kind": "voicemail", "title": "A Voicemail About a Cancelled Flight to Lisbon", "script": [["Daniel", "Hello Sophie, it's Daniel Reyes calling about my trip to Lisbon. I'm leaving this message at about ten past nine on Monday morning, and I'm afraid there's a problem."], ["Daniel", "The airline emailed me last night to say my flight on Tuesday, the one at quarter past seven, has been cancelled because of a strike. They've offered me two alternatives, and neither is ideal."], ["Daniel", "The first is a flight on Thursday morning, but that's useless because the conference opens on Wednesday at two in the afternoon. Actually, I'm presenting at four, so I can't miss it."], ["Daniel", "The second option is leaving on Wednesday at twenty to seven, with a change in Madrid. It lands in Lisbon at five past eleven, which should leave me enough time, as long as nothing's delayed."], ["Daniel", "My worry is the connection. I'd only have fifty minutes in Madrid, and I'd have to change terminals. Last time that happened, I nearly missed the plane. Could you check whether a longer layover is available?"], ["Daniel", "Alternatively, I wondered about a direct flight with a different airline. I know it'd probably cost more, but my company will cover it as long as I can show the cancellation email, so please don't let the price put you off."], ["Daniel", "That brings me to the hotel. Since I'll now arrive a day later, I need to shorten the booking. If I remember rightly, it was three nights from Tuesday, so it should become two nights from Wednesday. Please confirm that nobody charges me for the first night."], ["Daniel", "There's also the airport transfer. I'd reserved a taxi for Tuesday afternoon, and that needs to be cancelled or moved to Wednesday. I'd prefer a late-morning pick-up rather than a fixed time, in case the flight's late."], ["Daniel", "Oh, and one more thing. I said earlier that my return flight is on Friday evening. Actually, I got that wrong. It's Friday morning, at ten to nine, so please check that nothing needs changing there."], ["Daniel", "I know that's a lot to sort out, and I really appreciate your help. If you could look into the direct flight first, that's my top priority."], ["Daniel", "Please call me back before five this afternoon, because I'm in meetings after that and won't be able to answer. You already have my mobile number, so I won't repeat it."], ["Daniel", "If I don't hear from you today, I'll ring the airline myself first thing tomorrow, but I'd much rather you handled it. Thanks again, Sophie. Speak soon."]], "qs": [{"q": "Why is Daniel calling Sophie?", "opts": ["To thank her for a great holiday", "To ask her to sort out new travel plans after a cancelled flight", "To tell her he cannot attend the conference", "To complain about the hotel"], "a": 1, "kind": "gist", "why": "Daniel nói chuyến bay thứ Ba \"has been cancelled because of a strike\" và nhờ cô tìm chuyến mới, sửa khách sạn, xe đưa đón.", "wrong": {"To thank her for a great holiday": "Đây là chuyến công tác, không phải kỳ nghỉ.", "To tell her he cannot attend the conference": "Ông vẫn muốn dự hội nghị và còn phải thuyết trình.", "To complain about the hotel": "Ông không phàn nàn về khách sạn; chỉ muốn rút ngắn đặt phòng."}}, {"q": "What time does the second option leave on Wednesday?", "opts": ["Twenty to seven", "Quarter past seven", "Ten past nine", "Twenty to eight"], "a": 0, "kind": "number", "why": "Daniel nói \"leaving on Wednesday at twenty to seven\", tức sáu giờ bốn mươi. Bảy giờ mười lăm là chuyến thứ Ba bị hủy.", "wrong": {"Quarter past seven": "Bảy giờ mười lăm là giờ của chuyến thứ Ba đã bị hủy.", "Ten past nine": "Chín giờ mười là giờ ông để lại tin nhắn.", "Twenty to eight": "Không có giờ bay bảy giờ bốn mươi."}}, {"q": "What worries Daniel about the flight through Madrid?", "opts": ["The airline is unreliable", "The seats are uncomfortable", "The connection is short and involves changing terminals", "The flight lands too early"], "a": 2, "kind": "detail", "why": "Ông nói chỉ có \"fifty minutes in Madrid\" và phải đổi nhà ga, lần trước suýt lỡ chuyến.", "wrong": {"The airline is unreliable": "Ông không đánh giá hãng bay không đáng tin.", "The seats are uncomfortable": "Ông không nói gì về ghế ngồi.", "The flight lands too early": "Ông lo thời gian nối chuyến, không phải đến quá sớm."}}, {"q": "How many nights does Daniel want to stay at the hotel now?", "opts": ["One", "Two", "Three", "Four"], "a": 1, "kind": "number", "why": "Ban đầu là ba đêm từ thứ Ba, và ông muốn đổi thành \"two nights from Wednesday\".", "wrong": {"One": "Ông không muốn chỉ một đêm.", "Three": "Ba đêm là đặt phòng ban đầu.", "Four": "Không có bốn đêm."}}, {"q": "What can you infer about Daniel's attitude to the price of a direct flight?", "opts": ["He cannot afford it", "He thinks it is too expensive to consider", "He wants the cheapest option only", "He is not very concerned because his company will pay"], "a": 3, "kind": "inference", "why": "Ông nói công ty sẽ chi trả nếu ông đưa email hủy chuyến, và \"don't let the price put you off\".", "wrong": {"He cannot afford it": "Ông không nói mình không đủ tiền.", "He wants the cheapest option only": "Ông ưu tiên chuyến bay thẳng, không chỉ chọn rẻ nhất.", "He thinks it is too expensive to consider": "Ông bảo cô đừng để giá cả làm nản."}}, {"q": "What does Daniel ask Sophie to do?", "opts": ["Email him tomorrow morning", "Wait for the airline to contact her", "Call him back before five this afternoon", "Meet him at the airport"], "a": 2, "kind": "next-step", "why": "Ông nói \"Please call me back before five this afternoon\" vì sau đó ông họp và không nghe máy được.", "wrong": {"Email him tomorrow morning": "Ông muốn nghe tin trong hôm nay, không phải sáng mai.", "Wait for the airline to contact her": "Ông muốn cô chủ động xử lý, không chờ hãng bay.", "Meet him at the airport": "Không có kế hoạch gặp ở sân bay."}}], "notes": {"vocab": [["strike", "cuộc đình công"], ["layover", "thời gian chờ nối chuyến"], ["put you off", "làm nản, làm mất hứng"], ["top priority", "ưu tiên hàng đầu"], ["first thing tomorrow", "việc đầu tiên vào sáng mai"], ["cancelled", "bị hủy"], ["transfer", "việc đưa đón"]], "grammar": [["Present perfect passive", "has been cancelled because of a strike", "Has been + quá khứ phân từ: chuyến bay đã bị hủy và kết quả còn liên quan đến hiện tại."], ["As long as for condition", "as long as nothing's delayed", "As long as nghĩa là miễn là, nêu điều kiện."], ["Would rather + past", "I'd much rather you handled it", "Would rather + chủ ngữ + quá khứ đơn nói mong muốn người khác làm gì."]], "tips": ["Với tin nhắn thoại, hãy nghe trước lý do gọi, rồi ghi lại giờ giấc; người nói hay đưa ra lựa chọn rồi sửa lại.", "Chú ý các từ sửa như Actually, I got that wrong vì giá trị sau đó mới là đáp án đúng."]}}, {"id": "lc-601", "lvl": "C1", "kind": "talk", "title": "Why Bacteria Outsmart Our Medicines", "script": [["Dr Hart", "Good morning, everyone. Today I want to talk about what the World Health Organization calls one of the biggest threats to global health: antibiotic resistance."], ["Dr Hart", "Let me begin with a common misunderstanding. People often say that patients become resistant to antibiotics. That's not quite right. It's the bacteria that become resistant, not the person taking the drug."], ["Dr Hart", "So how does it happen? Whenever we give an antibiotic, most of the bacteria die, but a few carry random mutations that let them survive. Those survivors multiply, and within days the infection is dominated by the resistant strain."], ["Dr Hart", "Now, this is a natural process, but we've dramatically accelerated it. There are three main drivers."], ["Dr Hart", "The first is overprescribing. Studies suggest that roughly thirty percent of antibiotic prescriptions in outpatient clinics are unnecessary, for example for colds and flu, which are caused by viruses."], ["Dr Hart", "The second driver is poor adherence. When patients stop taking their tablets as soon as they feel better, the weakest bacteria are killed, but the tougher ones are left behind to recover."], ["Dr Hart", "The third, and the one people tend to overlook, is agriculture. In some countries, farm animals consume more antibiotics than humans do, often simply to make them grow faster."], ["Dr Hart", "The consequences are already visible. Take MRSA, which was once confined largely to hospitals but is now found in the community too. And tuberculosis that resists the two most powerful drugs requires treatment lasting up to two years."], ["Dr Hart", "One recent estimate attributes around one point two seven million deaths a year directly to resistant infections. If nothing changes, some forecasts put the annual toll at ten million by twenty fifty. I should stress, though, that those projections are contested, and the real figure could be lower or higher."], ["Dr Hart", "So what can be done? Broadly speaking, there are two strategies: preserving the drugs we have and developing new ones."], ["Dr Hart", "On the first front, hospitals run stewardship programmes, in which a pharmacist and an infectious disease doctor review every prescription after forty eight hours and ask whether the drug is still needed, or could be switched to something narrower."], ["Dr Hart", "On the second, the picture is rather less encouraging. Developing a new antibiotic costs well over a billion dollars, yet it earns little, because doctors, quite rightly, keep new drugs in reserve. That's why many pharmaceutical companies have left the field."], ["Dr Hart", "Some countries are experimenting with a subscription model, paying companies a fixed annual fee for access to a new antibiotic regardless of how much is used. It's too early to say whether this will work."], ["Dr Hart", "As future clinicians, your role is more important than you might think. Before you prescribe, ask yourself three questions: is this infection bacterial, which drug is the narrowest effective choice, and for how long is it genuinely needed?"], ["Dr Hart", "And when you counsel patients, don't just tell them to finish the course. Explain why. People follow advice far more reliably when they understand the reasoning behind it."], ["Dr Hart", "Antibiotics are a shared resource, rather like a common pasture. Overuse by one person damages the whole community, and that's the message I'd like you to take away today. Thank you."]], "qs": [{"q": "What is the main message of the lecture?", "opts": ["Antibiotic resistance is a rare problem that only affects people in hospitals.", "Resistance develops in bacteria because antibiotics are misused, so we must use them carefully and develop new ones.", "Patients who take antibiotics too often become resistant themselves.", "Governments should ban all antibiotics used on farms immediately."], "a": 1, "kind": "gist", "why": "Bài giảng nói vi khuẩn mới là thứ kháng thuốc, ba nguyên nhân chính là kê đơn quá mức, tuân thủ kém và nông nghiệp, và giải pháp là 'preserving the drugs we have and developing new ones'.", "wrong": {"Antibiotic resistance is a rare problem that only affects people in hospitals.": "Người nói nhấn mạnh vấn đề đã lan ra cộng đồng, không chỉ ở bệnh viện.", "Patients who take antibiotics too often become resistant themselves.": "Người nói sửa đúng quan niệm này: 'It's the bacteria that become resistant'.", "Governments should ban all antibiotics used on farms immediately.": "Người nói không đề nghị cấm hoàn toàn, chỉ nêu nông nghiệp là một nguyên nhân."}}, {"q": "Which common misunderstanding does the speaker correct?", "opts": ["That colds and flu are caused by viruses", "That new antibiotics are cheap to develop", "That MRSA is found only in hospitals", "That the patient, rather than the bacteria, becomes resistant"], "a": 3, "kind": "detail", "why": "Người nói nói: 'It's the bacteria that become resistant, not the person taking the drug.'", "wrong": {"That colds and flu are caused by viruses": "Đây là điều người nói khẳng định là đúng, không phải quan niệm sai.", "That new antibiotics are cheap to develop": "Người nói nói phát triển thuốc mới tốn hơn một tỷ đô la.", "That MRSA is found only in hospitals": "MRSA được nhắc là từng chủ yếu ở bệnh viện nhưng nay đã có ở cộng đồng, không phải quan niệm bị sửa."}}, {"q": "According to the speaker, what proportion of outpatient antibiotic prescriptions are unnecessary?", "opts": ["Roughly thirty percent", "Roughly ten percent", "Roughly half", "Roughly three percent"], "a": 0, "kind": "number", "why": "Người nói nói: 'roughly thirty percent of antibiotic prescriptions in outpatient clinics are unnecessary'.", "wrong": {"Roughly ten percent": "Con số được nêu là ba mươi phần trăm, không phải mười.", "Roughly half": "Không có chỗ nào nói một nửa; con số là khoảng ba mươi phần trăm.", "Roughly three percent": "Ba phần trăm quá thấp so với con số được nêu."}}, {"q": "Why have many pharmaceutical companies left the antibiotic field?", "opts": ["Antibiotic resistance has disappeared in most countries.", "Governments forbid companies from selling new antibiotics.", "New antibiotics earn little because they are kept in reserve.", "Farmers now buy all the new antibiotics produced."], "a": 2, "kind": "detail", "why": "Người nói giải thích: 'it earns little, because doctors... keep new drugs in reserve. That's why many pharmaceutical companies have left the field.'", "wrong": {"Antibiotic resistance has disappeared in most countries.": "Người nói nói kháng thuốc là mối đe dọa lớn, không hề biến mất.", "Governments forbid companies from selling new antibiotics.": "Không có thông tin nào về việc chính phủ cấm bán thuốc mới.", "Farmers now buy all the new antibiotics produced.": "Người nói không nói nông dân mua hết thuốc mới."}}, {"q": "What does the speaker imply about the forecast of ten million deaths by twenty fifty?", "opts": ["It is an exact figure confirmed by recent studies.", "It is certainly too high, because stewardship works well.", "It only applies to tuberculosis infections.", "It is uncertain and might turn out to be wrong."], "a": 3, "kind": "inference", "why": "Người nói nói: 'those projections are contested, and the real figure could be lower or higher', tức là dự báo không chắc chắn.", "wrong": {"It is an exact figure confirmed by recent studies.": "Người nói gọi các dự báo là 'contested', nên không phải con số chính xác.", "It is certainly too high, because stewardship works well.": "Người nói nói số thực có thể thấp hơn hoặc cao hơn, không khẳng định chắc chắn là quá cao.", "It only applies to tuberculosis infections.": "Dự báo nói về các nhiễm khuẩn kháng thuốc nói chung, không riêng lao."}}, {"q": "What does the speaker advise students to do when counselling patients?", "opts": ["Avoid mentioning side effects to prevent anxiety", "Explain the reasons for finishing a course of antibiotics", "Prescribe broader antibiotics to be safe", "Tell patients to stop treatment when they feel better"], "a": 1, "kind": "next-step", "why": "Người nói khuyên: 'don't just tell them to finish the course. Explain why.'", "wrong": {"Avoid mentioning side effects to prevent anxiety": "Người nói không đề cập việc giấu tác dụng phụ.", "Prescribe broader antibiotics to be safe": "Người nói muốn chọn kháng sinh hẹp nhất có hiệu quả, không phải rộng hơn.", "Tell patients to stop treatment when they feel better": "Dừng thuốc khi thấy khỏe là nguyên nhân gây kém tuân thủ mà người nói phê phán."}}], "notes": {"vocab": [["overprescribing", "kê đơn quá mức"], ["adherence", "sự tuân thủ điều trị"], ["mutations", "các đột biến"], ["stewardship programmes", "chương trình quản lý sử dụng kháng sinh hợp lý"], ["in reserve", "để dự trữ, chưa dùng ngay"], ["contested", "còn bị tranh cãi", "Dùng cho số liệu hoặc dự báo chưa chắc chắn."]], "grammar": [["Cleft sentence (câu nhấn mạnh)", "It's the bacteria that become resistant", "Cấu trúc 'It's ... that ...' dùng để nhấn mạnh phần quan trọng: chính vi khuẩn mới kháng thuốc."], ["Whenever + present simple", "Whenever we give an antibiotic", "'Whenever' nghĩa là mỗi khi, diễn tả điều lặp đi lặp lại."], ["Present perfect for result", "have left the field", "Hiện tại hoàn thành nói về kết quả còn tác động đến hiện nay: nhiều công ty đã rời lĩnh vực này."]], "tips": ["Với bài giảng, hãy nghe các từ báo hiệu cấu trúc như 'the first', 'the second', 'the third', 'on the first front' để theo dõi ý chính.", "Chú ý các con số và lời rào đón như 'roughly', 'though', 'contested' vì chúng cho biết mức độ chắc chắn của người nói."]}}, {"id": "lc-602", "lvl": "C1", "kind": "interview", "title": "Why Homes Cost So Much: An Economist Explains", "script": [["Host", "Welcome back to the programme. My guest today is Professor Amira Kaur, an economist who has spent twenty years studying housing markets. Professor, why are houses so expensive in so many cities right now?"], ["Professor Kaur", "Well, the short answer is that demand has outpaced supply for decades. But I'd resist the temptation to blame any single cause, because it's a combination of factors that reinforce each other."], ["Host", "Let's take them one by one. Supply first. Surely we could simply build more homes?"], ["Professor Kaur", "In principle, yes. In practice, building is slowed down by planning rules, the price of land, and a shortage of skilled workers. In this country, it takes on average four years to get a large project from application to the first brick."], ["Host", "Four years. That's remarkable. And what about demand? Some people blame investors and foreign buyers."], ["Professor Kaur", "That's the popular story, and it contains a grain of truth in a few city centres. But the data shows that foreign buyers account for only about three percent of purchases nationally. The bigger driver is low interest rates over the past decade, which made borrowing cheap and pushed prices up."], ["Host", "So cheap money inflated the market."], ["Professor Kaur", "Exactly. And now that rates have risen, we have a paradox. Prices haven't fallen much, because owners are reluctant to sell, but monthly repayments have jumped, so fewer people can afford to buy."], ["Host", "What does that mean for renters? Your recent report said rents have gone up by eleven percent in a single year."], ["Professor Kaur", "Let me be precise: it was ten point eight in the latest figures. When would-be buyers are locked out of ownership, they stay in the rental market for longer, which pushes rents up for everyone."], ["Host", "Some politicians are calling for rent controls. Would that help?"], ["Professor Kaur", "It's tempting, and in the short term it protects the tenants who already have a home. But the evidence from several cities suggests that landlords then sell up or stop maintaining their properties, so over time the supply of rental housing shrinks. Most economists, whatever their politics, are sceptical."], ["Host", "So what would you do instead?"], ["Professor Kaur", "If I had to pick one measure, I'd reform planning, so that approvals for homes near good transport links are quick and predictable. Second, I'd tax empty properties more heavily. Third, I'd invest in social housing, which has been neglected for a generation."], ["Host", "Isn't that expensive?"], ["Professor Kaur", "Of course it is. However, the cost of doing nothing is arguably higher: people spend half their income on housing, they can't move for work, and employers struggle to recruit. That drags down productivity."], ["Host", "Do you think things will improve any time soon?"], ["Professor Kaur", "I'm cautiously pessimistic. Even if we started building at full speed tomorrow, it would take ten years to close the gap. So my advice to young people is not to wait for prices to collapse, because that's unlikely to happen."], ["Host", "Not exactly cheerful news, but very clear. Professor Kaur, thank you for joining us."], ["Professor Kaur", "My pleasure."]], "qs": [{"q": "What is the interview mainly about?", "opts": ["How foreign investors have damaged the national economy", "The reasons for high housing costs and what could be done about them", "Why young people should stop renting and buy property", "The history of planning rules over the past twenty years"], "a": 1, "kind": "gist", "why": "Người dẫn hỏi 'why are houses so expensive' và giáo sư giải thích nguyên nhân rồi đề xuất giải pháp.", "wrong": {"How foreign investors have damaged the national economy": "Giáo sư nói người mua nước ngoài chỉ chiếm khoảng ba phần trăm, nên không phải chủ đề chính.", "Why young people should stop renting and buy property": "Bà không khuyên thuê hay mua, chỉ khuyên đừng chờ giá sụp đổ.", "The history of planning rules over the past twenty years": "Hai mươi năm là thời gian bà nghiên cứu, không phải chủ đề bài phỏng vấn."}}, {"q": "What was the latest figure for the annual rise in rents?", "opts": ["Eleven percent", "Three percent", "Four percent", "Ten point eight percent"], "a": 3, "kind": "number", "why": "Giáo sư sửa lại: 'Let me be precise: it was ten point eight in the latest figures.'", "wrong": {"Eleven percent": "Eleven percent là con số người dẫn nói, nhưng bà đã sửa lại.", "Three percent": "Ba phần trăm là tỷ lệ người mua nước ngoài.", "Four percent": "Bốn năm là thời gian xây dựng một dự án lớn, không phải tăng giá thuê."}}, {"q": "According to Professor Kaur, what is the bigger driver of demand than foreign buyers?", "opts": ["Low interest rates over the past decade", "A shortage of skilled workers", "Higher taxes on empty properties", "Falling wages in city centres"], "a": 0, "kind": "detail", "why": "Bà nói: 'The bigger driver is low interest rates over the past decade'.", "wrong": {"A shortage of skilled workers": "Thiếu thợ lành nghề là yếu tố làm chậm nguồn cung, không phải cầu.", "Higher taxes on empty properties": "Thuế nhà bỏ trống là giải pháp bà đề xuất.", "Falling wages in city centres": "Không có phần nào nói lương giảm ở trung tâm thành phố."}}, {"q": "What does the professor think about rent controls in the long term?", "opts": ["They would solve the housing shortage within ten years.", "They would make landlords build more properties.", "They may reduce the amount of rental housing available.", "They are supported by most economists."], "a": 2, "kind": "inference", "why": "Bà nói chủ nhà 'sell up or stop maintaining their properties, so over time the supply of rental housing shrinks'.", "wrong": {"They would solve the housing shortage within ten years.": "Bà không nói kiểm soát tiền thuê giải quyết thiếu hụt nhà.", "They would make landlords build more properties.": "Bà nói chủ nhà sẽ bán hoặc bỏ bảo trì, không xây thêm.", "They are supported by most economists.": "Bà nói 'Most economists ... are sceptical', tức là đa số không ủng hộ."}}, {"q": "Which measure would she choose if she could only pick one?", "opts": ["Investing in social housing", "Taxing empty properties", "Raising interest rates", "Reforming planning so that approvals are quicker"], "a": 3, "kind": "detail", "why": "Bà nói: 'If I had to pick one measure, I'd reform planning'.", "wrong": {"Investing in social housing": "Nhà ở xã hội là biện pháp thứ ba bà nêu.", "Taxing empty properties": "Đánh thuế nhà bỏ trống là biện pháp thứ hai.", "Raising interest rates": "Bà không đề xuất tăng lãi suất như một giải pháp."}}, {"q": "What does she advise young people to do?", "opts": ["To wait until prices fall next year", "Not to wait for prices to collapse", "To move to cities with cheaper land", "To invest in rental properties"], "a": 1, "kind": "next-step", "why": "Bà nói: 'my advice to young people is not to wait for prices to collapse'.", "wrong": {"To wait until prices fall next year": "Bà cho rằng giá sụp đổ là điều khó xảy ra, nên không khuyên chờ.", "To move to cities with cheaper land": "Bà không nói về việc chuyển đến thành phố khác.", "To invest in rental properties": "Bà không khuyên đầu tư bất động sản cho thuê."}}], "notes": {"vocab": [["outpaced", "vượt qua, tăng nhanh hơn"], ["account for", "chiếm (một tỷ lệ)"], ["locked out of", "bị loại ra khỏi, không tiếp cận được"], ["rent controls", "kiểm soát giá thuê nhà"], ["sceptical", "hoài nghi"], ["social housing", "nhà ở xã hội"], ["productivity", "năng suất"]], "grammar": [["Second conditional", "Even if we started building at full speed tomorrow, it would take ten years", "Câu điều kiện loại 2 nói về tình huống giả định ít có thể xảy ra: 'even if + past, would + động từ'."], ["now that", "now that rates have risen", "'Now that' nghĩa là vì bây giờ, dùng để nêu lý do từ tình huống mới."], ["Relative clause with 'which'", "which made borrowing cheap and pushed prices up", "Mệnh đề quan hệ 'which' bổ sung thông tin cho cả mệnh đề trước."]], "tips": ["Khi nghe phỏng vấn, chú ý những lúc người nói tự sửa số liệu như 'let me be precise', vì đáp án thường là số sau khi sửa.", "Nghe các từ chỉ thứ tự như 'first', 'second', 'third' để nắm các giải pháp theo từng thứ tự."]}}, {"id": "lc-603", "lvl": "C1", "kind": "conversation", "title": "Making Mr Walsh's Discharge Safe", "script": [["Dr Patel", "Right, let's start. Next on the list is Mr Walsh in bed twelve. He's seventy eight, admitted nine days ago with pneumonia, and his chest is much clearer now. Medically, I'm happy for him to go home, but I understand there are some concerns."], ["Grace", "Yes, from the nursing side, I'm not convinced he's ready. He's been steady in the morning, but he got quite breathless yesterday afternoon when he walked to the toilet, and his oxygen level dropped to ninety one percent."], ["Dr Patel", "Ninety one on room air? That's a little lower than I'd like. Was it just after exertion?"], ["Grace", "It was, and it recovered to ninety four within a few minutes. But he lives alone, and his daughter is abroad until the end of the month."], ["Sam", "That's what worries me too. I assessed him on Tuesday. He can manage a flight of stairs with supervision, but he's quite unsteady if he turns quickly. I'd say he's at moderate risk of falling, and his stairs at home don't have a second rail."], ["Dr Patel", "Okay. So the question is whether we delay discharge or find a way of making it safe. Keeping him in hospital isn't risk-free either. He could lose muscle strength and pick up another infection."], ["Grace", "Fair point. Could the community team step in? A short-term care package, with someone calling in twice a day?"], ["Sam", "I'd suggest a home visit by an occupational therapist first, to fit a second stair rail and a raised toilet seat. I've already put in the referral, and they said they could come on Thursday."], ["Dr Patel", "Good. And the social worker?"], ["Grace", "Maria says the earliest start for carers is Friday. Originally she thought Monday, but a space has opened up."], ["Dr Patel", "Excellent. So realistically, we're looking at Friday for discharge, provided the visit goes well and his oxygen level stays above ninety two on walking."], ["Sam", "I'd want him to do a walking test on Thursday morning, too, so we have a baseline."], ["Dr Patel", "Agreed. Grace, can you make sure he gets his chest physio exercises and explain the warning signs to him? Fever coming back, more breathlessness, confusion."], ["Grace", "Of course. I'll use teach-back with him so we know he's understood, as he tends to nod along even when he hasn't. And I'll ring his daughter this evening so she can join a video call before he leaves."], ["Dr Patel", "Lovely. I'll prepare the discharge summary and book a follow-up with his GP within a week. And a repeat chest X-ray in six weeks, to make sure the shadow has cleared."], ["Sam", "Sounds like a good plan to me, and I'll write my mobility notes up before Thursday."], ["Dr Patel", "Thanks, everyone. Next, bed fourteen."]], "qs": [{"q": "What is the purpose of this part of the meeting?", "opts": ["To decide whether Mr Walsh needs a chest operation", "To decide how to make Mr Walsh's discharge from hospital safe", "To arrange a transfer to another hospital", "To review Mr Walsh's antibiotic treatment"], "a": 1, "kind": "gist", "why": "Bác sĩ Patel nói: 'the question is whether we delay discharge or find a way of making it safe', cả nhóm bàn cách xuất viện an toàn.", "wrong": {"To decide whether Mr Walsh needs a chest operation": "Không ai nhắc đến phẫu thuật ngực.", "To arrange a transfer to another hospital": "Không có đề cập đến chuyển viện.", "To review Mr Walsh's antibiotic treatment": "Cuộc họp không bàn về điều trị kháng sinh."}}, {"q": "What was Mr Walsh's lowest oxygen reading?", "opts": ["Ninety two percent", "Ninety four percent", "Ninety five percent", "Ninety one percent"], "a": 3, "kind": "number", "why": "Grace nói: 'his oxygen level dropped to ninety one percent'.", "wrong": {"Ninety two percent": "Ninety two là ngưỡng cần giữ khi đi bộ, không phải chỉ số thấp nhất.", "Ninety four percent": "Ninety four là mức hồi phục sau vài phút.", "Ninety five percent": "Ninety five không được nhắc đến."}}, {"q": "What worries the physiotherapist about Mr Walsh at home?", "opts": ["He is unsteady when turning and his stairs have only one rail.", "He cannot climb stairs even with supervision.", "He has forgotten how to use his medication.", "His daughter has refused to look after him."], "a": 0, "kind": "detail", "why": "Sam nói: 'he's quite unsteady if he turns quickly' và 'his stairs at home don't have a second rail'.", "wrong": {"He cannot climb stairs even with supervision.": "Sam nói ông có thể đi một tầng cầu thang với sự giám sát.", "He has forgotten how to use his medication.": "Không nói đến chuyện quên dùng thuốc.", "His daughter has refused to look after him.": "Con gái ông đang ở nước ngoài, không phải từ chối chăm sóc."}}, {"q": "On which day is Mr Walsh most likely to be discharged?", "opts": ["Monday", "Tuesday", "Friday", "Thursday"], "a": 2, "kind": "number", "why": "Bác sĩ Patel nói: 'we're looking at Friday for discharge, provided the visit goes well'.", "wrong": {"Monday": "Thứ Hai là ngày nhân viên xã hội ban đầu nghĩ, nhưng đã đổi.", "Tuesday": "Thứ Ba là ngày Sam đánh giá ông.", "Thursday": "Thứ Năm là ngày đến thăm nhà và làm bài đi bộ."}}, {"q": "Why does Grace plan to use teach-back with Mr Walsh?", "opts": ["He is too deaf to hear the instructions.", "His daughter asked her to do it.", "He refuses to follow the physio exercises.", "He may appear to understand when he does not."], "a": 3, "kind": "inference", "why": "Grace nói ông 'tends to nod along even when he hasn't' understood, nên cần kiểm tra bằng teach-back.", "wrong": {"He is too deaf to hear the instructions.": "Không có thông tin nào nói ông bị điếc.", "His daughter asked her to do it.": "Việc này do Grace tự đề xuất, không phải con gái yêu cầu.", "He refuses to follow the physio exercises.": "Không nói ông từ chối tập vật lý trị liệu."}}, {"q": "What will Grace do this evening?", "opts": ["Teach Mr Walsh the warning signs of infection", "Phone Mr Walsh's daughter about a video call", "Book an appointment with his GP", "Fit a second stair rail at his home"], "a": 1, "kind": "next-step", "why": "Grace nói: 'I'll ring his daughter this evening so she can join a video call'.", "wrong": {"Teach Mr Walsh the warning signs of infection": "Dạy dấu hiệu cảnh báo là việc chung của Grace nhưng không nói là tối nay.", "Book an appointment with his GP": "Bác sĩ Patel mới là người đặt lịch hẹn với bác sĩ gia đình.", "Fit a second stair rail at his home": "Lắp tay vịn là việc của nhà trị liệu nghề nghiệp."}}], "notes": {"vocab": [["breathless", "khó thở, hụt hơi"], ["exertion", "sự gắng sức"], ["referral", "giấy giới thiệu, chuyển tuyến"], ["care package", "gói chăm sóc tại nhà"], ["baseline", "mức cơ bản để so sánh"], ["teach-back", "kỹ thuật yêu cầu bệnh nhân nhắc lại để kiểm tra mức hiểu"]], "grammar": [["Provided (that)", "provided the visit goes well", "'Provided' nghĩa là với điều kiện, dùng như 'if' nhưng nhấn mạnh điều kiện bắt buộc."], ["Suggest + noun", "I'd suggest a home visit", "'Suggest' đi với danh từ hoặc V-ing để đưa ra đề xuất lịch sự."], ["Habitual 'tends to'", "he tends to nod along even when he hasn't", "'Tends to' diễn tả thói quen hay xảy ra."]], "tips": ["Trong cuộc họp, chú ý các thay đổi như 'originally ... but', vì đáp án thường là thông tin sau khi thay đổi.", "Nghe kỹ phần phân công việc, thường có cụm như 'I'll ...' và tên người, để biết ai làm gì."]}}, {"id": "lc-604", "lvl": "C1", "kind": "talk", "title": "Creativity Is a Habit, Not a Gift", "script": [["Elena", "Thank you, and good evening. I'd like to begin with a confession. For most of my childhood, I was told I wasn't creative, because I couldn't draw. It took me thirty years to realise how wrong that was."], ["Elena", "Here's the idea I want to explore tonight. Creativity isn't a talent that some people have and others lack. It's a habit, a set of behaviours, and, crucially, it responds to the environment we put ourselves in."], ["Elena", "Let's start with the myth of the lone genius. We love the story of the inventor struck by a sudden flash of inspiration in the bath."], ["Elena", "But when historians study those stories closely, they find years of preparation, dozens of failed attempts, and, almost always, conversations with other people."], ["Elena", "Take the Wright brothers. Everyone remembers their first flight. Far fewer people remember that they tested more than two hundred wing shapes in a homemade wind tunnel first."], ["Elena", "The second point is about constraints. Counterintuitively, we tend to be more inventive when we have less, not more."], ["Elena", "Give a team unlimited budget and unlimited time, and they'll often produce something bland. Give them a tight deadline and a small budget, and they're forced to question their assumptions."], ["Elena", "I saw this myself when I ran a design studio. One year we had to launch a product in six weeks instead of six months. Everyone predicted a disaster. It turned out to be our best-selling product, precisely because we had no time to add features that nobody needed."], ["Elena", "Third, creativity needs boredom. Now, I know that's an unpopular thing to say in an age of constant notifications."], ["Elena", "But some of my best ideas have arrived while I was washing up or walking the dog, when my mind was free to wander. If we fill every spare moment with a screen, we deprive ourselves of that space."], ["Elena", "Fourth, and this is the one I find most difficult, creativity requires a willingness to fail publicly. Research on schoolchildren suggests that by the age of ten, many have stopped offering unusual answers, because they've learned that being wrong carries a social cost."], ["Elena", "In my studio, we introduced something called the failure list. Every person wrote down three things that had gone wrong that year and what they learned from each. Our boss went first, and, to be honest, that was what made it work. People copy what leaders do, not what leaders say."], ["Elena", "Now, I don't want to romanticise any of this. Creative work is often frustrating, and there are long periods when nothing seems to come. Most of the time, we simply have to show up and get to work."], ["Elena", "So let me leave you with three small experiments. This week, set yourself an artificial limit on something you normally do without limits."], ["Elena", "Second, schedule fifteen minutes of doing nothing at all, without your phone. And third, share one unfinished idea with a colleague, even though it feels uncomfortable."], ["Elena", "If you do those three things, I can't promise a breakthrough. But I can promise that you'll start to notice how creative you already are. Thank you very much."]], "qs": [{"q": "What is the speaker's central argument?", "opts": ["Creativity depends mainly on having a large budget and plenty of time.", "Creativity is a set of habits that can be developed, not a fixed talent.", "Only a few lone geniuses are capable of real invention.", "Children are naturally more creative than adults and always will be."], "a": 1, "kind": "gist", "why": "Người nói nói: 'Creativity isn't a talent that some people have and others lack. It's a habit'.", "wrong": {"Creativity depends mainly on having a large budget and plenty of time.": "Bà nói ngược lại: có ít nguồn lực lại thường sáng tạo hơn.", "Only a few lone geniuses are capable of real invention.": "Bà bác bỏ 'the myth of the lone genius'.", "Children are naturally more creative than adults and always will be.": "Bà không nói trẻ em luôn sáng tạo hơn; bà chỉ nói trẻ ngừng đưa ra câu trả lời khác thường vì sợ sai."}}, {"q": "Why does the speaker mention the Wright brothers?", "opts": ["To show that flying was invented by accident", "To show that inventors work best alone", "To show that wind tunnels are expensive", "To show that success came after a great deal of preparation"], "a": 3, "kind": "detail", "why": "Bà nói họ 'tested more than two hundred wing shapes' trước chuyến bay đầu tiên, nghĩa là có nhiều chuẩn bị.", "wrong": {"To show that flying was invented by accident": "Bà không nói việc phát minh là ngẫu nhiên.", "To show that inventors work best alone": "Bà nói các nhà phát minh thường trò chuyện với người khác.", "To show that wind tunnels are expensive": "Bà không nói về chi phí của hầm gió."}}, {"q": "How long did the team have to launch the product in the speaker's story?", "opts": ["Six weeks", "Six months", "Two hundred days", "Fifteen weeks"], "a": 0, "kind": "number", "why": "Bà nói: 'we had to launch a product in six weeks instead of six months'.", "wrong": {"Six months": "Sáu tháng là thời gian thông thường, không phải thời hạn thực tế.", "Two hundred days": "Hai trăm là số kiểu cánh của anh em nhà Wright.", "Fifteen weeks": "Mười lăm là số phút của thử nghiệm không làm gì."}}, {"q": "What does the speaker say about working with constraints?", "opts": ["Limits always produce bland ideas.", "Limits make teams work more slowly.", "Tight limits force people to question their assumptions.", "Limits should be avoided in design studios."], "a": 2, "kind": "detail", "why": "Bà nói với thời hạn chặt và ngân sách nhỏ, 'they're forced to question their assumptions'.", "wrong": {"Limits always produce bland ideas.": "Bà nói ngân sách và thời gian không giới hạn mới thường tạo ra ý tưởng nhạt.", "Limits make teams work more slowly.": "Đội của bà đã làm xong nhanh hơn và có sản phẩm bán chạy.", "Limits should be avoided in design studios.": "Bà ủng hộ giới hạn, không phải tránh chúng."}}, {"q": "Why does the speaker say it was important that the boss went first with the failure list?", "opts": ["The boss had made the most mistakes that year.", "The list was a requirement of the company.", "Staff were afraid of the boss and obeyed.", "Staff learn from what leaders actually do."], "a": 3, "kind": "inference", "why": "Bà nói 'Our boss went first... that was what made it work. People copy what leaders do, not what leaders say.'", "wrong": {"The boss had made the most mistakes that year.": "Không có thông tin về việc sếp sai nhiều nhất.", "The list was a requirement of the company.": "Không nói đây là quy định của công ty.", "Staff were afraid of the boss and obeyed.": "Bà nói người ta bắt chước hành động, không phải vì sợ."}}, {"q": "Which of the three experiments does the speaker suggest?", "opts": ["Draw something every day for a month", "Spend fifteen minutes doing nothing without a phone", "Read about the Wright brothers", "Remove all deadlines from your projects"], "a": 1, "kind": "next-step", "why": "Bà nói: 'schedule fifteen minutes of doing nothing at all, without your phone'.", "wrong": {"Draw something every day for a month": "Bà không bảo vẽ mỗi ngày.", "Read about the Wright brothers": "Bà không giao việc đọc về anh em nhà Wright.", "Remove all deadlines from your projects": "Bà khuyên đặt giới hạn nhân tạo, không phải bỏ thời hạn."}}], "notes": {"vocab": [["lone genius", "thiên tài đơn độc"], ["constraints", "ràng buộc, giới hạn"], ["bland", "nhạt nhẽo, thiếu thú vị"], ["assumptions", "giả định"], ["romanticise", "lãng mạn hóa, thổi phồng vẻ đẹp"], ["breakthrough", "bước đột phá"]], "grammar": [["Imperative + and (conditional)", "Give a team unlimited budget and unlimited time, and they'll often produce something bland", "Câu mệnh lệnh + 'and' + kết quả có nghĩa như câu điều kiện: nếu bạn làm..., thì..."], ["It takes + person + time + to", "It took me thirty years to realise how wrong that was", "Cấu trúc 'It takes/took + người + thời gian + to + động từ' nói về thời gian cần để làm gì."], ["Nominal relative clause", "People copy what leaders do, not what leaders say", "'What' mở đầu mệnh đề danh từ, nghĩa là 'những điều mà'."]], "tips": ["Trong bài diễn thuyết, chú ý các từ chỉ thứ tự như 'the second point', 'third', 'fourth' để chia ý.", "Nghe kỹ các ví dụ cá nhân và con số, thường có đối chiếu như 'six weeks instead of six months', cần phân biệt rõ."]}}, {"id": "lc-605", "lvl": "C1", "kind": "conversation", "title": "Planning the Methodology Chapter", "script": [["Dr Okafor", "Come in, Lena, take a seat. So, I've read the draft of your second chapter over the weekend. Before I give you my comments, how do you feel it went?"], ["Lena", "Honestly, I'm a bit torn. I think the literature review is solid, but I struggled with the methodology section. I keep going back and forth on whether to use interviews or a survey."], ["Dr Okafor", "That's useful self-awareness, and I'd agree with you on both counts. The review is well structured, although it leans heavily on studies from the last five years. You'll need to acknowledge the earlier work, otherwise a reviewer might think you've overlooked it."], ["Lena", "Right. I assumed older papers wouldn't be relevant, but I can see how that looks."], ["Dr Okafor", "Now, the methodology. Tell me what you want to find out."], ["Lena", "I want to understand why first-generation students drop out in their first year. My instinct is that a survey would give me numbers, but interviews would give me the reasons."], ["Dr Okafor", "Both have merit. A survey of, say, four hundred students would let you generalise, but you'd have a rather shallow picture. Interviews give depth, but with fifteen participants you couldn't claim the findings apply to everyone. Have you considered a mixed-methods design?"], ["Lena", "I did, but I worried that it's too ambitious for a one-year master's. I only have until June to submit."], ["Dr Okafor", "That's a legitimate concern. Here's a thought: run a short survey first, perhaps twenty questions, then interview eight to ten students chosen from the survey respondents. It's more manageable than it sounds, and the two parts inform each other."], ["Lena", "That makes sense. Would the ethics committee need to approve both parts?"], ["Dr Okafor", "Yes, and that's the timing issue. Their next meeting is on the fourteenth of November, and the one after that isn't until January. Applications close two weeks before a meeting, so you'd need to submit by the thirty first of October."], ["Lena", "Then I'd better get started. Could you point me to an example of a good application?"], ["Dr Okafor", "I'll send you the form and a successful example this afternoon. Draft the participant information sheet first, since that's the part students find hardest."], ["Lena", "Thank you. One more thing, if I may. My second supervisor has suggested I change my research question, which is a bit confusing. He wants me to focus on a single university instead of three."], ["Dr Okafor", "I'd lean towards his view, to be frank. A narrower focus would make your sample more coherent. But let's discuss it with him on Friday rather than decide between ourselves."], ["Lena", "Fine, I'll prepare a one-page summary of both options."], ["Dr Okafor", "Perfect. Let's meet again in two weeks."]], "qs": [{"q": "What is the main purpose of the meeting?", "opts": ["To tell Lena that her thesis has been rejected", "To discuss feedback on a draft chapter and plan the research method", "To choose a new second supervisor for Lena", "To prepare Lena for an ethics committee interview"], "a": 1, "kind": "gist", "why": "Dr Okafor đã đọc bản nháp chương hai, góp ý phần tổng quan tài liệu rồi bàn về phương pháp nghiên cứu.", "wrong": {"To tell Lena that her thesis has been rejected": "Không có gì cho thấy luận văn bị từ chối.", "To choose a new second supervisor for Lena": "Không bàn về đổi người hướng dẫn thứ hai, chỉ bàn về câu hỏi nghiên cứu.", "To prepare Lena for an ethics committee interview": "Ủy ban đạo đức chỉ được nhắc đến liên quan đến thời hạn nộp đơn."}}, {"q": "What criticism does Dr Okafor make of the literature review?", "opts": ["It is badly organised.", "It is far too long.", "It ignores studies from other countries.", "It relies too much on recent studies."], "a": 3, "kind": "detail", "why": "Ông nói: 'it leans heavily on studies from the last five years. You'll need to acknowledge the earlier work'.", "wrong": {"It is badly organised.": "Ông nói tổng quan được cấu trúc tốt.", "It is far too long.": "Ông không nhắc đến độ dài.", "It ignores studies from other countries.": "Ông không nói về nghiên cứu ở nước khác."}}, {"q": "How many students does Dr Okafor suggest interviewing?", "opts": ["Eight to ten", "Fifteen", "Twenty", "Four hundred"], "a": 0, "kind": "number", "why": "Ông nói: 'interview eight to ten students chosen from the survey respondents'.", "wrong": {"Fifteen": "Mười lăm là số người tham gia phỏng vấn trong ví dụ về hạn chế.", "Twenty": "Hai mươi là số câu hỏi khảo sát.", "Four hundred": "Bốn trăm là quy mô khảo sát ví dụ."}}, {"q": "By what date must Lena submit the ethics application to make the November meeting?", "opts": ["The fourteenth of November", "The first of January", "The thirty first of October", "The thirty first of June"], "a": 2, "kind": "number", "why": "Ông nói đơn đóng hai tuần trước cuộc họp ngày 14/11, nên 'you'd need to submit by the thirty first of October'.", "wrong": {"The fourteenth of November": "Ngày 14 tháng 11 là ngày họp, đơn phải nộp trước đó.", "The first of January": "Tháng Một là cuộc họp kế tiếp, Lena muốn tránh bị lỡ.", "The thirty first of June": "Tháng Sáu là hạn nộp luận văn, và tháng Sáu không có ngày ba mươi mốt."}}, {"q": "What is Dr Okafor's view of the second supervisor's suggestion?", "opts": ["He thinks it is a serious mistake.", "He wants Lena to ignore it completely.", "He has no opinion on the matter.", "He largely agrees but wants to discuss it with him first."], "a": 3, "kind": "inference", "why": "Ông nói: 'I'd lean towards his view' nhưng muốn 'discuss it with him on Friday rather than decide between ourselves'.", "wrong": {"He thinks it is a serious mistake.": "Ông nghiêng về quan điểm của người kia, không coi là sai lầm.", "He wants Lena to ignore it completely.": "Ông muốn thảo luận chứ không bỏ qua.", "He has no opinion on the matter.": "Ông có ý kiến rõ ràng là nghiêng về phía người kia."}}, {"q": "What will Dr Okafor send to Lena today?", "opts": ["A list of earlier studies to cite", "The ethics application form and a successful example", "A summary of both research options", "The draft of the information sheet"], "a": 1, "kind": "next-step", "why": "Ông nói: 'I'll send you the form and a successful example this afternoon'.", "wrong": {"A list of earlier studies to cite": "Lena sẽ tự tìm thêm các nghiên cứu cũ để trích dẫn.", "A summary of both research options": "Lena mới là người chuẩn bị bản tóm tắt hai phương án.", "The draft of the information sheet": "Lena phải tự soạn bản thông tin cho người tham gia."}}], "notes": {"vocab": [["torn", "phân vân, lưỡng lự"], ["generalise", "khái quát hóa"], ["mixed-methods design", "thiết kế nghiên cứu kết hợp định lượng và định tính"], ["respondents", "người trả lời khảo sát"], ["ethics committee", "ủy ban đạo đức"], ["coherent", "chặt chẽ, nhất quán"], ["lean towards", "nghiêng về"]], "grammar": [["otherwise", "otherwise a reviewer might think you've overlooked it", "'Otherwise' nghĩa là nếu không thì, nêu hậu quả của việc không làm điều vừa nói."], ["had better", "I'd better get started", "'Had better' dùng để nói nên làm gì, mang tính cấp bách."], ["Present perfect question", "Have you considered a mixed-methods design?", "Hiện tại hoàn thành dùng để hỏi về trải nghiệm hoặc việc đã cân nhắc đến thời điểm nói."]], "tips": ["Khi nghe cuộc họp có ngày tháng, chú ý quy tắc như 'two weeks before' để tự tính ngày đúng, vì đáp án có thể không được nói trực tiếp.", "Nghe các cụm lịch sự như 'I'd lean towards', 'to be frank' để nhận ra quan điểm thật của người nói."]}}, {"id": "lc-606", "lvl": "C1", "kind": "interview", "title": "Surgery Is a Team Sport", "script": [["Host", "Today I'm joined by Mr Daniel Adebayo, a consultant trauma surgeon with over twenty years' experience. Mr Adebayo, when people picture an operating theatre, they imagine the surgeon as the hero. Is that fair?"], ["Mr Adebayo", "Not at all, I'm afraid. It's a flattering image, but it's misleading. A complex operation might involve eight or nine people, and if any one of them isn't functioning well, the patient is at risk. Surgery is a team sport."], ["Host", "What happens when a case becomes an emergency?"], ["Mr Adebayo", "That's when the teamwork is really tested. Imagine a patient bleeding heavily after a road accident. Everything speeds up, voices get louder, and there's a temptation to bark orders. Paradoxically, that's precisely when you need to slow down your communication, not speed it up."], ["Host", "Slow down? How so?"], ["Mr Adebayo", "We use closed-loop communication. If I say, give me two units of blood, the anaesthetist repeats it back, two units of blood, and then confirms when it's done. It sounds pedantic, but it prevents errors that arise when instructions are misheard in a noisy room."], ["Host", "I read that checklists have made a big difference too."], ["Mr Adebayo", "They have. Before every operation, we pause for a briefing, the so-called time out, where we confirm the patient's identity, the procedure, and the site of the operation. Studies have shown that it reduces complications by about a third. Early on, some surgeons, myself included, found it irritating. Now I wouldn't operate without it."], ["Host", "Did anything change your mind?"], ["Mr Adebayo", "A near miss. Years ago, we nearly operated on the wrong side, because two people had assumed someone else had checked. A junior nurse spoke up, and she was right. That experience taught me that the most junior person in the room can see what I can't."], ["Host", "But speaking up to a senior surgeon takes courage."], ["Mr Adebayo", "It does, and that's a leader's responsibility. At the start of every list, I say, if you see something that worries you, tell me, and I promise I won't be offended. Said once, it's just words. What matters is how I react the first time somebody does."], ["Host", "And how do you cope personally with the stress?"], ["Mr Adebayo", "Preparation is the biggest factor. I mentally rehearse the difficult steps beforehand. And after a bad case, we hold a debrief within twenty four hours, not to assign blame but to ask what we'd do differently. I've also learned to take a short break when I'm exhausted, which I resisted for years, because I thought it showed weakness."], ["Host", "What advice would you give to medical students who hope to become surgeons?"], ["Mr Adebayo", "Learn to listen. Technical skill matters, obviously, but it can be taught. Humility is harder. And find colleagues who'll tell you the truth, even when it's uncomfortable."], ["Host", "Mr Adebayo, thank you very much."], ["Mr Adebayo", "Thank you for having me."]], "qs": [{"q": "What is the main point Mr Adebayo makes about surgery?", "opts": ["Surgeons should make decisions quickly without consulting others.", "Good outcomes depend on communication and teamwork, not on the surgeon alone.", "Technical skill is the only quality a surgeon needs.", "Checklists are unnecessary for experienced surgeons."], "a": 1, "kind": "gist", "why": "Ông nói hình ảnh người hùng là 'misleading' và 'Surgery is a team sport', rồi bàn về giao tiếp, danh sách kiểm tra và dám lên tiếng.", "wrong": {"Surgeons should make decisions quickly without consulting others.": "Ông nói trong tình huống khẩn cấp cần chậm lại giao tiếp.", "Technical skill is the only quality a surgeon needs.": "Ông nói kỹ năng kỹ thuật có thể dạy được, khiêm tốn mới khó hơn.", "Checklists are unnecessary for experienced surgeons.": "Ông nói giờ ông không mổ nếu thiếu time out."}}, {"q": "Why does the anaesthetist repeat instructions back?", "opts": ["To show respect to the surgeon", "To give the surgeon time to think", "To record the instructions for legal reasons", "To prevent errors caused by misheard instructions"], "a": 3, "kind": "detail", "why": "Ông nói: 'it prevents errors that arise when instructions are misheard in a noisy room'.", "wrong": {"To show respect to the surgeon": "Ông không nói đây là để thể hiện sự tôn trọng.", "To give the surgeon time to think": "Mục đích là tránh sai sót, không phải cho thời gian suy nghĩ.", "To record the instructions for legal reasons": "Ông không nhắc đến lý do pháp lý."}}, {"q": "By how much do studies show the time out reduces complications?", "opts": ["About a third", "About a half", "About twenty four percent", "About eight or nine percent"], "a": 0, "kind": "number", "why": "Ông nói: 'Studies have shown that it reduces complications by about a third'.", "wrong": {"About a half": "Một nửa không được nhắc đến.", "About twenty four percent": "Hai mươi bốn là số giờ trước buổi debrief.", "About eight or nine percent": "Tám hoặc chín là số người trong một ca mổ phức tạp."}}, {"q": "What did the near miss teach Mr Adebayo?", "opts": ["Junior staff should not be allowed to speak in theatre.", "Every operation needs two senior surgeons.", "The most junior person may notice things he cannot.", "Nurses should check the patient's identity alone."], "a": 2, "kind": "detail", "why": "Ông nói: 'the most junior person in the room can see what I can't'.", "wrong": {"Junior staff should not be allowed to speak in theatre.": "Ông kết luận ngược lại: nhân viên trẻ cần được khuyến khích lên tiếng.", "Every operation needs two senior surgeons.": "Ông không nói cần hai bác sĩ phẫu thuật cấp cao.", "Nurses should check the patient's identity alone.": "Không nói y tá nên kiểm tra một mình."}}, {"q": "Why does he say that how he reacts the first time somebody speaks up is important?", "opts": ["He wants to punish those who make mistakes.", "He believes that promises are always sufficient.", "He prefers staff to remain silent in theatre.", "Staff judge whether it is safe to speak up by his response."], "a": 3, "kind": "inference", "why": "Ông nói 'Said once, it's just words. What matters is how I react the first time somebody does', nghĩa là phản ứng thực tế quyết định nhân viên có dám nói tiếp hay không.", "wrong": {"He wants to punish those who make mistakes.": "Ông nói debrief không nhằm đổ lỗi.", "He believes that promises are always sufficient.": "Ông nói lời hứa chỉ là lời nói nếu không đi kèm hành động.", "He prefers staff to remain silent in theatre.": "Ông muốn nhân viên lên tiếng khi lo ngại."}}, {"q": "What advice does he give to medical students who want to be surgeons?", "opts": ["Practise operating techniques every day", "Learn to listen and look for honest colleagues", "Never take a break during a long case", "Avoid asking the nursing team for help"], "a": 1, "kind": "next-step", "why": "Ông khuyên: 'Learn to listen' và 'find colleagues who'll tell you the truth'.", "wrong": {"Practise operating techniques every day": "Ông nói kỹ năng kỹ thuật dạy được, nên không phải ưu tiên.", "Never take a break during a long case": "Ông nói ông đã học cách nghỉ ngắn khi kiệt sức.", "Avoid asking the nursing team for help": "Ông nhấn mạnh cả nhóm cùng làm việc, không tránh nhờ giúp đỡ."}}], "notes": {"vocab": [["operating theatre", "phòng mổ"], ["closed-loop communication", "giao tiếp vòng khép kín, người nhận nhắc lại để xác nhận"], ["pedantic", "tỉ mỉ quá mức"], ["time out", "bước dừng lại kiểm tra trước ca mổ"], ["near miss", "sự cố suýt xảy ra"], ["debrief", "buổi rút kinh nghiệm sau ca"], ["humility", "sự khiêm tốn"]], "grammar": [["Past perfect", "two people had assumed someone else had checked", "Quá khứ hoàn thành diễn tả hành động xảy ra trước một hành động quá khứ khác."], ["Present perfect with 'studies'", "Studies have shown that it reduces complications", "Hiện tại hoàn thành dùng cho kết quả nghiên cứu còn đúng đến hiện nay."], ["Zero conditional", "if any one of them isn't functioning well, the patient is at risk", "Câu điều kiện loại 0 diễn tả sự thật hoặc quy luật chung: if + hiện tại, hiện tại."]], "tips": ["Trong phỏng vấn, nghe câu hỏi của người dẫn để đoán đoạn trả lời sẽ nói về gì, rồi tập trung vào ví dụ cụ thể của khách mời.", "Chú ý các từ báo hiệu thay đổi như 'early on... now', 'at first', vì chúng cho thấy quan điểm đã đổi."]}}]);
